    fn emit_automatic_jsx_prelude(&mut self) {
        if !self.automatic_jsx.any() {
            return;
        }
        let development = self.settings.jsx == JsxEmit::ReactJsxDev;
        let runtime = if development {
            "react/jsx-dev-runtime"
        } else {
            "react/jsx-runtime"
        };
        if self.is_external_module {
            if self.commonjs_module_transform {
                self.writer.write("const ");
                self.writer.write(self.automatic_jsx_runtime_binding());
                self.writer.write(" = require(");
                write_quoted(&mut self.writer, runtime);
                self.writer.write(");");
                self.writer.newline();
            } else {
                self.writer.write("import { ");
                let mut first = true;
                for (used, imported, local) in [
                    (development, "jsxDEV", "_jsxDEV"),
                    (!development && self.automatic_jsx.jsx, "jsx", "_jsx"),
                    (!development && self.automatic_jsx.jsxs, "jsxs", "_jsxs"),
                    (self.automatic_jsx.fragment, "Fragment", "_Fragment"),
                ] {
                    if !used {
                        continue;
                    }
                    if !first {
                        self.writer.write(", ");
                    }
                    first = false;
                    self.writer.write(imported);
                    self.writer.write(" as ");
                    self.writer.write(local);
                }
                self.writer.write(" } from ");
                write_quoted(&mut self.writer, runtime);
                self.writer.write(";");
                self.writer.newline();
            }
        }
        if development {
            self.writer.write("const _jsxFileName = ");
            write_quoted(&mut self.writer, source_basename(self.source_name));
            self.writer.write(";");
            self.writer.newline();
        }
    }

    fn node(&self, id: NodeId) -> Result<&Node, EmitError> {
        self.arena.get(id).ok_or(EmitError {
            node: id,
            kind: SyntaxKind::Unknown,
        })
    }

    const fn unsupported(id: NodeId, kind: SyntaxKind) -> EmitError {
        EmitError { node: id, kind }
    }

    #[allow(clippy::too_many_lines)]
    fn commonjs_preinitialized_export_names(&self, statements: &NodeList) -> Vec<String> {
        let mut names = Vec::new();
        let mut seen = HashSet::new();
        for statement in &statements.nodes {
            let Some(node) = self.arena.get(*statement) else {
                continue;
            };
            if let NodeData::ExportDeclaration(export) = &node.data
                && self.import_runtime_meanings.get(statement) == Some(&false)
                && self.named_export_clause_has_runtime_specifier(export) != Some(true)
                && !self.const_enum_emit_mode.preserves_declarations()
            {
                continue;
            }
            if declaration_has_modifier(self.arena, node, SyntaxKind::DeclareKeyword) {
                continue;
            }
            if is_const_enum_declaration(self.arena, node)
                && !self.const_enum_emit_mode.preserves_declarations()
            {
                continue;
            }
            let exported = declaration_has_modifier(self.arena, node, SyntaxKind::ExportKeyword);
            let default_export =
                declaration_has_modifier(self.arena, node, SyntaxKind::DefaultKeyword);
            match &node.data {
                NodeData::ClassDeclaration(class) if exported => {
                    let name = if default_export {
                        None
                    } else {
                        class
                            .name
                            .and_then(|name| declaration_name_text(self.arena, name))
                    };
                    if let Some(name) = name
                        && seen.insert(name.to_owned())
                    {
                        names.push(name.to_owned());
                    }
                }
                NodeData::EnumDeclaration(enumeration) if exported => {
                    if let Some(name) = declaration_name_text(self.arena, enumeration.name)
                        && seen.insert(name.to_owned())
                    {
                        names.push(name.to_owned());
                    }
                }
                NodeData::ModuleDeclaration(module)
                    if exported
                        && self.namespace_has_runtime_contents(module, &mut HashSet::new()) =>
                {
                    if let Some(name) = declaration_name_text(self.arena, module.name)
                        && seen.insert(name.to_owned())
                    {
                        names.push(name.to_owned());
                    }
                }
                NodeData::ImportEqualsDeclaration(import)
                    if exported
                        && self.settings.module == ModuleKind::CommonJs
                        && !self.is_external_import_equals(import)
                        && self.import_equals_has_runtime_use(*statement, import) =>
                {
                    if let Some(name) = declaration_name_text(self.arena, import.name)
                        && seen.insert(name.to_owned())
                    {
                        names.push(name.to_owned());
                    }
                }
                NodeData::VariableStatement(statement) if exported => {
                    let Some(NodeData::VariableDeclarationList(list)) = self
                        .arena
                        .get(statement.declaration_list)
                        .map(|node| &node.data)
                    else {
                        continue;
                    };
                    for declaration in &list.declarations.nodes {
                        let Some(NodeData::VariableDeclaration(declaration)) =
                            self.arena.get(*declaration).map(|node| &node.data)
                        else {
                            continue;
                        };
                        for name in self.declaration_names(&[declaration.name]) {
                            if seen.insert(name.clone()) {
                                names.push(name);
                            }
                        }
                    }
                }
                NodeData::ExportDeclaration(export) => {
                    let Some(clause) = export
                        .export_clause
                        .and_then(|clause| self.arena.get(clause))
                    else {
                        continue;
                    };
                    if let NodeData::NamespaceExport(namespace) = &clause.data {
                        if let Some(name) = declaration_name_text(self.arena, namespace.name)
                            && seen.insert(name.to_owned())
                        {
                            names.push(name.to_owned());
                        }
                        continue;
                    }
                    let NodeData::NamedExports(exports) = &clause.data else {
                        continue;
                    };
                    for element in &exports.elements.nodes {
                        let Some(NodeData::ExportSpecifier(specifier)) =
                            self.arena.get(*element).map(|node| &node.data)
                        else {
                            continue;
                        };
                        if !self.export_specifier_emits_runtime(export, *element)
                            || self
                                .commonjs_export_function_declaration(*element)
                                .is_some()
                        {
                            continue;
                        }
                        let Some(name) = declaration_name_text(self.arena, specifier.name) else {
                            continue;
                        };
                        if seen.insert(name.to_owned()) {
                            names.push(name.to_owned());
                        }
                    }
                }
                _ => {}
            }
        }
        names
    }

    fn prepare_uninitialized_export_rewrites(&mut self, statements: &NodeList) {
        for statement in &statements.nodes {
            let Some(node) = self.arena.get(*statement) else {
                continue;
            };
            let NodeData::VariableStatement(variable) = &node.data else {
                continue;
            };
            if !declaration_has_modifier(self.arena, node, SyntaxKind::ExportKeyword)
                || !self.variable_list_is_uninitialized(variable.declaration_list)
            {
                continue;
            }
            let Some(NodeData::VariableDeclarationList(list)) = self
                .arena
                .get(variable.declaration_list)
                .map(|node| &node.data)
            else {
                continue;
            };
            for declaration_id in &list.declarations.nodes {
                let Some(NodeData::VariableDeclaration(declaration)) =
                    self.arena.get(*declaration_id).map(|node| &node.data)
                else {
                    continue;
                };
                let Some(name) = declaration_name_text(self.arena, declaration.name) else {
                    continue;
                };
                if let Some(symbol) = self
                    .bindings
                    .node_symbols
                    .get(&declaration.name)
                    .copied()
                    .or_else(|| self.bindings.node_symbols.get(declaration_id).copied())
                    .or_else(|| self.bindings.resolve_name_at(declaration.name, name))
                {
                    self.identifier_rewrites
                        .insert(symbol, format!("exports.{name}"));
                }
            }
        }
    }

    fn export_specifier_target_has_runtime_value(
        &self,
        specifier: &ts_ast::ExportSpecifierData,
    ) -> bool {
        let local = specifier.property_name.unwrap_or(specifier.name);
        let Some(name) = declaration_name_text(self.arena, local) else {
            return false;
        };
        let Some(mut symbol) = self.bindings.resolve_name_at(local, name) else {
            return false;
        };
        if self.export_specifier_is_orphan_global(local, symbol) {
            let Some(declaration_symbol) = self
                .bindings
                .root_scope()
                .and_then(|scope| scope.symbols.get(name))
            else {
                return true;
            };
            symbol = declaration_symbol;
        }
        self.symbol_has_runtime_value(symbol, &mut HashSet::new())
    }

    fn export_specifier_is_orphan_global(&self, local: NodeId, symbol: SymbolId) -> bool {
        self.bindings.symbols.get(symbol).is_some_and(|symbol| {
            symbol.target.is_none()
                && !symbol.declarations.is_empty()
                && symbol.declarations.iter().all(|declaration| {
                    matches!(
                        self.arena.get(*declaration).map(|node| &node.data),
                        Some(NodeData::ExportSpecifier(_))
                    )
                })
                && declaration_name_text(self.arena, local).is_some_and(|name| {
                    self.bindings
                        .root_scope()
                        .is_none_or(|scope| scope.symbols.get(name).is_none())
                })
        })
    }

    fn export_specifier_id_is_orphan_global(&self, specifier: NodeId) -> bool {
        let Some(NodeData::ExportSpecifier(specifier)) =
            self.arena.get(specifier).map(|node| &node.data)
        else {
            return false;
        };
        let local = specifier.property_name.unwrap_or(specifier.name);
        let Some(name) = declaration_name_text(self.arena, local) else {
            return false;
        };
        self.bindings
            .resolve_name_at(local, name)
            .is_some_and(|symbol| self.export_specifier_is_orphan_global(local, symbol))
    }

    fn export_specifier_emits_runtime(
        &self,
        export: &ts_ast::ExportDeclarationData,
        specifier_id: NodeId,
    ) -> bool {
        let Some(NodeData::ExportSpecifier(specifier)) =
            self.arena.get(specifier_id).map(|node| &node.data)
        else {
            return false;
        };
        if export.is_type_only || specifier.is_type_only {
            return false;
        }
        if self.const_enum_emit_mode.preserves_declarations() {
            return true;
        }
        if export.module_specifier.is_some() {
            return self
                .import_runtime_meanings
                .get(&specifier_id)
                .copied()
                .unwrap_or(true);
        }
        if let Some(runtime) = self.import_runtime_meanings.get(&specifier_id) {
            return *runtime;
        }
        self.export_specifier_target_has_runtime_value(specifier)
            || self
                .commonjs_export_import_declaration(specifier_id)
                .is_some()
            || self
                .commonjs_export_variable_declaration(specifier_id)
                .is_some()
            || self
                .commonjs_export_function_declaration(specifier_id)
                .is_some()
            || self
                .commonjs_export_class_declaration(specifier_id)
                .is_some()
    }

    fn named_export_clause_has_runtime_specifier(
        &self,
        export: &ts_ast::ExportDeclarationData,
    ) -> Option<bool> {
        let NodeData::NamedExports(exports) =
            &self.arena.get(export.export_clause?)?.data
        else {
            return None;
        };
        (!exports.elements.nodes.is_empty()).then(|| {
            exports
                .elements
                .nodes
                .iter()
                .any(|specifier| self.export_specifier_emits_runtime(export, *specifier))
        })
    }

    fn statement_emits_runtime(&self, id: NodeId, node: &Node) -> bool {
        if !self.namespace_containers.is_empty()
            && self.namespace_erases_external_module_statement(node)
        {
            return false;
        }
        if (declaration_has_modifier(self.arena, node, SyntaxKind::DeclareKeyword)
            && !matches!(node.data, NodeData::ImportEqualsDeclaration(_)))
            || (is_const_enum_declaration(self.arena, node)
                && !self.const_enum_emit_mode.preserves_declarations())
        {
            return false;
        }
        if let NodeData::ExportDeclaration(export) = &node.data
            && (export.is_type_only || export.export_clause.is_some())
            && self.import_runtime_meanings.get(&id) == Some(&false)
            && self.named_export_clause_has_runtime_specifier(export) != Some(true)
            && !self.const_enum_emit_mode.preserves_declarations()
        {
            return false;
        }
        match &node.data {
            NodeData::ImportDeclaration(import) => self.import_has_runtime_use(id, import),
            NodeData::ImportEqualsDeclaration(import) => {
                self.import_equals_has_runtime_use(id, import)
            }
            NodeData::NotEmittedStatement(_)
            | NodeData::InterfaceDeclaration(_)
            | NodeData::TypeAliasDeclaration(_) => false,
            NodeData::ExportDeclaration(export)
                if self.named_export_clause_has_runtime_specifier(export) == Some(false) =>
            {
                false
            }
            NodeData::ExportDeclaration(_) if export_declaration_is_empty(self.arena, node) => {
                false
            }
            NodeData::ExportAssignment(assignment)
                if assignment.is_export_equals
                    && !matches!(self.settings.module, ModuleKind::CommonJs | ModuleKind::Preserve) =>
            {
                false
            }
            NodeData::ExportAssignment(assignment) => {
                self.export_assignment_has_runtime_value(assignment.expression)
            }
            NodeData::FunctionDeclaration(function) => function.body.is_some(),
            NodeData::ModuleDeclaration(module) => {
                self.namespace_has_runtime_contents(module, &mut HashSet::new())
            }
            NodeData::VariableStatement(statement)
                if (self.commonjs_module_transform || !self.namespace_containers.is_empty())
                    && declaration_has_modifier(self.arena, node, SyntaxKind::ExportKeyword)
                    && self.variable_list_is_uninitialized(statement.declaration_list) =>
            {
                false
            }
            _ => true,
        }
    }

    fn statement_emits_in_place(&self, id: NodeId, node: &Node) -> bool {
        self.statement_emits_runtime(id, node)
            && !matches!(
                &node.data,
                NodeData::ExportAssignment(assignment) if assignment.is_export_equals
            )
    }

    fn is_external_import_equals(&self, import: &ts_ast::ImportEqualsDeclarationData) -> bool {
        matches!(
            self.arena
                .get(import.module_reference)
                .map(|node| &node.data),
            Some(NodeData::ExternalModuleReference(_))
        )
    }

    fn namespace_erases_external_module_statement(&self, node: &Node) -> bool {
        match &node.data {
            NodeData::ImportDeclaration(_) | NodeData::ExportDeclaration(_) => true,
            NodeData::ImportEqualsDeclaration(import) => self.is_external_import_equals(import),
            _ => false,
        }
    }

    fn import_equals_has_runtime_use(
        &self,
        declaration: NodeId,
        import: &ts_ast::ImportEqualsDeclarationData,
    ) -> bool {
        if import.is_type_only {
            return false;
        }
        if self.is_external_import_equals(import) {
            self.external_import_equals_has_runtime_use(declaration, import)
        } else {
            let exported = self.has_modifier(import.modifiers.as_ref(), SyntaxKind::ExportKeyword);
            let used = self.import_binding_is_used(import.name);
            let export_equals_target = self.import_is_export_equals_target(import.name);
            let alias_chain = self.identifier_text(import.name).is_ok_and(|name| {
                self.import_name_has_runtime_alias_chain(name, &mut HashSet::new())
            });
            self.internal_import_equals_has_runtime_value(import)
                && (exported || used || export_equals_target || alias_chain)
        }
    }

    fn runtime_export_equals_expression(&self, statements: &NodeList) -> Option<NodeId> {
        statements.nodes.iter().find_map(|statement| {
            let NodeData::ExportAssignment(assignment) = &self.arena.get(*statement)?.data else {
                return None;
            };
            (assignment.is_export_equals
                && self.entity_has_runtime_value(assignment.expression, &mut HashSet::new()))
            .then_some(assignment.expression)
        })
    }

    fn external_import_equals_has_runtime_use(
        &self,
        declaration: NodeId,
        import: &ts_ast::ImportEqualsDeclarationData,
    ) -> bool {
        if import.is_type_only {
            return false;
        }
        let has_runtime_reference = self
            .identifier_text(import.name)
            .is_ok_and(|name| self.import_name_has_non_erased_runtime_reference(name));
        let has_runtime_alias_chain = self
            .identifier_text(import.name)
            .is_ok_and(|name| self.import_name_has_runtime_alias_chain(name, &mut HashSet::new()));
        let is_export_equals_target = self.import_is_export_equals_target(import.name);
        (self.has_modifier(import.modifiers.as_ref(), SyntaxKind::ExportKeyword)
            && self.import_semantically_has_runtime_value(declaration))
            || (self.import_semantically_has_runtime_value(declaration) && has_runtime_reference)
            || is_export_equals_target
            || has_runtime_alias_chain
    }

    fn import_is_export_equals_target(&self, import_name: NodeId) -> bool {
        let import_symbol = self
            .bindings
            .node_symbols
            .get(&import_name)
            .copied()
            .or_else(|| {
                let name = declaration_name_text(self.arena, import_name)?;
                self.bindings.resolve_name_at(import_name, name)
            });
        self.arena.iter().any(|(_, node)| {
            let NodeData::ExportAssignment(assignment) = &node.data else {
                return false;
            };
            if !assignment.is_export_equals {
                return false;
            }
            let Some(name) = declaration_name_text(self.arena, assignment.expression) else {
                return false;
            };
            let target_symbol = self
                .bindings
                .node_symbols
                .get(&assignment.expression)
                .copied()
                .or_else(|| self.bindings.resolve_name_at(assignment.expression, name));
            match (import_symbol, target_symbol) {
                (Some(import_symbol), Some(target_symbol)) => import_symbol == target_symbol,
                _ => declaration_name_text(self.arena, import_name) == Some(name),
            }
        })
    }

    fn internal_import_equals_has_runtime_value(
        &self,
        import: &ts_ast::ImportEqualsDeclarationData,
    ) -> bool {
        self.internal_import_equals_has_runtime_value_with_visited(import, &mut HashSet::new())
    }

    fn internal_import_equals_has_runtime_value_with_visited(
        &self,
        import: &ts_ast::ImportEqualsDeclarationData,
        visited: &mut HashSet<SymbolId>,
    ) -> bool {
        if matches!(
            self.arena
                .get(import.module_reference)
                .map(|node| &node.data),
            Some(NodeData::Identifier(identifier)) if identifier.text.is_empty()
        ) {
            return false;
        }
        self.entity_has_runtime_value(import.module_reference, visited)
    }

    fn entity_has_runtime_value(&self, entity: NodeId, visited: &mut HashSet<SymbolId>) -> bool {
        let Some(symbol) = self.resolve_entity_symbol(entity, &mut HashSet::new()) else {
            // Preserve the syntactic fallback for unresolved aliases.
            return true;
        };
        self.symbol_has_runtime_value(symbol, visited)
    }

    fn export_assignment_has_runtime_value(&self, expression: NodeId) -> bool {
        if self.entity_has_runtime_value(expression, &mut HashSet::new()) {
            return true;
        }
        let Some(symbol) = self.resolve_entity_symbol(expression, &mut HashSet::new()) else {
            return true;
        };
        self.bindings.symbols.get(symbol).is_some_and(|symbol| {
            symbol.declarations.iter().any(|declaration| {
                self.arena.get(*declaration).is_some_and(|node| {
                    matches!(
                        node.data,
                        NodeData::ClassDeclaration(_)
                            | NodeData::FunctionDeclaration(_)
                            | NodeData::EnumDeclaration(_)
                            | NodeData::ModuleDeclaration(_)
                            | NodeData::VariableDeclaration(_)
                    ) && (!is_const_enum_declaration(self.arena, node)
                        || self.const_enum_emit_mode.preserves_declarations())
                })
            })
        })
    }

    fn resolve_entity_symbol(
        &self,
        entity: NodeId,
        visited: &mut HashSet<SymbolId>,
    ) -> Option<SymbolId> {
        match &self.arena.get(entity)?.data {
            NodeData::Identifier(identifier) => self
                .bindings
                .node_symbols
                .get(&entity)
                .copied()
                .or_else(|| self.bindings.resolve_name_at(entity, &identifier.text))
                .or_else(|| {
                    self.enclosing_namespace_member_symbol(entity, &identifier.text)
                }),
            NodeData::QualifiedName(name) => {
                let left = self.resolve_entity_symbol(name.left, visited)?;
                let left = self.alias_target_symbol(left, visited).unwrap_or(left);
                let right = declaration_name_text(self.arena, name.right)?;
                self.bindings.symbols.get(left)?.members.get(right)
            }
            _ => None,
        }
    }

    fn enclosing_namespace_member_symbol(&self, node: NodeId, name: &str) -> Option<SymbolId> {
        let mut current = self.arena.get(node)?.parent;
        let mut namespace_path = Vec::new();
        while let Some(ancestor) = current {
            let ancestor_node = self.arena.get(ancestor)?;
            if let NodeData::ModuleDeclaration(module) = &ancestor_node.data {
                if let Some(module_name) = declaration_name_text(self.arena, module.name) {
                    namespace_path.push(module_name.to_owned());
                }
                let namespace = self
                    .bindings
                    .node_symbols
                    .get(&module.name)
                    .copied()
                    .or_else(|| {
                        declaration_name_text(self.arena, module.name).and_then(|module_name| {
                            self.bindings.resolve_name_at(module.name, module_name)
                        })
                    });
                if let Some(member) = namespace
                    .and_then(|namespace| self.bindings.symbols.get(namespace))
                    .and_then(|namespace| namespace.members.get(name))
                {
                    return Some(member);
                }
            }
            current = ancestor_node.parent;
        }
        namespace_path.reverse();
        if let Some(member) = (|| {
            let (root, nested) = namespace_path.split_first()?;
            let mut namespace = self.bindings.root_scope()?.symbols.get(root)?;
            for segment in nested {
                namespace = self.bindings.symbols.get(namespace)?.members.get(segment)?;
            }
            self.bindings.symbols.get(namespace)?.members.get(name)
        })() {
            return Some(member);
        }
        let mut expected_path = namespace_path;
        expected_path.push(name.to_owned());
        self.arena.iter().find_map(|(_, candidate)| {
            let NodeData::ModuleDeclaration(module) = &candidate.data else {
                return None;
            };
            if declaration_name_text(self.arena, module.name) != Some(name) {
                return None;
            }
            let mut path = vec![name.to_owned()];
            let mut parent = candidate.parent;
            while let Some(ancestor) = parent {
                let ancestor_node = self.arena.get(ancestor)?;
                if let NodeData::ModuleDeclaration(module) = &ancestor_node.data
                    && let Some(module_name) = declaration_name_text(self.arena, module.name)
                {
                    path.push(module_name.to_owned());
                }
                parent = ancestor_node.parent;
            }
            path.reverse();
            (path == expected_path)
                .then(|| self.bindings.node_symbols.get(&module.name).copied())
                .flatten()
        })
    }

    fn alias_target_symbol(
        &self,
        symbol: SymbolId,
        visited: &mut HashSet<SymbolId>,
    ) -> Option<SymbolId> {
        if !visited.insert(symbol) {
            return None;
        }
        let symbol = self.bindings.symbols.get(symbol)?;
        if let Some(target) = symbol.target {
            return Some(target);
        }
        symbol.declarations.iter().find_map(|declaration| {
            let NodeData::ImportEqualsDeclaration(import) = &self.arena.get(*declaration)?.data
            else {
                return None;
            };
            self.resolve_entity_symbol(import.module_reference, visited)
        })
    }

    fn symbol_has_runtime_value(&self, symbol: SymbolId, visited: &mut HashSet<SymbolId>) -> bool {
        if !visited.insert(symbol) {
            return false;
        }
        let Some(symbol) = self.bindings.symbols.get(symbol) else {
            return true;
        };
        if let Some(target) = symbol.target {
            return self.symbol_has_runtime_value(target, visited);
        }
        for declaration in &symbol.declarations {
            let Some(node) = self.arena.get(*declaration) else {
                continue;
            };
            match &node.data {
                NodeData::ImportEqualsDeclaration(import) => {
                    if !import.is_type_only
                        && (!self.is_external_import_equals(import)
                            || self.import_semantically_has_runtime_value(*declaration)
                            || self.import_is_export_equals_target(import.name))
                        && self.entity_has_runtime_value(import.module_reference, visited)
                    {
                        return true;
                    }
                }
                NodeData::ModuleDeclaration(module) => {
                    if self.namespace_has_runtime_contents(module, visited) {
                        return true;
                    }
                }
                NodeData::ImportClause(_)
                | NodeData::ImportSpecifier(_)
                | NodeData::NamespaceImport(_)
                | NodeData::NamedImports(_) => {
                    if self.import_binding_has_runtime_value(*declaration) {
                        return true;
                    }
                }
                NodeData::InterfaceDeclaration(_)
                | NodeData::TypeAliasDeclaration(_)
                | NodeData::ExportAssignment(_)
                | NodeData::ExportSpecifier(_) => {}
                NodeData::FunctionDeclaration(function) if function.body.is_none() => {}
                NodeData::EnumDeclaration(_)
                    if is_const_enum_declaration(self.arena, node)
                        && !self.const_enum_emit_mode.preserves_declarations() => {}
                _ if !declaration_has_modifier(self.arena, node, SyntaxKind::DeclareKeyword) => {
                    return true;
                }
                _ => {}
            }
        }
        false
    }

    fn import_binding_has_runtime_value(&self, declaration: NodeId) -> bool {
        let mut current = declaration;
        loop {
            let Some(node) = self.arena.get(current) else {
                return true;
            };
            match &node.data {
                NodeData::ImportDeclaration(_) => {
                    return self.import_semantically_has_runtime_value(current);
                }
                NodeData::ImportClause(clause)
                    if clause.phase_modifier == Some(SyntaxKind::TypeKeyword) =>
                {
                    return false;
                }
                NodeData::ImportSpecifier(specifier) if specifier.is_type_only => return false,
                _ => {}
            }
            let Some(parent) = node.parent else {
                return true;
            };
            current = parent;
        }
    }

    fn namespace_has_runtime_contents(
        &self,
        module: &ts_ast::ModuleDeclarationData,
        visited: &mut HashSet<SymbolId>,
    ) -> bool {
        let Some(body) = module.body else {
            return false;
        };
        let Some(body) = self.arena.get(body) else {
            return false;
        };
        match &body.data {
            NodeData::ModuleBlock(block) => {
                block.statements.nodes.iter().any(|statement| {
                    self.namespace_statement_has_runtime_value(*statement, visited)
                })
            }
            NodeData::ModuleDeclaration(module) => {
                self.namespace_has_runtime_contents(module, visited)
            }
            _ => false,
        }
    }

    fn namespace_statement_has_runtime_value(
        &self,
        statement: NodeId,
        visited: &mut HashSet<SymbolId>,
    ) -> bool {
        let Some(node) = self.arena.get(statement) else {
            return false;
        };
        if let NodeData::ExportDeclaration(export) = &node.data {
            return export.module_specifier.is_none()
                && self.named_export_clause_has_runtime_specifier(export) == Some(true);
        }
        if self.namespace_erases_external_module_statement(node) {
            return false;
        }
        match &node.data {
            NodeData::InterfaceDeclaration(_) | NodeData::TypeAliasDeclaration(_) => false,
            NodeData::ModuleDeclaration(module) => {
                self.namespace_has_runtime_contents(module, visited)
            }
            // Exported aliases instantiate a module even when their target is type-only and the
            // alias is consequently erased. Non-exported imports do not instantiate a module.
            NodeData::ImportEqualsDeclaration(import) => {
                self.has_modifier(import.modifiers.as_ref(), SyntaxKind::ExportKeyword)
            }
            NodeData::EnumDeclaration(_)
                if is_const_enum_declaration(self.arena, node)
                    && !self.const_enum_emit_mode.preserves_declarations() =>
            {
                false
            }
            _ => true,
        }
    }

    fn namespace_has_prior_merged_value_declaration(&self, name: NodeId) -> bool {
        let Some(current) = self.arena.get(name).and_then(|node| node.parent) else {
            return false;
        };
        let Some(current_start) = self.arena.get(current).map(|node| node.range.start) else {
            return false;
        };
        self.bindings
            .node_symbols
            .get(&name)
            .and_then(|symbol| self.bindings.symbols.get(*symbol))
            .is_some_and(|symbol| {
                symbol.declarations.iter().any(|declaration| {
                    if *declaration == current {
                        return false;
                    }
                    let Some(node) = self.arena.get(*declaration) else {
                        return false;
                    };
                    if node.range.start >= current_start
                        || node_is_in_ambient_context(self.arena, *declaration)
                    {
                        return false;
                    }
                    match &node.data {
                        NodeData::ClassDeclaration(_) => true,
                        NodeData::EnumDeclaration(_) => {
                            !is_const_enum_declaration(self.arena, node)
                                || self.const_enum_emit_mode.preserves_declarations()
                        }
                        NodeData::ModuleDeclaration(module) => {
                            self.namespace_has_runtime_contents(module, &mut HashSet::new())
                        }
                        NodeData::FunctionDeclaration(function) => function.body.is_some(),
                        _ => false,
                    }
                })
            })
    }

    fn namespace_needs_local_declaration(&self, name: NodeId, text: &str) -> bool {
        !self.namespace_has_prior_merged_value_declaration(name)
            && !self.system_predeclared_names.contains(text)
    }

    fn namespace_parameter_collides(&self, name: NodeId, text: &str) -> bool {
        let Some(declaration) = self.arena.get(name).and_then(|name| name.parent) else {
            return false;
        };
        let Some(module_scope) = self.bindings.node_scopes.get(&declaration).copied() else {
            return false;
        };
        let collision_flags = SymbolFlags::FUNCTION_SCOPED_VARIABLE
            | SymbolFlags::BLOCK_SCOPED_VARIABLE
            | SymbolFlags::FUNCTION
            | SymbolFlags::CLASS
            | SymbolFlags::REGULAR_ENUM
            | SymbolFlags::CONST_ENUM
            | SymbolFlags::ALIAS;
        let namespace_flags = SymbolFlags::VALUE_MODULE | SymbolFlags::NAMESPACE_MODULE;

        self.bindings.scopes.iter().any(|scope| {
            let mut current = Some(scope.id);
            let mut is_descendant = false;
            while let Some(scope_id) = current {
                if scope_id == module_scope {
                    is_descendant = true;
                    break;
                }
                current = self.bindings.scope(scope_id).and_then(|scope| scope.parent);
            }
            is_descendant
                && scope
                    .symbols
                    .get(text)
                    .and_then(|symbol| self.bindings.symbols.get(symbol))
                    .is_some_and(|symbol| {
                        symbol.flags.intersects(collision_flags)
                            || (scope.id == module_scope
                                && symbol.flags.intersects(namespace_flags))
                            || (scope.id != module_scope
                                && symbol.flags.intersects(namespace_flags)
                                && symbol.declarations.iter().any(|declaration| {
                                    matches!(
                                        self.arena.get(*declaration).map(|node| &node.data),
                                        Some(NodeData::ModuleDeclaration(module))
                                            if self.namespace_has_runtime_contents(
                                                module,
                                                &mut HashSet::new(),
                                            )
                                    )
                                }))
                    })
        })
    }

    fn namespace_local_declaration_is_block_scoped(&self, name: NodeId) -> bool {
        if self.settings.target < ScriptTarget::Es2015 {
            return false;
        }
        let mut declaration = self.arena.get(name).and_then(|name| name.parent);
        while let Some(id) = declaration {
            let Some(parent_id) = self
                .arena
                .get(id)
                .and_then(|declaration| declaration.parent)
            else {
                return false;
            };
            let Some(parent) = self.arena.get(parent_id) else {
                return false;
            };
            match parent.data {
                NodeData::Block(_) | NodeData::ModuleBlock(_) => return true,
                NodeData::ModuleDeclaration(_) => declaration = Some(parent_id),
                _ => return false,
            }
        }
        false
    }

    fn identifier_is_qualified_enclosing_namespace_root(
        &self,
        identifier: NodeId,
        symbol: SymbolId,
    ) -> bool {
        let Some(parent) = self.arena.get(identifier).and_then(|node| node.parent) else {
            return false;
        };
        let qualified_root = matches!(
            self.arena.get(parent).map(|node| &node.data),
            Some(NodeData::PropertyAccessExpression(access)) if access.expression == identifier
        ) || matches!(
            self.arena.get(parent).map(|node| &node.data),
            Some(NodeData::QualifiedName(name)) if name.left == identifier
        );
        if !qualified_root {
            return false;
        }

        let mut ancestor = Some(parent);
        while let Some(id) = ancestor {
            let Some(node) = self.arena.get(id) else {
                break;
            };
            if let NodeData::ModuleDeclaration(module) = &node.data
                && self.bindings.node_symbols.get(&module.name).copied() == Some(symbol)
            {
                return true;
            }
            ancestor = node.parent;
        }
        false
    }

    fn reopened_namespace_member_rewrite(&self, identifier: NodeId, text: &str) -> Option<String> {
        let parent = self.arena.get(identifier)?.parent?;
        if matches!(
            self.arena.get(parent).map(|node| &node.data),
            Some(NodeData::PropertyAccessExpression(access)) if access.expression == identifier
        ) || matches!(
            self.arena.get(parent).map(|node| &node.data),
            Some(NodeData::QualifiedName(name)) if name.left == identifier
        ) {
            return None;
        }
        if !identifier_is_unqualified_value_reference(self.arena, identifier) {
            return None;
        }
        let value_flags = SymbolFlags::FUNCTION
            | SymbolFlags::CLASS
            | SymbolFlags::FUNCTION_SCOPED_VARIABLE
            | SymbolFlags::BLOCK_SCOPED_VARIABLE
            | SymbolFlags::REGULAR_ENUM
            | SymbolFlags::CONST_ENUM
            | SymbolFlags::VALUE_MODULE
            | SymbolFlags::NAMESPACE_MODULE;
        let mut ancestor = Some(parent);
        while let Some(id) = ancestor {
            let node = self.arena.get(id)?;
            if let NodeData::ModuleDeclaration(module) = &node.data {
                let path = self.namespace_declaration_path(id)?;
                let reopened_member = self.arena.iter().find_map(|(candidate_id, candidate)| {
                    if candidate_id == id
                        || !matches!(candidate.data, NodeData::ModuleDeclaration(_))
                        || self.namespace_declaration_path(candidate_id).as_ref() != Some(&path)
                    {
                        return None;
                    }
                    let NodeData::ModuleDeclaration(candidate) = &candidate.data else {
                        return None;
                    };
                    self.bindings
                        .node_symbols
                        .get(&candidate.name)
                        .and_then(|symbol| self.bindings.symbols.get(*symbol))
                        .and_then(|symbol| symbol.members.get(text))
                        .and_then(|member| self.bindings.symbols.get(member))
                });
                if reopened_member.is_some_and(|member| member.flags.intersects(value_flags)) {
                    return Some(format!(
                        "{}.{}",
                        self.identifier_text(module.name).ok()?,
                        text
                    ));
                }
            }
            ancestor = node.parent;
        }
        None
    }

    fn identifier_has_local_namespace_value_declaration(
        &self,
        identifier: NodeId,
        text: &str,
    ) -> bool {
        if !identifier_is_unqualified_value_reference(self.arena, identifier) {
            return false;
        }
        let mut current = self.arena.get(identifier).and_then(|node| node.parent);
        while let Some(id) = current {
            let Some(node) = self.arena.get(id) else {
                return false;
            };
            if let NodeData::ModuleBlock(block) = &node.data {
                return block.statements.nodes.iter().any(|statement| {
                    let Some(statement) = self.arena.get(*statement) else {
                        return false;
                    };
                    match &statement.data {
                        NodeData::FunctionDeclaration(function) => {
                            function
                                .name
                                .and_then(|name| declaration_name_text(self.arena, name))
                                == Some(text)
                        }
                        NodeData::ClassDeclaration(class) => {
                            class
                                .name
                                .and_then(|name| declaration_name_text(self.arena, name))
                                == Some(text)
                        }
                        NodeData::EnumDeclaration(enumeration) => {
                            declaration_name_text(self.arena, enumeration.name) == Some(text)
                        }
                        NodeData::ModuleDeclaration(module) => {
                            declaration_name_text(self.arena, module.name) == Some(text)
                                && self.namespace_has_runtime_contents(module, &mut HashSet::new())
                        }
                        _ => false,
                    }
                });
            }
            current = node.parent;
        }
        false
    }

    fn namespace_declaration_path(&self, declaration: NodeId) -> Option<Vec<String>> {
        let mut path = Vec::new();
        let mut ancestor = Some(declaration);
        while let Some(id) = ancestor {
            let node = self.arena.get(id)?;
            if let NodeData::ModuleDeclaration(module) = &node.data {
                path.push(self.identifier_text(module.name).ok()?.to_owned());
            }
            ancestor = node.parent;
        }
        path.reverse();
        Some(path)
    }

    fn record_mapping(&mut self, node: &Node) {
        if self.source_map.is_none() {
            return;
        }
        let (line, column) = self.writer.position();
        let (original_line, original_column) = original_position(
            self.source_text,
            self.source_line_starts
                .as_deref()
                .expect("source line starts exist when source maps are enabled"),
            node.range.start.get(),
        );
        if let Some(builder) = &mut self.source_map {
            let _ = builder.add_mapping(line, column, 0, original_line, original_column);
        }
    }

    #[allow(clippy::too_many_lines)]
    fn emit_statement(&mut self, id: NodeId) -> Result<(), EmitError> {
        let node = self.node(id)?.clone();
        if self.es5_async_hoisted_function_declarations.contains(&id) {
            return Ok(());
        }
        if !self.namespace_containers.is_empty()
            && self.namespace_erases_external_module_statement(&node)
        {
            return Ok(());
        }
        if let NodeData::VariableStatement(statement) = &node.data
            && self
                .es5_async_hoisted_variable_lists
                .contains(&statement.declaration_list)
        {
            self.record_mapping(&node);
            if self.emit_es5_async_for_initializer_assignments(statement.declaration_list)? {
                self.writer.write(";");
                self.writer.newline();
            }
            return Ok(());
        }
        if declaration_has_modifier(self.arena, &node, SyntaxKind::DeclareKeyword)
            && !matches!(node.data, NodeData::ImportEqualsDeclaration(_))
        {
            return Ok(());
        }
        if is_const_enum_declaration(self.arena, &node)
            && !self.const_enum_emit_mode.preserves_declarations()
        {
            return Ok(());
        }
        if let NodeData::ExportDeclaration(export) = &node.data
            && (export.is_type_only || export.export_clause.is_some())
            && self.import_runtime_meanings.get(&id) == Some(&false)
            && self.named_export_clause_has_runtime_specifier(export) != Some(true)
            && !self.const_enum_emit_mode.preserves_declarations()
        {
            return Ok(());
        }
        if matches!(
            &node.data,
            NodeData::ExportAssignment(assignment)
                if assignment.is_export_equals
                    && node.parent.is_some_and(|parent| matches!(
                        self.arena.get(parent).map(|node| &node.data),
                        Some(NodeData::SourceFile(_))
                    ))
        ) {
            return Ok(());
        }
        if let NodeData::ExportAssignment(assignment) = &node.data
            && assignment.is_export_equals
            && !self.entity_has_runtime_value(assignment.expression, &mut HashSet::new())
        {
            return Ok(());
        }
        match &node.data {
            NodeData::NotEmittedStatement(_) => return Ok(()),
            NodeData::ExportDeclaration(export)
                if self.named_export_clause_has_runtime_specifier(export) == Some(false) =>
            {
                return Ok(());
            }
            NodeData::ImportDeclaration(import) if !self.import_has_runtime_use(id, import) => {
                return Ok(());
            }
            NodeData::ImportEqualsDeclaration(import)
                if !self.import_equals_has_runtime_use(id, import) =>
            {
                return Ok(());
            }
            NodeData::ModuleDeclaration(module)
                if !self.namespace_has_runtime_contents(module, &mut HashSet::new()) =>
            {
                return Ok(());
            }
            NodeData::ExportDeclaration(export)
                if self.commonjs_module_transform
                    && self.commonjs_export_is_fully_hoisted(export) =>
            {
                return Ok(());
            }
            _ => {}
        }
        if let Some(container) = self.namespace_containers.last().cloned()
            && let NodeData::ImportEqualsDeclaration(import) = &node.data
            && !self.is_external_import_equals(import)
            && self.has_modifier(import.modifiers.as_ref(), SyntaxKind::ExportKeyword)
        {
            let name = self.identifier_text(import.name)?.to_owned();
            self.writer.write(&container);
            self.writer.write(".");
            self.writer.write(&name);
            self.writer.write(" = ");
            self.emit_expression(import.module_reference, 1)?;
            self.writer.write(";");
            self.writer.newline();
            return Ok(());
        }
        if (self.commonjs_module_transform || !self.namespace_containers.is_empty())
            && declaration_has_modifier(self.arena, &node, SyntaxKind::ExportKeyword)
            && let NodeData::VariableStatement(statement) = &node.data
            && self.variable_list_is_uninitialized(statement.declaration_list)
        {
            return Ok(());
        }
        match &node.data {
            NodeData::InterfaceDeclaration(_) | NodeData::TypeAliasDeclaration(_) => return Ok(()),
            NodeData::FunctionDeclaration(data) if data.body.is_none() => return Ok(()),
            NodeData::ExportDeclaration(_) if export_declaration_is_empty(self.arena, &node) => {
                return Ok(());
            }
            _ => {}
        }
        self.record_mapping(&node);
        match &node.data {
            NodeData::Block(_) => self.emit_block(id)?,
            NodeData::EmptyStatement(_) => self.writer.write(";"),
            NodeData::VariableStatement(data) => {
                if self.exported_object_rest_temps.contains_key(&id) {
                    self.emit_exported_object_rest_initializer(id, data)?;
                } else if self.commonjs_empty_binding_temps.contains_key(&id) {
                    self.emit_commonjs_empty_binding_initializer(id, data)?;
                } else if self.emit_system_predeclared_variable_assignment(data)? {
                } else if !self.emit_namespace_export_variable_initializers(data)?
                    && !self.emit_commonjs_export_variable_initializer(data)?
                {
                    self.emit_runtime_declaration_modifiers(data.modifiers.as_ref());
                    self.emit_variable_list(
                        data.declaration_list,
                        self.commonjs_module_transform
                            && self
                                .has_modifier(data.modifiers.as_ref(), SyntaxKind::ExportKeyword),
                    )?;
                    self.writer.write(";");
                    if !self.variable_list_is_uninitialized(data.declaration_list) {
                        let names = self.variable_declaration_names(data.declaration_list)?;
                        self.emit_commonjs_declaration_exports(data.modifiers.as_ref(), &names);
                    }
                }
            }
            NodeData::FunctionDeclaration(data) => {
                let commonjs_default_name = self.commonjs_anonymous_default_names.get(&id).cloned();
                let namespace_default_name = (!self.namespace_containers.is_empty()
                    && data.name.is_none()
                    && self.has_modifier(data.modifiers.as_ref(), SyntaxKind::ExportKeyword)
                    && self.has_modifier(data.modifiers.as_ref(), SyntaxKind::DefaultKeyword))
                .then(|| self.generated_names.generate("default"));
                self.emit_runtime_declaration_modifiers(data.modifiers.as_ref());
                if !self.namespace_containers.is_empty()
                    && self.has_modifier(data.modifiers.as_ref(), SyntaxKind::DefaultKeyword)
                {
                    self.writer.write("default ");
                }
                let is_async = self.has_modifier(data.modifiers.as_ref(), SyntaxKind::AsyncKeyword);
                let downlevel_async_generator = self.settings.target < ScriptTarget::Es2018
                    && data.asterisk_token.is_some()
                    && is_async;
                let downlevel_async = self.settings.target < ScriptTarget::Es2017
                    && data.asterisk_token.is_none()
                    && is_async;
                let downlevel_generator = self.settings.target < ScriptTarget::Es2015
                    && data.asterisk_token.is_some()
                    && !is_async;
                let downlevel_binding_parameters = if self.settings.target < ScriptTarget::Es2018
                    && !is_async
                    && data.asterisk_token.is_none()
                {
                    self.downlevel_binding_parameters(&data.parameters, id)
                } else {
                    Vec::new()
                };
                if !downlevel_async && !downlevel_async_generator && is_async {
                    self.writer.write("async ");
                }
                self.writer.write("function");
                if data.asterisk_token.is_some()
                    && !downlevel_async_generator
                    && !downlevel_generator
                {
                    self.writer.write("*");
                }
                self.writer.write(" ");
                let function_name = data
                    .name
                    .and_then(|name| declaration_name_text(self.arena, name))
                    .map(str::to_owned)
                    .or_else(|| commonjs_default_name.clone());
                if let Some(name) = data.name {
                    let text = declaration_name_text(self.arena, name).unwrap_or_default();
                    self.write_source_identifier(name, text);
                } else if let Some(name) = commonjs_default_name.as_deref() {
                    self.writer.write(name);
                }
                let parameter_class_temps = data.body.map_or_else(Vec::new, |body| {
                    self.prepare_parameter_class_expression_temps(&data.parameters, body)
                });
                let downlevel_parameter_defaults = self.settings.target < ScriptTarget::Es2015
                    && data.parameters.nodes.iter().any(|parameter| {
                        matches!(
                            self.arena.get(*parameter).map(|node| &node.data),
                            Some(NodeData::ParameterDeclaration(parameter))
                                if parameter.initializer.is_some()
                        )
                    });
                if !downlevel_binding_parameters.is_empty() {
                    self.emit_parameters_with_name_overrides(
                        &data.parameters,
                        false,
                        &downlevel_binding_parameters,
                    )?;
                } else if downlevel_parameter_defaults && parameter_class_temps.is_empty() {
                    self.emit_parameters_without_initializers(&data.parameters)?;
                } else if parameter_class_temps.is_empty() {
                    self.emit_parameters(&data.parameters)?;
                } else {
                    self.emit_parameter_names(&data.parameters)?;
                }
                self.writer.write(" ");
                if downlevel_async {
                    self.emit_downlevel_async_function_body(
                        data.body.expect("body checked above"),
                        "this",
                    )?;
                } else if downlevel_async_generator {
                    let inner_name = self
                        .generated_names
                        .generate(function_name.as_deref().unwrap_or("_default"));
                    if self.settings.target < ScriptTarget::Es2015 {
                        self.emit_es5_downlevel_async_generator_body(
                            data.body.expect("body checked above"),
                            &inner_name,
                        )?;
                    } else {
                        self.emit_downlevel_async_generator_body(
                            data.body.expect("body checked above"),
                            &inner_name,
                        )?;
                    }
                } else if downlevel_generator {
                    self.emit_es5_generator_body(data.body.expect("body checked above"))?;
                } else if !downlevel_binding_parameters.is_empty() {
                    self.emit_function_body_with_binding_parameters(
                        data.body.expect("body checked above"),
                        &data.parameters,
                        &parameter_class_temps,
                        downlevel_parameter_defaults,
                        &downlevel_binding_parameters,
                    )?;
                } else if !parameter_class_temps.is_empty() || downlevel_parameter_defaults {
                    self.emit_function_body_with_parameter_defaults(
                        data.body.expect("body checked above"),
                        &data.parameters,
                        &parameter_class_temps,
                    )?;
                } else if self.settings.target < ScriptTarget::Es2015
                    && self.body_has_downlevel_async_arrow(data.body.expect("body checked above"))
                {
                    self.emit_function_body_with_this_capture(
                        data.body.expect("body checked above"),
                    )?;
                } else {
                    self.emit_function_body(data.body.expect("body checked above"))?;
                }
                if let Some(container) = self.namespace_containers.last().cloned()
                    && self.has_modifier(data.modifiers.as_ref(), SyntaxKind::ExportKeyword)
                    && let Some(name) = data.name.and_then(|name| {
                        declaration_name_text(self.arena, name).map(str::to_owned)
                    }).or(namespace_default_name)
                {
                    self.emit_source_comments_between_with_ownership(
                        node.range.end.get(),
                        u32::try_from(self.source_text.len()).unwrap_or(u32::MAX),
                        true,
                        false,
                    );
                    if !self.writer.line_start {
                        self.writer.newline();
                    }
                    self.writer.write(&container);
                    self.writer.write(".");
                    self.writer.write(&name);
                    self.writer.write(" = ");
                    self.writer.write(&name);
                    self.writer.write(";");
                }
            }
            NodeData::ClassDeclaration(data) => {
                let decorators = self.class_decorator_expressions(data.modifiers.as_ref());
                let recovered_default_name = (!decorators.is_empty()
                    && data.name.is_none()
                    && self.has_modifier(data.modifiers.as_ref(), SyntaxKind::DefaultKeyword))
                .then(|| self.generated_names.generate("default"));
                let commonjs_default_name = ((self.commonjs_module_transform
                    || !self.namespace_containers.is_empty())
                    && data.name.is_none()
                    && self.has_modifier(data.modifiers.as_ref(), SyntaxKind::ExportKeyword)
                    )
                .then(|| self.generated_names.generate("default"));
                let lower_preserved_default = self.settings.target < ScriptTarget::Es2015
                    && !self.commonjs_module_transform
                    && self.system_export_function.is_none()
                    && self.namespace_containers.is_empty()
                    && self.has_modifier(data.modifiers.as_ref(), SyntaxKind::ExportKeyword)
                    && self.has_modifier(data.modifiers.as_ref(), SyntaxKind::DefaultKeyword);
                if decorators.is_empty() {
                    if !lower_preserved_default {
                        self.emit_runtime_declaration_modifiers(data.modifiers.as_ref());
                    }
                    self.emit_class_with_name(data, commonjs_default_name.as_deref())?;
                } else if let Some(name) = recovered_default_name.as_deref() {
                    self.writer.write("let ");
                    self.writer.write(name);
                    self.writer.write(" = ");
                    self.emit_class(data)?;
                    self.writer.write(";");
                } else {
                    self.emit_decorated_class_binding(data)?;
                }
                self.emit_auto_accessor_storage_initializers(data);
                if lower_preserved_default && let Some(name) = data.name {
                    self.writer.newline();
                    self.writer.write("export default ");
                    self.emit_expression(name, 0)?;
                    self.writer.write(";");
                }
                if data.name.is_some() || commonjs_default_name.is_some() {
                    let names = data.name.map_or_else(
                        || vec![commonjs_default_name.clone().expect("name checked above")],
                        |name| self.declaration_names(&[name]),
                    );
                    if let Some(container) = self.namespace_containers.last().cloned() {
                        if self.has_modifier(data.modifiers.as_ref(), SyntaxKind::ExportKeyword)
                            && let Some(name) = names.first()
                        {
                            self.emit_source_comments_between_with_ownership(
                                node.range.end.get(),
                                u32::try_from(self.source_text.len()).unwrap_or(u32::MAX),
                                true,
                                false,
                            );
                            if !self.writer.line_start {
                                self.writer.newline();
                            }
                            self.writer.write(&container);
                            self.writer.write(".");
                            self.writer.write(name);
                            self.writer.write(" = ");
                            self.writer.write(name);
                            self.writer.write(";");
                        }
                    } else if !self.commonjs_class_export_precedes_static_initializers(data) {
                        self.emit_commonjs_declaration_exports(data.modifiers.as_ref(), &names);
                    }
                }
                if self.settings.target >= ScriptTarget::Es2015 {
                    self.emit_class_member_decorators(data)?;
                }
                if !decorators.is_empty() && self.settings.target >= ScriptTarget::Es2015 {
                    self.emit_class_decorator_assignment(
                        data,
                        &decorators,
                        true,
                        recovered_default_name.as_deref(),
                    )?;
                }
            }
            NodeData::EnumDeclaration(data) => {
                self.emit_runtime_declaration_modifiers(data.modifiers.as_ref());
                self.emit_enum(data)?;
            }
            NodeData::ModuleDeclaration(data) => self.emit_namespace(data)?,
            NodeData::ReturnStatement(data) => {
                self.writer.write("return");
                if self.async_expression_transform == AsyncExpressionTransform::AsyncGenerator {
                    self.writer.write(" yield __await(");
                    if let Some(expression) = data.expression {
                        self.emit_expression(expression, 0)?;
                    } else {
                        self.writer.write("void 0");
                    }
                    self.writer.write(")");
                } else if let Some(expression) = data.expression {
                    self.writer.write(" ");
                    self.emit_expression(expression, 0)?;
                }
                self.writer.write(";");
            }
            NodeData::IfStatement(data) => {
                self.emit_if_statement(data)?;
            }
            NodeData::WhileStatement(data) => {
                self.writer.write("while (");
                self.emit_expression(data.expression, 0)?;
                self.writer.write(") ");
                self.emit_embedded(data.statement)?;
            }
            NodeData::DoStatement(data) => {
                if !self.emit_es5_captured_do_loop(data)? {
                    let body_is_block =
                        matches!(&self.node(data.statement)?.data, NodeData::Block(_));
                    self.writer.write("do ");
                    self.emit_embedded(data.statement)?;
                    if body_is_block {
                        self.writer.write(" while (");
                    } else {
                        self.writer.newline();
                        self.writer.write("while (");
                    }
                    self.emit_expression(data.expression, 0)?;
                    self.writer.write(");");
                }
            }
            NodeData::ForStatement(data) => {
                if self.emit_es5_captured_for_loop(data)? {
                    self.writer.newline();
                    return Ok(());
                }
                self.writer.write("for (");
                if let Some(initializer) = data.initializer {
                    if matches!(
                        &self.node(initializer)?.data,
                        NodeData::VariableDeclarationList(_)
                    ) {
                        if self.es5_async_hoisted_variable_lists.contains(&initializer) {
                            self.emit_es5_async_for_initializer_assignments(initializer)?;
                        } else {
                            self.emit_variable_list(initializer, false)?;
                        }
                    } else {
                        self.emit_expression(initializer, 0)?;
                    }
                }
                self.writer.write(";");
                if let Some(condition) = data.condition {
                    self.writer.write(" ");
                    self.emit_expression(condition, 0)?;
                }
                self.writer.write(";");
                if let Some(incrementor) = data.incrementor {
                    self.writer.write(" ");
                    self.emit_expression(incrementor, 0)?;
                }
                self.writer.write(") ");
                self.emit_embedded(data.statement)?;
            }
            NodeData::ForInOrOfStatement(data) => {
                if node.kind == SyntaxKind::ForOfStatement
                    && self.emit_es5_captured_for_of_loop(data)?
                {
                    self.writer.newline();
                    return Ok(());
                }
                if node.kind == SyntaxKind::ForOfStatement
                    && data.await_modifier.is_none()
                    && self.settings.target < ScriptTarget::Es2015
                {
                    if self.downlevel_iteration {
                        self.emit_downlevel_iterable_for_of(data)?;
                    } else {
                        self.emit_downlevel_for_of(id, data)?;
                    }
                    self.writer.newline();
                    return Ok(());
                }
                self.writer.write("for");
                if data.await_modifier.is_some() {
                    self.writer.write(" await");
                }
                self.writer.write(" (");
                if matches!(
                    &self.node(data.initializer)?.data,
                    NodeData::VariableDeclarationList(_)
                ) {
                    if self
                        .es5_async_hoisted_variable_lists
                        .contains(&data.initializer)
                    {
                        self.emit_es5_async_hoisted_loop_binding(data.initializer)?;
                    } else {
                        self.emit_variable_list(data.initializer, false)?;
                    }
                } else {
                    self.emit_expression(data.initializer, 0)?;
                }
                self.writer
                    .write(if node.kind == SyntaxKind::ForInStatement {
                        " in "
                    } else {
                        " of "
                    });
                self.emit_expression(data.expression, 0)?;
                self.writer.write(") ");
                self.emit_embedded(data.statement)?;
            }
            NodeData::SwitchStatement(data) => self.emit_switch(data)?,
            NodeData::TryStatement(data) => self.emit_try(data)?,
            NodeData::ThrowStatement(data) => {
                self.writer.write("throw ");
                self.emit_expression(data.expression, 0)?;
                self.writer.write(";");
            }
            NodeData::BreakStatement(data) => {
                if let Some(target) = self.es5_async_control_case(id, false) {
                    self.writer.write("return [3 /*break*/, ");
                    self.writer.write(&target.to_string());
                    self.writer.write("];");
                    self.writer.newline();
                    return Ok(());
                }
                self.writer.write("break");
                if let Some(label) = data.label {
                    self.writer.write(" ");
                    self.emit_expression(label, 0)?;
                }
                self.writer.write(";");
            }
            NodeData::ContinueStatement(data) => {
                if let Some(target) = self.es5_async_control_case(id, true) {
                    self.writer.write("return [3 /*break*/, ");
                    self.writer.write(&target.to_string());
                    self.writer.write("];");
                    self.writer.newline();
                    return Ok(());
                }
                if data.label.is_none() && self.continue_targets_captured_loop(id) {
                    self.writer.write("return \"continue\";");
                    self.writer.newline();
                    return Ok(());
                }
                self.writer.write("continue");
                let keyword_end = node.range.start.get().saturating_add(8);
                if let Some(label) = data.label {
                    let label_start = self.node(label)?.range.start.get();
                    if self.trivia_has_block_comment(keyword_end, label_start) {
                        self.emit_inline_block_comments_between(keyword_end, label_start, true);
                    } else {
                        self.writer.write(" ");
                    }
                    self.emit_expression(label, 0)?;
                    self.emit_inline_block_comments_between(
                        self.node(label)?.range.end.get(),
                        node.range.end.get(),
                        true,
                    );
                } else {
                    self.emit_inline_block_comments_between(
                        keyword_end,
                        node.range.end.get(),
                        true,
                    );
                }
                self.writer.remove_trailing_spaces();
                self.writer.write(";");
            }
            NodeData::DebuggerStatement(_) => self.writer.write("debugger;"),
            NodeData::LabeledStatement(data) => {
                self.emit_expression(data.label, 0)?;
                self.writer.write(": ");
                self.emit_statement(data.statement)?;
                return Ok(());
            }
            NodeData::WithStatement(data) => {
                self.writer.write("with (");
                self.emit_expression(data.expression, 0)?;
                self.writer.write(") ");
                self.emit_embedded(data.statement)?;
            }
            NodeData::ImportDeclaration(data) => self.emit_import(data)?,
            NodeData::ImportEqualsDeclaration(data) => {
                if !self.is_external_import_equals(data)
                    && self.import_equals_is_namespace_member(data)
                    && !self.has_modifier(data.modifiers.as_ref(), SyntaxKind::ExportKeyword)
                    && !self.import_binding_is_used(data.name)
                    && self.identifier_text(data.name).is_ok_and(|name| {
                        !self.import_name_has_runtime_alias_chain(name, &mut HashSet::new())
                    })
                {
                    return Ok(());
                }
                if !self.import_equals_has_runtime_use(id, data) {
                    return Ok(());
                }
                self.emit_import_equals(data)?;
            }
            NodeData::ExportAssignment(data) => {
                if data.is_export_equals {
                    if node.parent.is_some_and(|parent| {
                        matches!(
                            self.arena.get(parent).map(|node| &node.data),
                            Some(NodeData::SourceFile(_))
                        )
                    }) {
                        return Ok(());
                    }
                    self.writer.write("export = ");
                    self.emit_expression(data.expression, 0)?;
                    self.writer.write(";");
                } else {
                    if !self.statement_emits_runtime(id, &node) {
                        return Ok(());
                    }
                    if self.commonjs_module_transform {
                        self.writer.write("exports.default = ");
                    } else {
                        self.writer.write("export default ");
                    }
                    let precedence = if self.settings.target < ScriptTarget::Es2015
                        && matches!(self.node(data.expression)?.data, NodeData::ArrowFunction(_))
                    {
                        3
                    } else {
                        0
                    };
                    self.emit_expression(data.expression, precedence)?;
                    self.writer.write(";");
                }
            }
            NodeData::ExportDeclaration(data) => self.emit_export(data)?,
            NodeData::ExpressionStatement(data) => {
                let precedence = if self.settings.target < ScriptTarget::Es2015
                    && matches!(self.node(data.expression)?.data, NodeData::ArrowFunction(_))
                {
                    3
                } else {
                    0
                };
                let wrap_erased_function =
                    self.expression_statement_starts_with_erased_function(data.expression);
                if wrap_erased_function {
                    self.writer.write("(");
                }
                self.emit_expression(data.expression, precedence)?;
                if wrap_erased_function {
                    self.writer.write(")");
                }
                if let Some(semicolon) = self.source_punctuation_between(
                    self.node(data.expression)?.range.end.get(),
                    node.range.end.get(),
                    b';',
                ) {
                    self.emit_binary_comment_trivia(
                        self.node(data.expression)?.range.end.get(),
                        semicolon,
                    );
                    self.writer.remove_trailing_spaces();
                }
                self.writer.write(";");
            }
            _ => return Err(Self::unsupported(id, node.kind)),
        }
        for (range, comment) in std::mem::take(&mut self.pending_statement_line_comments) {
            if self.emitted_source_comments.insert(range) {
                self.writer.write(" ");
                self.writer.write(&comment);
            }
        }
        self.writer.newline();
        Ok(())
    }

    fn continue_targets_captured_loop(&self, statement: NodeId) -> bool {
        let Some(target_body) = self.captured_loop_body else {
            return false;
        };
        let mut current = statement;
        while let Some(parent) = self.arena.get(current).and_then(|node| node.parent) {
            if parent == target_body {
                return true;
            }
            if self.arena.get(parent).is_some_and(|node| {
                matches!(
                    node.kind,
                    SyntaxKind::ForStatement
                        | SyntaxKind::ForInStatement
                        | SyntaxKind::ForOfStatement
                        | SyntaxKind::WhileStatement
                        | SyntaxKind::DoStatement
                )
            }) {
                return false;
            }
            current = parent;
        }
        false
    }

    fn emit_switch(&mut self, data: &ts_ast::SwitchStatementData) -> Result<(), EmitError> {
        self.writer.write("switch (");
        self.emit_expression(data.expression, 0)?;
        self.writer.write(") {");
        self.writer.newline();
        let block_node = self.node(data.case_block)?.clone();
        let NodeData::CaseBlock(block) = &block_node.data else {
            return Err(Self::unsupported(data.case_block, block_node.kind));
        };
        self.writer.indent += 1;
        let mut previous_end = block_node.range.start.get().saturating_add(1);
        let mut previous_emitted = false;
        for (clause_index, clause_id) in block.clauses.nodes.iter().enumerate() {
            let clause_node = self.node(*clause_id)?.clone();
            let NodeData::CaseOrDefaultClause(clause) = &clause_node.data else {
                return Err(Self::unsupported(*clause_id, clause_node.kind));
            };
            self.emit_source_comments_between_with_trailing(
                previous_end,
                clause_node.range.start.get(),
                previous_emitted,
            );
            if clause_node.kind == SyntaxKind::DefaultClause {
                self.writer.write("default:");
            } else {
                self.writer.write("case ");
                self.emit_expression(clause.expression, 0)?;
                self.writer.write(":");
            }
            let comment_end = clause
                .statements
                .nodes
                .first()
                .and_then(|statement| self.arena.get(*statement))
                .map(|node| node.range.start.get())
                .or_else(|| {
                    block
                        .clauses
                        .nodes
                        .get(clause_index + 1)
                        .and_then(|next| self.arena.get(*next))
                        .map(|node| node.range.start.get())
                })
                .unwrap_or_else(|| block_node.range.end.get().saturating_sub(1));
            if let Some(comment_start) =
                self.switch_clause_colon_end(&clause_node, clause, comment_end)
            {
                self.emit_source_comments_between_with_ownership(
                    comment_start,
                    comment_end,
                    true,
                    false,
                );
            }
            if let [statement] = clause.statements.nodes.as_slice()
                && matches!(
                    self.node(*statement)?.data,
                    NodeData::Block(_)
                        | NodeData::BreakStatement(_)
                        | NodeData::ContinueStatement(_)
                        | NodeData::ExpressionStatement(_)
                        | NodeData::ReturnStatement(_)
                )
                && self.switch_clause_statement_is_inline(*clause_id, *statement)
            {
                self.writer.write(" ");
                self.emit_statement(*statement)?;
                self.writer.remove_trailing_newline();
                self.writer.newline();
                let statement_node = self.node(*statement)?;
                previous_end = statement_node.range.end.get();
                previous_emitted = statement_emits_javascript(self.arena, statement_node);
            } else {
                if !self.writer.line_start {
                    self.writer.newline();
                }
                self.writer.indent += 1;
                previous_end = clause_node.range.start.get();
                previous_emitted = false;
                for statement in &clause.statements.nodes {
                    let statement_node = self.node(*statement)?.clone();
                    self.emit_source_comments_between_with_trailing(
                        previous_end,
                        statement_node.range.start.get(),
                        previous_emitted,
                    );
                    self.emit_statement(*statement)?;
                    previous_end = statement_node.range.end.get();
                    previous_emitted = statement_emits_javascript(self.arena, &statement_node);
                }
                self.writer.indent -= 1;
            }
        }
        self.emit_source_comments_between_with_trailing(
            previous_end,
            block_node.range.end.get().saturating_sub(1),
            previous_emitted,
        );
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn switch_clause_colon_end(
        &self,
        clause_node: &Node,
        clause: &ts_ast::CaseOrDefaultClauseData,
        boundary: u32,
    ) -> Option<u32> {
        let start = if clause_node.kind == SyntaxKind::DefaultClause {
            clause_node.range.start.get()
        } else {
            self.arena.get(clause.expression)?.range.end.get()
        };
        let start_index = usize::try_from(start).ok()?;
        let end_index = usize::try_from(boundary).ok()?;
        let suffix = self.source_text.get(start_index..end_index)?;
        let colon = suffix.find(':')?;
        u32::try_from(start_index + colon + 1).ok()
    }

    fn switch_clause_statement_is_inline(&self, clause: NodeId, statement: NodeId) -> bool {
        if self.source_text.is_empty() {
            return true;
        }
        let Some(clause) = self.arena.get(clause) else {
            return false;
        };
        let Some(statement) = self.arena.get(statement) else {
            return false;
        };
        let start = usize::try_from(clause.range.start.get()).unwrap_or(usize::MAX);
        let end = usize::try_from(statement.range.start.get()).unwrap_or(usize::MAX);
        self.source_text
            .get(start..end)
            .is_some_and(|text| !text.contains(['\n', '\r']))
    }

    fn emit_if_statement(&mut self, data: &ts_ast::IfStatementData) -> Result<(), EmitError> {
        self.writer.write("if (");
        self.emit_expression(data.expression, 0)?;
        self.writer.write(") ");
        self.emit_embedded(data.then_statement)?;
        if let Some(otherwise) = data.else_statement {
            self.writer.newline();
            self.writer.write("else ");
            let otherwise_node = self.node(otherwise)?.clone();
            if let NodeData::IfStatement(otherwise) = &otherwise_node.data {
                self.emit_if_statement(otherwise)?;
            } else {
                self.emit_embedded(otherwise)?;
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn emit_es5_captured_do_loop(
        &mut self,
        data: &ts_ast::DoStatementData,
    ) -> Result<bool, EmitError> {
        if self.settings.target >= ScriptTarget::Es2015 {
            return Ok(false);
        }
        let body_node = self.node(data.statement)?.clone();
        let NodeData::Block(block) = &body_node.data else {
            return Ok(false);
        };
        let mut captured = None;
        for statement_id in &block.statements.nodes {
            let Some(NodeData::VariableStatement(statement)) =
                self.arena.get(*statement_id).map(|node| &node.data)
            else {
                continue;
            };
            let Some(list_node) = self.arena.get(statement.declaration_list) else {
                continue;
            };
            let NodeData::VariableDeclarationList(list) = &list_node.data else {
                continue;
            };
            if !variable_list_is_block_scoped(list_node) {
                continue;
            }
            for declaration_id in &list.declarations.nodes {
                let Some(NodeData::VariableDeclaration(declaration)) =
                    self.arena.get(*declaration_id).map(|node| &node.data)
                else {
                    continue;
                };
                let Some(name) = declaration_name_text(self.arena, declaration.name) else {
                    continue;
                };
                let rewrite_symbols = self
                    .arena
                    .iter()
                    .filter_map(|(id, node)| {
                        let NodeData::Identifier(identifier) = &node.data else {
                            return None;
                        };
                        (id != declaration.name
                            && identifier.text == name
                            && node_is_in_nested_function(self.arena, id, data.statement))
                        .then(|| self.bindings.resolve_name_at(id, name))
                        .flatten()
                    })
                    .collect::<HashSet<_>>();
                if !rewrite_symbols.is_empty() {
                    captured = Some((
                        *statement_id,
                        declaration.initializer,
                        rewrite_symbols,
                        name.to_owned(),
                    ));
                    break;
                }
            }
            if captured.is_some() {
                break;
            }
        }
        let Some((captured_statement, captured_initializer, rewrite_symbols, captured_name)) =
            captured
        else {
            return Ok(false);
        };
        let renamed = self.generated_names.generate(&captured_name);
        let loop_name = self.generated_names.generate("_loop");
        let mut hoisted = Vec::new();
        for statement_id in &block.statements.nodes {
            let Some(NodeData::VariableStatement(statement)) =
                self.arena.get(*statement_id).map(|node| &node.data)
            else {
                continue;
            };
            let Some(list_node) = self.arena.get(statement.declaration_list) else {
                continue;
            };
            if list_node.flags.0 & 3 != 0 {
                continue;
            }
            hoisted.extend(simple_variable_names(
                self.arena,
                statement.declaration_list,
            ));
        }

        self.writer.write("var ");
        self.writer.write(&loop_name);
        self.writer.write(" = function () {");
        self.writer.newline();
        self.writer.indent += 1;
        let previous_rewrites = rewrite_symbols
            .iter()
            .map(|symbol| {
                (
                    *symbol,
                    self.identifier_rewrites.insert(*symbol, renamed.clone()),
                )
            })
            .collect::<Vec<_>>();
        for statement_id in &block.statements.nodes {
            if *statement_id == captured_statement {
                self.writer.write("var ");
                self.writer.write(&renamed);
                if let Some(initializer) = captured_initializer {
                    self.writer.write(" = ");
                    self.emit_expression(initializer, 1)?;
                }
                self.writer.write(";");
                self.writer.newline();
                continue;
            }
            if let Some(NodeData::VariableStatement(statement)) =
                self.arena.get(*statement_id).map(|node| &node.data)
                && let Some(list_node) = self.arena.get(statement.declaration_list)
                && !variable_list_is_block_scoped(list_node)
                && let NodeData::VariableDeclarationList(list) = &list_node.data
            {
                for declaration_id in &list.declarations.nodes {
                    let Some(NodeData::VariableDeclaration(declaration)) =
                        self.arena.get(*declaration_id).map(|node| &node.data)
                    else {
                        continue;
                    };
                    let Some(initializer) = declaration.initializer else {
                        continue;
                    };
                    self.emit_expression(declaration.name, 1)?;
                    self.writer.write(" = ");
                    self.emit_expression(initializer, 1)?;
                    self.writer.write(";");
                    self.writer.newline();
                }
                continue;
            }
            self.emit_statement(*statement_id)?;
        }
        for (symbol, rewrite) in previous_rewrites {
            if let Some(rewrite) = rewrite {
                self.identifier_rewrites.insert(symbol, rewrite);
            } else {
                self.identifier_rewrites.remove(&symbol);
            }
        }
        self.writer.indent -= 1;
        self.writer.write("};");
        self.writer.newline();
        if !hoisted.is_empty() {
            self.writer.write("var ");
            self.writer.write(&hoisted.join(", "));
            self.writer.write(";");
            self.writer.newline();
        }
        self.writer.write("do {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write(&loop_name);
        self.writer.write("();");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("} while (");
        self.emit_expression(data.expression, 0)?;
        self.writer.write(");");
        Ok(true)
    }

    fn block_scoped_declaration_is_captured(&self, declaration_name: NodeId, body: NodeId) -> bool {
        let Some(name) = declaration_name_text(self.arena, declaration_name) else {
            return false;
        };
        let Some(symbol) = self
            .bindings
            .node_symbols
            .get(&declaration_name)
            .copied()
            .or_else(|| self.bindings.resolve_name_at(declaration_name, name))
        else {
            return false;
        };
        self.arena.iter().any(|(id, node)| {
            matches!(&node.data, NodeData::Identifier(identifier) if identifier.text == name)
                && id != declaration_name
                && node_is_in_nested_function(self.arena, id, body)
                && (self.bindings.resolve_name_at(id, name) == Some(symbol)
                    // A class field name and its initializer share the class's
                    // binding scope in the current binder.  The initializer's
                    // unqualified identifier can therefore be reported as the
                    // field symbol even though it lexically refers to the loop
                    // variable.  Classes become IIFEs for ES5, so recognize the
                    // value reference structurally as a capture.
                    || (node_is_in_nested_class(self.arena, id, body)
                        && identifier_is_unqualified_value_reference(self.arena, id)))
        })
    }

    #[allow(clippy::too_many_lines)]
    fn emit_es5_captured_for_loop(
        &mut self,
        data: &ts_ast::ForStatementData,
    ) -> Result<bool, EmitError> {
        if self.settings.target >= ScriptTarget::Es2015 {
            return Ok(false);
        }
        let body_node = self.node(data.statement)?.clone();
        let NodeData::Block(block) = &body_node.data else {
            return Ok(false);
        };
        let captured_initializer_names = self.es5_captured_for_initializer_names(data);
        let captured_body_declaration = block.statements.nodes.iter().any(|statement| {
            let Some(NodeData::VariableStatement(statement)) =
                self.arena.get(*statement).map(|node| &node.data)
            else {
                return false;
            };
            let Some(list_node) = self.arena.get(statement.declaration_list) else {
                return false;
            };
            let NodeData::VariableDeclarationList(list) = &list_node.data else {
                return false;
            };
            variable_list_is_block_scoped(list_node)
                && list.declarations.nodes.iter().any(|declaration| {
                    matches!(
                        self.arena.get(*declaration).map(|node| &node.data),
                        Some(NodeData::VariableDeclaration(declaration))
                            if self.block_scoped_declaration_is_captured(
                                declaration.name,
                                data.statement,
                            )
                    )
                })
        });
        if captured_initializer_names.is_empty() && !captured_body_declaration {
            return Ok(false);
        }

        let loop_name = self.generated_names.generate("_loop");
        let mut hoisted = Vec::new();
        self.writer.write("var ");
        self.writer.write(&loop_name);
        self.writer.write(" = function (");
        self.writer.write(&captured_initializer_names.join(", "));
        self.writer.write(") {");
        self.writer.newline();
        self.writer.indent += 1;
        self.prepare_synthetic_function_class_expression_temps(data.statement);
        for statement in &block.statements.nodes {
            if let Some(NodeData::VariableStatement(variable)) =
                self.arena.get(*statement).map(|node| &node.data)
                && let Some(list_node) = self.arena.get(variable.declaration_list)
                && !variable_list_is_block_scoped(list_node)
                && let NodeData::VariableDeclarationList(list) = &list_node.data
            {
                let mut emitted_initializer = false;
                for declaration_id in &list.declarations.nodes {
                    let Some(NodeData::VariableDeclaration(declaration)) =
                        self.arena.get(*declaration_id).map(|node| &node.data)
                    else {
                        continue;
                    };
                    if let Some(name) = declaration_name_text(self.arena, declaration.name) {
                        hoisted.push(name.to_owned());
                    }
                    if let Some(initializer) = declaration.initializer {
                        if emitted_initializer {
                            self.writer.write(", ");
                        }
                        self.emit_expression(declaration.name, 1)?;
                        self.writer.write(" = ");
                        self.emit_expression(initializer, 1)?;
                        emitted_initializer = true;
                    }
                }
                if emitted_initializer {
                    self.writer.write(";");
                    self.writer.newline();
                }
            } else {
                self.emit_statement(*statement)?;
            }
        }
        self.writer.indent -= 1;
        self.writer.write("};");
        self.writer.newline();
        if !hoisted.is_empty() {
            self.writer.write("var ");
            self.writer.write(&hoisted.join(", "));
            self.writer.write(";");
            self.writer.newline();
        }
        self.writer.write("for (");
        if let Some(initializer) = data.initializer {
            if matches!(
                self.arena.get(initializer).map(|node| &node.data),
                Some(NodeData::VariableDeclarationList(_))
            ) {
                self.emit_variable_list(initializer, false)?;
            } else {
                self.emit_expression(initializer, 0)?;
            }
        }
        self.writer.write(";");
        if let Some(condition) = data.condition {
            self.writer.write(" ");
            self.emit_expression(condition, 0)?;
        }
        self.writer.write(";");
        if let Some(incrementor) = data.incrementor {
            self.writer.write(" ");
            self.emit_expression(incrementor, 0)?;
        }
        self.writer.write(") {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write(&loop_name);
        self.writer.write("(");
        self.writer.write(&captured_initializer_names.join(", "));
        self.writer.write(");");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(true)
    }

    fn es5_captured_for_initializer_names(&self, data: &ts_ast::ForStatementData) -> Vec<String> {
        if self.settings.target >= ScriptTarget::Es2015 {
            return Vec::new();
        }
        let Some(initializer) = data.initializer else {
            return Vec::new();
        };
        let Some(initializer_node) = self.arena.get(initializer) else {
            return Vec::new();
        };
        let NodeData::VariableDeclarationList(list) = &initializer_node.data else {
            return Vec::new();
        };
        if !variable_list_is_block_scoped(initializer_node) {
            return Vec::new();
        }
        list.declarations
            .nodes
            .iter()
            .filter_map(|declaration| {
                let NodeData::VariableDeclaration(declaration) =
                    &self.arena.get(*declaration)?.data
                else {
                    return None;
                };
                self.block_scoped_declaration_is_captured(declaration.name, data.statement)
                    .then(|| declaration_name_text(self.arena, declaration.name).map(str::to_owned))
                    .flatten()
            })
            .collect()
    }

    fn prepare_synthetic_function_class_expression_temps(&mut self, body: NodeId) {
        let Some(body_range) = self.arena.get(body).map(|node| node.range) else {
            return;
        };
        let mut classes = self
            .arena
            .iter()
            .filter_map(|(id, node)| {
                let NodeData::ClassExpression(class) = &node.data else {
                    return None;
                };
                if !(body_range.start <= node.range.start && node.range.end <= body_range.end) {
                    return None;
                }
                let mut current = id;
                while let Some(parent) = self.arena.get(current).and_then(|node| node.parent) {
                    if parent == body {
                        break;
                    }
                    if matches!(
                        self.arena.get(parent).map(|node| &node.data),
                        Some(
                            NodeData::FunctionDeclaration(_)
                                | NodeData::FunctionExpression(_)
                                | NodeData::ArrowFunction(_)
                                | NodeData::MethodDeclaration(_)
                                | NodeData::ConstructorDeclaration(_)
                                | NodeData::GetAccessorDeclaration(_)
                                | NodeData::SetAccessorDeclaration(_)
                        )
                    ) {
                        return None;
                    }
                    current = parent;
                }
                let declaration = Self::class_expression_as_declaration(class);
                self.class_expression_requires_post_class_lowering(&declaration)
                    .then_some((node.range.start, id))
            })
            .collect::<Vec<_>>();
        classes.sort_by_key(|(start, _)| *start);
        if classes.is_empty() {
            return;
        }

        let mut claimed = HashSet::new();
        let mut temps = Vec::new();
        for (_, class_id) in classes {
            if let Some(NodeData::ClassExpression(class)) =
                self.arena.get(class_id).map(|node| &node.data)
            {
                let members = class.members.nodes.clone();
                self.prepare_class_expression_computed_property_temps(
                    &members,
                    body,
                    &mut claimed,
                    &mut temps,
                );
            }
            let temp = self.generate_block_temp(body, &claimed);
            claimed.insert(temp.clone());
            self.class_expression_temps.insert(class_id, temp.clone());
            temps.push(temp);
        }
        self.writer.write("var ");
        for (index, temp) in temps.iter().enumerate() {
            if index != 0 {
                self.writer.write(", ");
            }
            self.writer.write(temp);
            self.writer.write(" = void 0");
        }
        self.writer.write(";");
        self.writer.newline();
    }

    fn emit_es5_captured_for_of_loop(
        &mut self,
        data: &ts_ast::ForInOrOfStatementData,
    ) -> Result<bool, EmitError> {
        if self.settings.target >= ScriptTarget::Es2015 || data.await_modifier.is_some() {
            return Ok(false);
        }
        let initializer_node = self.node(data.initializer)?.clone();
        let NodeData::VariableDeclarationList(list) = &initializer_node.data else {
            return Ok(false);
        };
        if !variable_list_is_block_scoped(&initializer_node) {
            return Ok(false);
        }
        let Some(declaration_id) = list.declarations.nodes.first() else {
            return Ok(false);
        };
        let Some(NodeData::VariableDeclaration(declaration)) =
            self.arena.get(*declaration_id).map(|node| &node.data)
        else {
            return Ok(false);
        };
        let Some(parameter) = declaration_name_text(self.arena, declaration.name) else {
            return Ok(false);
        };
        if !self.block_scoped_declaration_is_captured(declaration.name, data.statement) {
            return Ok(false);
        }
        let body_node = self.node(data.statement)?.clone();
        let NodeData::Block(block) = &body_node.data else {
            return Ok(false);
        };
        let loop_name = self.generated_names.generate("_loop");
        self.writer.write("var ");
        self.writer.write(&loop_name);
        self.writer.write(" = function (");
        self.writer.write(parameter);
        self.writer.write(") {");
        self.writer.newline();
        self.writer.indent += 1;
        let previous_captured_loop_body = self.captured_loop_body.replace(data.statement);
        let result = (|| {
            let mut previous_end = body_node.range.start.get().saturating_add(1);
            let mut previous_emitted = false;
            for statement in &block.statements.nodes {
                let statement_node = self.node(*statement)?.clone();
                self.emit_source_comments_between_with_trailing(
                    previous_end,
                    statement_node.range.start.get(),
                    previous_emitted,
                );
                self.emit_statement(*statement)?;
                previous_end = statement_node.range.end.get();
                previous_emitted = statement_emits_javascript(self.arena, &statement_node);
            }
            self.emit_source_comments_between_with_trailing(
                previous_end,
                body_node.range.end.get().saturating_sub(1),
                previous_emitted,
            );
            Ok::<(), EmitError>(())
        })();
        self.captured_loop_body = previous_captured_loop_body;
        result?;
        self.writer.indent -= 1;
        self.writer.write("};");
        self.writer.newline();

        let counter = self.generated_names.generate_loop_variable();
        let rhs = match self.node(data.expression)?.data.clone() {
            NodeData::Identifier(identifier) => self.generated_names.generate(&identifier.text),
            _ => self.generated_names.generate_temp(),
        };
        self.writer.write("for (var ");
        self.writer.write(&counter);
        self.writer.write(" = 0, ");
        self.writer.write(&rhs);
        self.writer.write(" = ");
        self.emit_expression(data.expression, 1)?;
        self.writer.write("; ");
        self.writer.write(&counter);
        self.writer.write(" < ");
        self.writer.write(&rhs);
        self.writer.write(".length; ");
        self.writer.write(&counter);
        self.writer.write("++) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("var ");
        self.writer.write(parameter);
        self.writer.write(" = ");
        self.writer.write(&rhs);
        self.writer.write("[");
        self.writer.write(&counter);
        self.writer.write("];");
        self.writer.newline();
        self.writer.write(&loop_name);
        self.writer.write("(");
        self.writer.write(parameter);
        self.writer.write(");");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(true)
    }

    fn emit_try(&mut self, data: &ts_ast::TryStatementData) -> Result<(), EmitError> {
        self.writer.write("try ");
        self.emit_block(data.try_block)?;
        if let Some(catch_id) = data.catch_clause {
            let catch_node = self.node(catch_id)?.clone();
            let NodeData::CatchClause(catch) = &catch_node.data else {
                return Err(Self::unsupported(catch_id, catch_node.kind));
            };
            self.writer.newline();
            self.writer.write("catch");
            if let Some(variable_id) = catch.variable_declaration {
                let variable_node = self.node(variable_id)?.clone();
                let NodeData::VariableDeclaration(variable) = &variable_node.data else {
                    return Err(Self::unsupported(variable_id, variable_node.kind));
                };
                self.writer.write(" (");
                self.emit_expression(variable.name, 0)?;
                if let Some(initializer) = variable.initializer {
                    self.writer.write(" = ");
                    self.emit_expression(initializer, 1)?;
                }
                self.writer.write(")");
            } else if self.settings.target < ScriptTarget::Es2019 {
                let variable = self.generated_names.generate_temp();
                self.writer.write(" (");
                self.writer.write(&variable);
                self.writer.write(")");
            }
            self.writer.write(" ");
            self.emit_block(catch.block)?;
        }
        if let Some(finally_block) = data.finally_block {
            self.writer.newline();
            self.writer.write("finally ");
            self.emit_block(finally_block)?;
        }
        Ok(())
    }

    fn emit_downlevel_for_of(
        &mut self,
        statement: NodeId,
        data: &ts_ast::ForInOrOfStatementData,
    ) -> Result<(), EmitError> {
        let planned = self.es5_async_for_of_names.get(&statement).cloned();
        let (counter, rhs, binding_temp) = if let Some(plan) = &planned {
            (
                plan.counter.clone(),
                plan.rhs.clone(),
                plan.pattern_temp.clone(),
            )
        } else {
            self.scoped_downlevel_for_of_names(statement, data.expression)
        };
        self.writer.write("for (");
        if planned.is_none() {
            self.writer.write("var ");
        }
        self.writer.write(&counter);
        self.writer.write(" = 0, ");
        self.writer.write(&rhs);
        self.writer.write(" = ");
        self.emit_expression(data.expression, 1)?;
        self.writer.write("; ");
        self.writer.write(&counter);
        self.writer.write(" < ");
        self.writer.write(&rhs);
        self.writer.write(".length; ");
        self.writer.write(&counter);
        self.writer.write("++) ");
        let value = DownlevelBindingValue::Element(
            Box::new(DownlevelBindingValue::Name(rhs)),
            DownlevelBindingIndex::Name(counter),
        );
        self.emit_downlevel_for_of_body(
            data.statement,
            data.initializer,
            &value,
            binding_temp.as_deref(),
        )
    }

    fn scoped_downlevel_for_of_names(
        &self,
        statement: NodeId,
        expression: NodeId,
    ) -> (String, String, Option<String>) {
        let container = self.nearest_function_like_container(statement);
        let mut used = self
            .arena
            .iter()
            .filter_map(|(id, node)| {
                (self.nearest_function_like_container(id) == container)
                    .then_some(node)
                    .and_then(|node| match &node.data {
                        NodeData::Identifier(identifier) => Some(identifier.text.clone()),
                        _ => None,
                    })
            })
            .collect::<HashSet<_>>();
        let mut loops = self
            .arena
            .iter()
            .filter(|(id, node)| {
                node.kind == SyntaxKind::ForOfStatement
                    && self.nearest_function_like_container(*id) == container
                    && node.range.start.get()
                        <= self
                            .arena
                            .get(statement)
                            .map_or(u32::MAX, |statement| statement.range.start.get())
            })
            .map(|(id, node)| (node.range.start.get(), id))
            .collect::<Vec<_>>();
        loops.sort_by_key(|(start, _)| *start);

        let mut current = (String::new(), String::new(), None);
        for (_, loop_id) in loops {
            let counter = if used.insert("_i".to_owned()) {
                "_i".to_owned()
            } else {
                Self::generate_scoped_temp(&mut used)
            };
            let loop_expression = if loop_id == statement {
                expression
            } else {
                match self.arena.get(loop_id).map(|node| &node.data) {
                    Some(NodeData::ForInOrOfStatement(data)) => data.expression,
                    _ => expression,
                }
            };
            let rhs = match self.arena.get(loop_expression).map(|node| &node.data) {
                Some(NodeData::Identifier(identifier)) => {
                    let mut index = 1_u32;
                    loop {
                        let candidate = format!("{}_{}", identifier.text, index);
                        if used.insert(candidate.clone()) {
                            break candidate;
                        }
                        index += 1;
                    }
                }
                _ => Self::generate_scoped_temp(&mut used),
            };
            let binding_temp = match self.arena.get(loop_id).map(|node| &node.data) {
                Some(NodeData::ForInOrOfStatement(data))
                    if self.downlevel_for_of_initializer_needs_temp(data.initializer) =>
                {
                    Some(Self::generate_scoped_temp(&mut used))
                }
                _ => None,
            };
            current = (counter, rhs, binding_temp);
        }
        current
    }

    fn downlevel_for_of_initializer_needs_temp(&self, initializer: NodeId) -> bool {
        let Some(NodeData::VariableDeclarationList(list)) =
            self.arena.get(initializer).map(|node| &node.data)
        else {
            return false;
        };
        let Some(NodeData::VariableDeclaration(declaration)) = list
            .declarations
            .nodes
            .first()
            .and_then(|declaration| self.arena.get(*declaration))
            .map(|node| &node.data)
        else {
            return false;
        };
        matches!(
            self.arena.get(declaration.name).map(|node| node.kind),
            Some(SyntaxKind::ArrayBindingPattern | SyntaxKind::ObjectBindingPattern)
        ) && !self.binding_pattern_has_single_simple_leaf(declaration.name)
    }

    fn generate_scoped_temp(used: &mut HashSet<String>) -> String {
        let mut count = 0_u32;
        loop {
            if let Some(candidate) = generated_temp_name(count)
                && used.insert(candidate.clone())
            {
                return candidate;
            }
            count += 1;
        }
    }

    fn emit_downlevel_iterable_for_of(
        &mut self,
        data: &ts_ast::ForInOrOfStatementData,
    ) -> Result<(), EmitError> {
        let iterator = match self.node(data.expression)?.data.clone() {
            NodeData::Identifier(identifier) => self.generated_names.generate(&identifier.text),
            _ => self.generated_names.generate_temp(),
        };
        let step = self.generated_names.generate(&iterator);
        let error = self.generated_names.generate("e");
        let caught = self.generated_names.generate(&error);
        let return_method = self.generated_names.generate_temp();

        self.writer.write("var ");
        self.writer.write(&error);
        self.writer.write(", ");
        self.writer.write(&return_method);
        self.writer.write(";");
        self.writer.newline();
        self.writer.write("try {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("for (var ");
        self.writer.write(&iterator);
        self.writer.write(" = __values(");
        self.emit_expression(data.expression, 1)?;
        self.writer.write("), ");
        self.writer.write(&step);
        self.writer.write(" = ");
        self.writer.write(&iterator);
        self.writer.write(".next(); !");
        self.writer.write(&step);
        self.writer.write(".done; ");
        self.writer.write(&step);
        self.writer.write(" = ");
        self.writer.write(&iterator);
        self.writer.write(".next()) ");
        let value = DownlevelBindingValue::Element(
            Box::new(DownlevelBindingValue::Name(step.clone())),
            DownlevelBindingIndex::String("value".to_owned()),
        );
        self.emit_downlevel_for_of_body(data.statement, data.initializer, &value, None)?;
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        self.writer.newline();
        self.writer.write("catch (");
        self.writer.write(&caught);
        self.writer.write(") { ");
        self.writer.write(&error);
        self.writer.write(" = { error: ");
        self.writer.write(&caught);
        self.writer.write(" }; }");
        self.writer.newline();
        self.writer.write("finally {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("try {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("if (");
        self.writer.write(&step);
        self.writer.write(" && !");
        self.writer.write(&step);
        self.writer.write(".done && (");
        self.writer.write(&return_method);
        self.writer.write(" = ");
        self.writer.write(&iterator);
        self.writer.write(".return)) ");
        self.writer.write(&return_method);
        self.writer.write(".call(");
        self.writer.write(&iterator);
        self.writer.write(");");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        self.writer.newline();
        self.writer.write("finally { if (");
        self.writer.write(&error);
        self.writer.write(") throw ");
        self.writer.write(&error);
        self.writer.write(".error; }");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn emit_downlevel_for_of_body(
        &mut self,
        body: NodeId,
        initializer: NodeId,
        value: &DownlevelBindingValue,
        binding_temp: Option<&str>,
    ) -> Result<(), EmitError> {
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.emit_downlevel_for_of_binding(initializer, value, binding_temp)?;

        let body_node = self.node(body)?.clone();
        if let NodeData::Block(block) = &body_node.data {
            let mut previous_end = body_node.range.start.get().saturating_add(1);
            let mut previous_emitted = true;
            for statement in &block.statements.nodes {
                let statement_node = self.node(*statement)?.clone();
                self.emit_source_comments_between_with_trailing(
                    previous_end,
                    statement_node.range.start.get(),
                    previous_emitted,
                );
                self.emit_statement(*statement)?;
                previous_end = statement_node.range.end.get();
                previous_emitted = statement_emits_javascript(self.arena, &statement_node);
            }
            self.emit_source_comments_between_with_trailing(
                previous_end,
                body_node.range.end.get().saturating_sub(1),
                previous_emitted,
            );
        } else {
            self.emit_statement(body)?;
        }
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn emit_downlevel_for_of_binding(
        &mut self,
        initializer: NodeId,
        value: &DownlevelBindingValue,
        binding_temp: Option<&str>,
    ) -> Result<(), EmitError> {
        let initializer_node = self.node(initializer)?.clone();
        if let NodeData::VariableDeclarationList(list) = &initializer_node.data {
            if self.es5_async_hoisted_variable_lists.contains(&initializer)
                && let Some(declaration_id) = list.declarations.nodes.first()
                && let NodeData::VariableDeclaration(declaration) =
                    &self.node(*declaration_id)?.data
                && matches!(self.node(declaration.name)?.data, NodeData::Identifier(_))
            {
                self.emit_expression(declaration.name, 1)?;
                self.writer.write(" = ");
                self.emit_downlevel_binding_value(value)?;
                self.writer.write(";");
                self.writer.newline();
                return Ok(());
            }
            self.writer.write("var ");
            let mut emitted = false;
            if let Some(declaration_id) = list.declarations.nodes.first() {
                let declaration_node = self.node(*declaration_id)?.clone();
                let NodeData::VariableDeclaration(declaration) = &declaration_node.data else {
                    return Err(Self::unsupported(*declaration_id, declaration_node.kind));
                };
                let binding_value = if matches!(
                    self.node(declaration.name)?.kind,
                    SyntaxKind::ArrayBindingPattern | SyntaxKind::ObjectBindingPattern
                ) && !self
                    .binding_pattern_has_single_simple_leaf(declaration.name)
                {
                    let temp = binding_temp
                        .map_or_else(|| self.generated_names.generate_temp(), str::to_owned);
                    self.emit_downlevel_declarator_start(&mut emitted);
                    self.writer.write(&temp);
                    self.writer.write(" = ");
                    self.emit_downlevel_binding_value(value)?;
                    DownlevelBindingValue::Name(temp)
                } else {
                    (*value).clone()
                };
                self.emit_downlevel_binding_declarators(
                    declaration.name,
                    binding_value,
                    None,
                    &mut emitted,
                    true,
                )?;
            }
            if !emitted {
                let temp = self.generated_names.generate_temp();
                self.emit_downlevel_declarator_start(&mut emitted);
                self.writer.write(&temp);
                self.writer.write(" = ");
                self.emit_downlevel_binding_value(value)?;
            }
            self.writer.write(";");
        } else {
            self.emit_expression(initializer, 1)?;
            self.writer.write(" = ");
            self.emit_downlevel_binding_value(value)?;
            self.writer.write(";");
        }
        self.writer.newline();
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn emit_downlevel_binding_declarators(
        &mut self,
        name: NodeId,
        value: DownlevelBindingValue,
        initializer: Option<NodeId>,
        emitted: &mut bool,
        inline_single_leaf_nested: bool,
    ) -> Result<(), EmitError> {
        let value = if let Some(initializer) = initializer {
            let temp = self.generated_names.generate_temp();
            self.emit_downlevel_declarator_start(emitted);
            self.writer.write(&temp);
            self.writer.write(" = ");
            self.emit_downlevel_binding_value(&value)?;
            let defaulted = self.generated_names.generate_temp();
            self.emit_downlevel_declarator_start(emitted);
            self.writer.write(&defaulted);
            self.writer.write(" = ");
            self.writer.write(&temp);
            self.writer.write(" === void 0 ? ");
            self.emit_expression(initializer, 2)?;
            self.writer.write(" : ");
            self.writer.write(&temp);
            DownlevelBindingValue::Name(defaulted)
        } else {
            value
        };

        let name_node = self.node(name)?.clone();
        match &name_node.data {
            NodeData::Identifier(_) => {
                self.emit_downlevel_declarator_start(emitted);
                self.emit_expression(name, 0)?;
                self.writer.write(" = ");
                self.emit_downlevel_binding_value(&value)?;
            }
            NodeData::BindingPattern(pattern)
                if name_node.kind == SyntaxKind::ArrayBindingPattern =>
            {
                let mut index = 0_usize;
                let mut previous_end = name_node.range.start.get().saturating_add(1);
                for element_id in &pattern.elements.nodes {
                    let element_node = self.node(*element_id)?.clone();
                    index += self
                        .array_binding_comma_count(previous_end, element_node.range.start.get());
                    if matches!(element_node.data, NodeData::OmittedExpression(_)) {
                        previous_end = element_node.range.end.get();
                        continue;
                    }
                    let NodeData::BindingElement(element) = &element_node.data else {
                        return Err(Self::unsupported(*element_id, element_node.kind));
                    };
                    let Some(element_name) = element.name else {
                        continue;
                    };
                    let mut element_value = if element.dot_dot_dot_token.is_some() {
                        DownlevelBindingValue::Slice(Box::new(value.clone()), index)
                    } else {
                        DownlevelBindingValue::Element(
                            Box::new(value.clone()),
                            DownlevelBindingIndex::Number(index),
                        )
                    };
                    let nested_kind = self.node(element_name)?.kind;
                    let nested_single_leaf =
                        self.binding_pattern_has_single_simple_leaf(element_name);
                    if element.initializer.is_none()
                        && ((nested_kind == SyntaxKind::ArrayBindingPattern
                            && !(inline_single_leaf_nested && nested_single_leaf))
                            || (nested_kind == SyntaxKind::ObjectBindingPattern
                                && !nested_single_leaf))
                    {
                        let temp = self.generated_names.generate_temp();
                        self.emit_downlevel_declarator_start(emitted);
                        self.writer.write(&temp);
                        self.writer.write(" = ");
                        self.emit_downlevel_binding_value(&element_value)?;
                        element_value = DownlevelBindingValue::Name(temp);
                    }
                    self.emit_downlevel_binding_declarators(
                        element_name,
                        element_value,
                        element.initializer,
                        emitted,
                        inline_single_leaf_nested,
                    )?;
                    previous_end = element_node.range.end.get();
                }
            }
            NodeData::BindingPattern(pattern)
                if name_node.kind == SyntaxKind::ObjectBindingPattern =>
            {
                for element_id in &pattern.elements.nodes {
                    let element_node = self.node(*element_id)?.clone();
                    let NodeData::BindingElement(element) = &element_node.data else {
                        return Err(Self::unsupported(*element_id, element_node.kind));
                    };
                    let Some(element_name) = element.name else {
                        continue;
                    };
                    if element.dot_dot_dot_token.is_some() {
                        return Err(Self::unsupported(*element_id, element_node.kind));
                    }
                    let property = element.property_name.unwrap_or(element_name);
                    let index = match &self.node(property)?.data {
                        NodeData::ComputedPropertyName(computed) => {
                            let expression = computed.expression;
                            let temp = self.generated_names.generate_temp();
                            self.emit_downlevel_declarator_start(emitted);
                            self.writer.write(&temp);
                            self.writer.write(" = ");
                            self.emit_expression(expression, 1)?;
                            DownlevelBindingIndex::Name(temp)
                        }
                        NodeData::Identifier(identifier) => {
                            DownlevelBindingIndex::String(identifier.text.clone())
                        }
                        NodeData::StringLiteral(literal) => {
                            DownlevelBindingIndex::String(literal.text.clone())
                        }
                        NodeData::NumericLiteral(literal) => {
                            DownlevelBindingIndex::String(literal.text.clone())
                        }
                        _ => return Err(Self::unsupported(property, self.node(property)?.kind)),
                    };
                    let element_value =
                        DownlevelBindingValue::Element(Box::new(value.clone()), index);
                    self.emit_downlevel_binding_declarators(
                        element_name,
                        element_value,
                        element.initializer,
                        emitted,
                        inline_single_leaf_nested,
                    )?;
                }
            }
            _ => return Err(Self::unsupported(name, name_node.kind)),
        }
        Ok(())
    }

    fn array_binding_comma_count(&self, start: u32, end: u32) -> usize {
        let start = usize::try_from(start).unwrap_or(usize::MAX);
        let end = usize::try_from(end).unwrap_or(usize::MAX);
        let Some(text) = self.source_text.get(start..end) else {
            return 0;
        };
        let bytes = text.as_bytes();
        let mut index = 0;
        let mut commas = 0;
        while index < bytes.len() {
            if bytes[index..].starts_with(b"//") {
                index += 2;
                while index < bytes.len() && !matches!(bytes[index], b'\n' | b'\r') {
                    index += 1;
                }
            } else if bytes[index..].starts_with(b"/*") {
                index += 2;
                while index + 1 < bytes.len() && !bytes[index..].starts_with(b"*/") {
                    index += 1;
                }
                index = (index + 2).min(bytes.len());
            } else {
                commas += usize::from(bytes[index] == b',');
                index += 1;
            }
        }
        commas
    }

    fn emit_downlevel_declarator_start(&mut self, emitted: &mut bool) {
        if *emitted {
            self.writer.write(", ");
        }
        *emitted = true;
    }

    fn emit_downlevel_binding_value(
        &mut self,
        value: &DownlevelBindingValue,
    ) -> Result<(), EmitError> {
        match value {
            DownlevelBindingValue::Node(node) => self.emit_expression(*node, 18)?,
            DownlevelBindingValue::Name(name) => self.writer.write(name),
            DownlevelBindingValue::Element(value, index) => {
                self.emit_downlevel_binding_value(value)?;
                if let DownlevelBindingIndex::String(name) = index
                    && is_identifier_text(name)
                {
                    self.writer.write(".");
                    self.writer.write(name);
                    return Ok(());
                }
                self.writer.write("[");
                match index {
                    DownlevelBindingIndex::Number(index) => {
                        self.writer.write(&index.to_string());
                    }
                    DownlevelBindingIndex::Name(name) => self.writer.write(name),
                    DownlevelBindingIndex::String(name) => {
                        write_quoted(&mut self.writer, name);
                    }
                }
                self.writer.write("]");
            }
            DownlevelBindingValue::Slice(value, index) => {
                self.emit_downlevel_binding_value(value)?;
                self.writer.write(".slice(");
                self.writer.write(&index.to_string());
                self.writer.write(")");
            }
            DownlevelBindingValue::VoidZero => self.writer.write("void 0"),
        }
        Ok(())
    }

    fn prepare_commonjs_empty_binding_temps(&mut self, statements: &NodeList) {
        for statement in &statements.nodes {
            let Some(node) = self.arena.get(*statement) else {
                continue;
            };
            let NodeData::VariableStatement(variable) = &node.data else {
                continue;
            };
            if !self.has_modifier(variable.modifiers.as_ref(), SyntaxKind::ExportKeyword) {
                continue;
            }
            let Some(NodeData::VariableDeclarationList(list)) = self
                .arena
                .get(variable.declaration_list)
                .map(|node| &node.data)
            else {
                continue;
            };
            let [declaration_id] = list.declarations.nodes.as_slice() else {
                continue;
            };
            let Some(NodeData::VariableDeclaration(declaration)) =
                self.arena.get(*declaration_id).map(|node| &node.data)
            else {
                continue;
            };
            let Some(pattern_node) = self.arena.get(declaration.name) else {
                continue;
            };
            let supported_pattern = matches!(
                pattern_node.kind,
                SyntaxKind::ArrayBindingPattern | SyntaxKind::ObjectBindingPattern
            );
            let exact_empty = matches!(
                &pattern_node.data,
                NodeData::BindingPattern(pattern) if pattern.elements.nodes.is_empty()
            );
            if !supported_pattern
                || declaration.initializer.is_none()
                || !self.binding_pattern_has_no_identifiers(declaration.name)
                || (!exact_empty && self.settings.module != ModuleKind::CommonJs)
            {
                continue;
            }
            let mut pattern_count = 0;
            self.count_array_binding_patterns(declaration.name, &mut pattern_count);
            if exact_empty && pattern_node.kind == SyntaxKind::ObjectBindingPattern {
                pattern_count += 1;
            }
            if pattern_count == 0 {
                continue;
            }
            let temps = (0..pattern_count)
                .map(|_| self.generated_names.generate_temp())
                .collect::<Vec<_>>();
            self.commonjs_empty_binding_hoists
                .extend(temps.iter().cloned());
            self.commonjs_empty_binding_temps.insert(*statement, temps);
            if exact_empty && self.settings.target < ScriptTarget::Es2015 {
                let exported = self.generated_names.generate_temp();
                self.commonjs_empty_binding_exports
                    .insert(*statement, exported);
            }
        }
    }

    fn prepare_exported_object_rest_temps(&mut self, statements: &NodeList) {
        for statement in &statements.nodes {
            let Some(node) = self.arena.get(*statement) else {
                continue;
            };
            let NodeData::VariableStatement(variable) = &node.data else {
                continue;
            };
            if !self.has_modifier(variable.modifiers.as_ref(), SyntaxKind::ExportKeyword) {
                continue;
            }
            let Some(NodeData::VariableDeclarationList(list)) = self
                .arena
                .get(variable.declaration_list)
                .map(|node| &node.data)
            else {
                continue;
            };
            let [declaration] = list.declarations.nodes.as_slice() else {
                continue;
            };
            let Some(NodeData::VariableDeclaration(declaration)) =
                self.arena.get(*declaration).map(|node| &node.data)
            else {
                continue;
            };
            if declaration.initializer.is_none()
                || !self.object_binding_pattern_has_rest(declaration.name)
            {
                continue;
            }
            let temp = self.generated_names.generate_temp();
            self.commonjs_empty_binding_hoists.push(temp.clone());
            self.exported_object_rest_temps.insert(*statement, temp);
        }
    }

    fn prepare_commonjs_destructuring_assignment_temps(&mut self) {
        let mut assignments = self
            .arena
            .iter()
            .filter_map(|(id, node)| {
                let NodeData::BinaryExpression(binary) = &node.data else {
                    return None;
                };
                if self
                    .arena
                    .get(binary.operator_token)
                    .is_none_or(|operator| operator.kind != SyntaxKind::EqualsToken)
                    || !matches!(
                        self.arena.get(binary.left).map(|left| left.kind),
                        Some(
                            SyntaxKind::ObjectLiteralExpression
                                | SyntaxKind::ArrayLiteralExpression
                        )
                    )
                    || !self.commonjs_destructuring_pattern_updates_export(binary.left)
                {
                    return None;
                }
                Some((node.range.start.get(), id, binary.left))
            })
            .collect::<Vec<_>>();
        assignments.sort_by_key(|(start, _, _)| *start);
        for (_, expression, pattern) in assignments {
            self.commonjs_destructuring_assignment_roots
                .insert(expression);
            self.prepare_commonjs_destructuring_pattern_temps(pattern);
        }
    }

    fn prepare_commonjs_destructuring_pattern_temps(&mut self, pattern: NodeId) {
        if self.commonjs_destructuring_pattern_value_use_count(pattern) > 1
            && !self
                .commonjs_destructuring_assignment_temps
                .contains_key(&pattern)
        {
            let temp = self.generated_names.generate_temp();
            self.commonjs_destructuring_assignment_hoists
                .push(temp.clone());
            self.commonjs_destructuring_assignment_temps
                .insert(pattern, temp);
        }
        match self.arena.get(pattern).map(|node| &node.data) {
            Some(NodeData::ObjectLiteralExpression(object)) => {
                for property in &object.properties.nodes {
                    match self.arena.get(*property).map(|node| &node.data) {
                        Some(NodeData::PropertyAssignment(property)) => {
                            self.prepare_commonjs_destructuring_pattern_temps(property.initializer);
                        }
                        Some(NodeData::ShorthandPropertyAssignment(property)) => {
                            self.prepare_commonjs_destructuring_pattern_temps(property.name);
                        }
                        Some(NodeData::SpreadAssignment(spread)) => {
                            self.prepare_commonjs_destructuring_pattern_temps(spread.expression);
                        }
                        _ => {}
                    }
                }
            }
            Some(NodeData::ArrayLiteralExpression(array)) => {
                for element in &array.elements.nodes {
                    if let Some(NodeData::SpreadElement(spread)) =
                        self.arena.get(*element).map(|node| &node.data)
                    {
                        self.prepare_commonjs_destructuring_pattern_temps(spread.expression);
                    } else {
                        self.prepare_commonjs_destructuring_pattern_temps(*element);
                    }
                }
            }
            _ => {}
        }
    }

    fn commonjs_destructuring_pattern_value_use_count(&self, pattern: NodeId) -> usize {
        match self.arena.get(pattern).map(|node| &node.data) {
            Some(NodeData::ObjectLiteralExpression(object)) => object
                .properties
                .nodes
                .iter()
                .filter(
                    |property| match self.arena.get(**property).map(|node| &node.data) {
                        Some(NodeData::PropertyAssignment(property)) => {
                            self.commonjs_destructuring_pattern_leaf_count(property.initializer)
                                != 0
                        }
                        Some(NodeData::ShorthandPropertyAssignment(property)) => {
                            self.commonjs_destructuring_pattern_leaf_count(property.name) != 0
                        }
                        Some(NodeData::SpreadAssignment(spread)) => {
                            self.commonjs_destructuring_pattern_leaf_count(spread.expression) != 0
                        }
                        _ => false,
                    },
                )
                .count(),
            Some(NodeData::ArrayLiteralExpression(array)) => array
                .elements
                .nodes
                .iter()
                .filter(
                    |element| match self.arena.get(**element).map(|node| &node.data) {
                        Some(NodeData::OmittedExpression(_)) | None => false,
                        Some(NodeData::SpreadElement(spread)) => {
                            self.commonjs_destructuring_pattern_leaf_count(spread.expression) != 0
                        }
                        Some(_) => self.commonjs_destructuring_pattern_leaf_count(**element) != 0,
                    },
                )
                .count(),
            _ => 0,
        }
    }

    fn commonjs_destructuring_pattern_leaf_count(&self, pattern: NodeId) -> usize {
        match self.arena.get(pattern).map(|node| &node.data) {
            Some(
                NodeData::Identifier(_)
                | NodeData::PropertyAccessExpression(_)
                | NodeData::ElementAccessExpression(_),
            ) => 1,
            Some(NodeData::ObjectLiteralExpression(object)) => object
                .properties
                .nodes
                .iter()
                .map(
                    |property| match self.arena.get(*property).map(|node| &node.data) {
                        Some(NodeData::PropertyAssignment(property)) => {
                            self.commonjs_destructuring_pattern_leaf_count(property.initializer)
                        }
                        Some(NodeData::ShorthandPropertyAssignment(property)) => {
                            self.commonjs_destructuring_pattern_leaf_count(property.name)
                        }
                        Some(NodeData::SpreadAssignment(spread)) => {
                            self.commonjs_destructuring_pattern_leaf_count(spread.expression)
                        }
                        _ => 0,
                    },
                )
                .sum(),
            Some(NodeData::ArrayLiteralExpression(array)) => array
                .elements
                .nodes
                .iter()
                .map(
                    |element| match self.arena.get(*element).map(|node| &node.data) {
                        Some(NodeData::OmittedExpression(_)) | None => 0,
                        Some(NodeData::SpreadElement(spread)) => {
                            self.commonjs_destructuring_pattern_leaf_count(spread.expression)
                        }
                        Some(_) => self.commonjs_destructuring_pattern_leaf_count(*element),
                    },
                )
                .sum(),
            _ => 0,
        }
    }

    fn commonjs_destructuring_pattern_updates_export(&self, pattern: NodeId) -> bool {
        match self.arena.get(pattern).map(|node| &node.data) {
            Some(NodeData::Identifier(identifier)) => {
                !self
                    .commonjs_named_exports_for_local(&identifier.text)
                    .is_empty()
                    || self.identifier_has_exported_value_declaration(pattern, &identifier.text)
            }
            Some(NodeData::ObjectLiteralExpression(object)) => {
                object.properties.nodes.iter().any(|property| {
                    match self.arena.get(*property).map(|node| &node.data) {
                        Some(NodeData::PropertyAssignment(property)) => {
                            self.commonjs_destructuring_pattern_updates_export(property.initializer)
                        }
                        Some(NodeData::ShorthandPropertyAssignment(property)) => {
                            self.commonjs_destructuring_pattern_updates_export(property.name)
                        }
                        Some(NodeData::SpreadAssignment(spread)) => {
                            self.commonjs_destructuring_pattern_updates_export(spread.expression)
                        }
                        _ => false,
                    }
                })
            }
            Some(NodeData::ArrayLiteralExpression(array)) => {
                array.elements.nodes.iter().any(|element| {
                    match self.arena.get(*element).map(|node| &node.data) {
                        Some(NodeData::SpreadElement(spread)) => {
                            self.commonjs_destructuring_pattern_updates_export(spread.expression)
                        }
                        Some(NodeData::OmittedExpression(_)) | None => false,
                        Some(_) => self.commonjs_destructuring_pattern_updates_export(*element),
                    }
                })
            }
            _ => false,
        }
    }

    fn identifier_has_exported_value_declaration(&self, id: NodeId, name: &str) -> bool {
        let Some(symbol) = self.bindings.resolve_name_at(id, name) else {
            return false;
        };
        self.bindings.symbols.get(symbol).is_some_and(|symbol| {
            symbol.declarations.iter().any(|declaration| {
                let mut current = Some(*declaration);
                while let Some(id) = current {
                    let Some(node) = self.arena.get(id) else {
                        break;
                    };
                    if declaration_has_modifier(self.arena, node, SyntaxKind::ExportKeyword) {
                        return true;
                    }
                    current = node.parent;
                }
                false
            })
        })
    }

    fn binding_pattern_has_no_identifiers(&self, name: NodeId) -> bool {
        let Some(node) = self.arena.get(name) else {
            return false;
        };
        let NodeData::BindingPattern(pattern) = &node.data else {
            return false;
        };
        pattern.elements.nodes.iter().all(|element| {
            let Some(element) = self.arena.get(*element) else {
                return false;
            };
            match &element.data {
                NodeData::OmittedExpression(_) => true,
                NodeData::BindingElement(element) => element
                    .name
                    .is_some_and(|name| self.binding_pattern_has_no_identifiers(name)),
                _ => false,
            }
        })
    }

    fn count_array_binding_patterns(&self, name: NodeId, count: &mut usize) {
        let Some(node) = self.arena.get(name) else {
            return;
        };
        let NodeData::BindingPattern(pattern) = &node.data else {
            return;
        };
        if node.kind == SyntaxKind::ArrayBindingPattern {
            *count += 1;
        }
        for element in &pattern.elements.nodes {
            if let Some(NodeData::BindingElement(element)) =
                self.arena.get(*element).map(|node| &node.data)
                && let Some(name) = element.name
            {
                self.count_array_binding_patterns(name, count);
            }
        }
    }

    fn emit_commonjs_empty_binding_initializer(
        &mut self,
        statement: NodeId,
        variable: &ts_ast::VariableStatementData,
    ) -> Result<(), EmitError> {
        let temps = self
            .commonjs_empty_binding_temps
            .get(&statement)
            .cloned()
            .unwrap_or_default();
        let list = self.node(variable.declaration_list)?.clone();
        let NodeData::VariableDeclarationList(list) = &list.data else {
            return Err(Self::unsupported(variable.declaration_list, list.kind));
        };
        let declaration_id = list.declarations.nodes[0];
        let declaration = self.node(declaration_id)?.clone();
        let NodeData::VariableDeclaration(declaration) = &declaration.data else {
            return Err(Self::unsupported(declaration_id, declaration.kind));
        };
        let mut temps = temps.iter();
        let root = temps.next().expect("prepared empty binding root");
        let exported = self.commonjs_empty_binding_exports.get(&statement).cloned();
        if let Some(exported) = exported.as_deref() {
            if let Some(export_function) = self.system_export_function.clone() {
                self.writer.write(&export_function);
                self.writer.write("(");
                write_quoted(&mut self.writer, exported);
                self.writer.write(", ");
                self.writer.write(exported);
                self.writer.write(" = ");
            } else if self.commonjs_module_transform {
                self.writer.write("exports.");
                self.writer.write(exported);
                self.writer.write(" = ");
            } else {
                self.writer.write("export var ");
                self.writer.write(exported);
                self.writer.write(" = ");
            }
        }
        self.writer.write(root);
        self.writer.write(" = ");
        self.emit_expression(declaration.initializer.expect("initializer checked"), 1)?;
        self.emit_empty_binding_children(declaration.name, root, &mut temps)?;
        if exported.is_some() && self.system_export_function.is_some() {
            self.writer.write(")");
        }
        self.writer.write(";");
        Ok(())
    }

    fn emit_exported_object_rest_initializer(
        &mut self,
        statement: NodeId,
        variable: &ts_ast::VariableStatementData,
    ) -> Result<(), EmitError> {
        let temp = self.exported_object_rest_temps[&statement].clone();
        let Some(NodeData::VariableDeclarationList(list)) = self
            .arena
            .get(variable.declaration_list)
            .map(|node| &node.data)
        else {
            return Ok(());
        };
        let declaration_id = list.declarations.nodes[0];
        let Some(NodeData::VariableDeclaration(declaration)) =
            self.arena.get(declaration_id).map(|node| &node.data)
        else {
            return Ok(());
        };
        if self.commonjs_module_transform {
            self.install_commonjs_binding_rewrites(declaration.name);
        }
        let initializer = declaration.initializer.expect("prepared initializer");
        let Some(NodeData::BindingPattern(pattern)) =
            self.arena.get(declaration.name).map(|node| &node.data)
        else {
            return Ok(());
        };
        let mut ordinary = Vec::new();
        let mut rest = None;
        for element in &pattern.elements.nodes {
            let Some(NodeData::BindingElement(element)) =
                self.arena.get(*element).map(|node| &node.data)
            else {
                continue;
            };
            let Some(name) = element.name else {
                continue;
            };
            if element.dot_dot_dot_token.is_some() {
                rest = declaration_name_text(self.arena, name).map(str::to_owned);
            } else if let (Some(local), Some(property)) = (
                declaration_name_text(self.arena, name),
                declaration_name_text(self.arena, element.property_name.unwrap_or(name)),
            ) {
                ordinary.push((local.to_owned(), property.to_owned()));
            }
        }
        if self.settings.target >= ScriptTarget::Es2015 {
            self.writer.write(&temp);
            self.writer.write(" = ");
            self.emit_expression(initializer, 1)?;
            self.writer.write(", ");
        }
        let mut first = true;
        for (local, property) in &ordinary {
            if !first {
                self.writer.write(", ");
            }
            self.emit_exported_object_rest_assignment_start(local, first);
            self.emit_exported_object_rest_temp_value(
                &temp,
                initializer,
                self.settings.target < ScriptTarget::Es2015 && first,
            )?;
            if is_identifier_text(property) {
                self.writer.write(".");
                self.writer.write(property);
            } else {
                self.writer.write("[");
                write_quoted(&mut self.writer, property);
                self.writer.write("]");
            }
            self.emit_exported_object_rest_assignment_end();
            first = false;
        }
        if let Some(rest) = rest {
            if !first {
                self.writer.write(", ");
            }
            self.emit_exported_object_rest_assignment_start(&rest, first);
            self.writer.write("__rest(");
            self.emit_exported_object_rest_temp_value(
                &temp,
                initializer,
                first && self.settings.target < ScriptTarget::Es2015,
            )?;
            self.writer.write(", [");
            for (index, (_, property)) in ordinary.iter().enumerate() {
                if index != 0 {
                    self.writer.write(", ");
                }
                write_quoted(&mut self.writer, property);
            }
            self.writer.write("])");
            self.emit_exported_object_rest_assignment_end();
        }
        self.writer.write(";");
        Ok(())
    }

    fn emit_exported_object_rest_temp_value(
        &mut self,
        temp: &str,
        initializer: NodeId,
        initialize: bool,
    ) -> Result<(), EmitError> {
        if initialize {
            self.writer.write("(");
            self.writer.write(temp);
            self.writer.write(" = ");
            self.emit_expression(initializer, 1)?;
            self.writer.write(", ");
            self.writer.write(temp);
            self.writer.write(")");
        } else {
            self.writer.write(temp);
        }
        Ok(())
    }

    fn emit_exported_object_rest_assignment_start(&mut self, name: &str, first: bool) {
        if let Some(export_function) = self.system_export_function.clone() {
            self.writer.write(&export_function);
            self.writer.write("(");
            write_quoted(&mut self.writer, name);
            self.writer.write(", ");
            self.writer.write(name);
            self.writer.write(" = ");
        } else if self.commonjs_module_transform {
            self.writer.write("exports.");
            self.writer.write(name);
            self.writer.write(" = ");
        } else {
            if first {
                self.writer.write("export var ");
            }
            self.writer.write(name);
            self.writer.write(" = ");
        }
    }

    fn emit_exported_object_rest_assignment_end(&mut self) {
        if self.system_export_function.is_some() {
            self.writer.write(")");
        }
    }

    fn emit_empty_binding_children<'a>(
        &mut self,
        pattern_id: NodeId,
        parent_temp: &str,
        temps: &mut impl Iterator<Item = &'a String>,
    ) -> Result<(), EmitError> {
        let pattern_node = self.node(pattern_id)?.clone();
        let NodeData::BindingPattern(pattern) = &pattern_node.data else {
            return Ok(());
        };
        let mut index = 0_usize;
        let mut previous_end = pattern_node.range.start.get().saturating_add(1);
        for element_id in &pattern.elements.nodes {
            let element_node = self.node(*element_id)?.clone();
            index += self.array_binding_comma_count(previous_end, element_node.range.start.get());
            let NodeData::BindingElement(element) = &element_node.data else {
                previous_end = element_node.range.end.get();
                continue;
            };
            let Some(name) = element.name else {
                previous_end = element_node.range.end.get();
                continue;
            };
            if self.node(name)?.kind == SyntaxKind::ArrayBindingPattern {
                let temp = temps.next().expect("prepared nested empty binding temp");
                self.writer.write(", ");
                self.writer.write(temp);
                self.writer.write(" = ");
                self.writer.write(parent_temp);
                self.writer.write("[");
                self.writer.write(&index.to_string());
                self.writer.write("]");
                self.emit_empty_binding_children(name, temp, temps)?;
            }
            previous_end = element_node.range.end.get();
        }
        Ok(())
    }

    fn emit_block(&mut self, id: NodeId) -> Result<(), EmitError> {
        let node = self.node(id)?.clone();
        let NodeData::Block(data) = &node.data else {
            return Err(Self::unsupported(id, node.kind));
        };
        let source_multiline = self.node_source_is_multiline(id);
        let has_downlevel_rest = self.settings.target < ScriptTarget::Es2015
            && self
                .function_like_body_parameters(id)
                .is_some_and(|parameters| self.parameters_have_rest_parameter(parameters));
        let has_binding_parameter_property = self.body_has_binding_parameter_property(id);
        if data.statements.nodes.is_empty()
            && !source_multiline
            && !has_downlevel_rest
            && !has_binding_parameter_property
        {
            self.writer.write("{ }");
            return Ok(());
        }
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.namespace_declarations.push(HashSet::new());
        self.prepare_class_expression_temps(id, data);
        let mut previous_end = node.range.start.get().saturating_add(1);
        if self.body_opening_line_comment_is_unowned(id) {
            let comment_end = data
                .statements
                .nodes
                .first()
                .and_then(|statement| self.arena.get(*statement))
                .map_or_else(
                    || node.range.end.get().saturating_sub(1),
                    |statement| statement.range.start.get(),
                );
            previous_end = self.position_after_immediate_line_comment(previous_end, comment_end);
        }
        let mut previous_emitted = if self.settings.target < ScriptTarget::Es2015
            && let Some(parameters) = self.function_like_body_parameters(id).cloned()
        {
            self.emit_downlevel_rest_parameter_prologue(&parameters)?
        } else {
            false
        };
        for statement in &data.statements.nodes {
            let statement_node = self.node(*statement)?.clone();
            let direct_await = matches!(
                &statement_node.data,
                NodeData::ExpressionStatement(expression)
                    if matches!(
                        self.arena.get(expression.expression).map(|node| &node.data),
                        Some(NodeData::AwaitExpression(_))
                    )
            );
            let inline_comment_start = direct_await
                .then(|| {
                    self.inline_await_leading_comment_start(
                        previous_end,
                        statement_node.range.start.get(),
                    )
                })
                .flatten();
            let comment_end = inline_comment_start.unwrap_or(statement_node.range.start.get());
            self.emit_source_comments_between_with_trailing(
                previous_end,
                comment_end,
                previous_emitted || previous_end == node.range.start.get().saturating_add(1),
            );
            if self.block_comment_touches_range_end(previous_end, comment_end)
                && matches!(statement_node.data, NodeData::Block(_))
                && self.writer.line_start
            {
                self.writer.remove_trailing_newline();
                self.writer.write(" ");
            }
            if let Some(comment_start) = inline_comment_start {
                self.emit_inline_block_comments_between(
                    comment_start,
                    statement_node.range.start.get(),
                    false,
                );
            }
            self.emit_statement(*statement)?;
            previous_end = statement_node.range.end.get();
            previous_emitted = statement_emits_javascript(self.arena, &statement_node);
        }
        self.emit_source_comments_between_with_trailing(
            previous_end,
            node.range.end.get().saturating_sub(1),
            previous_emitted,
        );
        self.namespace_declarations.pop();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn block_comment_touches_range_end(&self, start: u32, end: u32) -> bool {
        let start = usize::try_from(start).unwrap_or(usize::MAX);
        let end = usize::try_from(end).unwrap_or(usize::MAX);
        let Some(trivia) = self.source_text.get(start..end) else {
            return false;
        };
        let Some(comment_end) = trivia.rfind("*/").map(|end| end + 2) else {
            return false;
        };
        !trivia[comment_end..].contains(['\n', '\r'])
    }

    #[allow(clippy::too_many_lines)]
    fn prepare_class_expression_temps(&mut self, block_id: NodeId, block: &ts_ast::BlockData) {
        let is_function_body = self
            .arena
            .get(block_id)
            .and_then(|node| node.parent)
            .and_then(|parent| self.arena.get(parent))
            .is_some_and(|parent| {
                matches!(
                    parent.data,
                    NodeData::FunctionDeclaration(_)
                        | NodeData::FunctionExpression(_)
                        | NodeData::ArrowFunction(_)
                        | NodeData::MethodDeclaration(_)
                        | NodeData::ConstructorDeclaration(_)
                        | NodeData::GetAccessorDeclaration(_)
                        | NodeData::SetAccessorDeclaration(_)
                )
            });
        let block_range = self.arena.get(block_id).map(|node| node.range);
        let mut class_expressions = if self.settings.target < ScriptTarget::Es2022 {
            self.arena
                .iter()
                .filter_map(|(id, node)| {
                    let NodeData::ClassExpression(class) = &node.data else {
                        return None;
                    };
                    if self.class_expression_temps.contains_key(&id)
                        || !block_range.is_some_and(|range| {
                            range.start <= node.range.start && node.range.end <= range.end
                        })
                    {
                        return None;
                    }
                    let declaration = Self::class_expression_as_declaration(class);
                    if !self.class_expression_requires_post_class_lowering(&declaration) {
                        return None;
                    }
                    if is_function_body {
                        let mut current = id;
                        while let Some(parent) =
                            self.arena.get(current).and_then(|node| node.parent)
                        {
                            if parent == block_id {
                                return Some((node.range.start, id));
                            }
                            if matches!(
                                self.arena.get(parent).map(|node| &node.data),
                                Some(
                                    NodeData::FunctionDeclaration(_)
                                        | NodeData::FunctionExpression(_)
                                        | NodeData::ArrowFunction(_)
                                        | NodeData::MethodDeclaration(_)
                                        | NodeData::ConstructorDeclaration(_)
                                        | NodeData::GetAccessorDeclaration(_)
                                        | NodeData::SetAccessorDeclaration(_)
                                )
                            ) {
                                return None;
                            }
                            current = parent;
                        }
                        None
                    } else {
                        node.parent
                            .is_some_and(|parent| block.statements.nodes.contains(&parent))
                            .then_some((node.range.start, id))
                    }
                })
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        class_expressions.sort_by_key(|(start, _)| *start);
        let mut claimed = HashSet::new();
        let mut temps = Vec::new();
        for (_, class_expression) in class_expressions {
            if let Some(NodeData::ClassExpression(class)) =
                self.arena.get(class_expression).map(|node| &node.data)
            {
                let members = class.members.nodes.clone();
                self.prepare_class_expression_computed_property_temps(
                    &members,
                    block_id,
                    &mut claimed,
                    &mut temps,
                );
            }
            let temp = self.generate_block_temp(block_id, &claimed);
            claimed.insert(temp.clone());
            self.class_expression_temps
                .insert(class_expression, temp.clone());
            temps.push(temp);
        }
        if is_function_body {
            self.prepare_downlevel_nullish_temps(block_id, &mut claimed, &mut temps);
            if matches!(self.settings.module, ModuleKind::Amd | ModuleKind::Umd)
                && let Some(container) = self.arena.get(block_id).and_then(|node| node.parent)
            {
                self.prepare_amd_dynamic_import_temps(
                    container,
                    block_id,
                    &mut claimed,
                    &mut temps,
                );
            }
        }
        if !temps.is_empty() {
            self.writer.write("var ");
            self.writer.write(&temps.join(", "));
            self.writer.write(";");
            self.writer.newline();
        }
    }

    fn prepare_amd_dynamic_import_temps(
        &mut self,
        container: NodeId,
        allocation_scope: NodeId,
        claimed: &mut HashSet<String>,
        temps: &mut Vec<String>,
    ) {
        let mut calls = self
            .arena
            .iter()
            .filter_map(|(id, node)| {
                let NodeData::CallExpression(call) = &node.data else {
                    return None;
                };
                if !self.is_dynamic_import_call(call)
                    || self.nearest_function_like_container(id) != Some(container)
                    || self.amd_dynamic_import_temps.contains_key(&id)
                {
                    return None;
                }
                let argument = call.arguments.nodes.first().copied()?;
                (!matches!(
                    self.arena.get(argument).map(|node| &node.data),
                    Some(NodeData::StringLiteral(_) | NodeData::NoSubstitutionTemplateLiteral(_))
                ))
                .then_some((node.range.start, id))
            })
            .collect::<Vec<_>>();
        calls.sort_by_key(|(start, _)| *start);
        for (_, call) in calls {
            let temp = self.generate_block_temp(allocation_scope, claimed);
            claimed.insert(temp.clone());
            self.amd_dynamic_import_temps.insert(call, temp.clone());
            temps.push(temp);
        }
    }

    #[allow(clippy::too_many_lines)]
    fn prepare_source_class_expression_temps(&mut self, source_file: NodeId) {
        if self.settings.target >= ScriptTarget::Es2022 {
            return;
        }
        let mut claimed = HashSet::new();
        let mut field_temps = Vec::new();
        if self.settings.target < ScriptTarget::Es2015 {
            self.prepare_source_computed_object_literal_temps(
                source_file,
                &mut claimed,
                &mut field_temps,
            );
        }
        let mut classes = self
            .arena
            .iter()
            .filter_map(|(id, node)| {
                let (members, is_expression) = match &node.data {
                    NodeData::ClassDeclaration(class) => (&class.members.nodes, false),
                    NodeData::ClassExpression(class) => (&class.members.nodes, true),
                    _ => return None,
                };
                self.class_expression_belongs_to_source_scope(id, source_file)
                    .then(|| (node.range.start, id, members.clone(), is_expression))
            })
            .collect::<Vec<_>>();
        classes.sort_by_key(|(start, _, _, _)| *start);

        for (_, class_id, members, is_expression) in &classes {
            for member in members {
                let Some(NodeData::PropertyDeclaration(property)) =
                    self.arena.get(*member).map(|node| &node.data)
                else {
                    continue;
                };
                let Some(NodeData::ComputedPropertyName(computed)) =
                    self.arena.get(property.name).map(|node| &node.data)
                else {
                    continue;
                };
                if *is_expression
                    && self.computed_property_requires_runtime_evaluation(*member, property)
                {
                    self.class_expression_computed_properties
                        .insert(property.name);
                }
                if !self.class_field_emits_runtime_value(property)
                    || class_member_has_legacy_decorators(self.arena, *member)
                    || self
                        .constant_computed_property_name(computed.expression)
                        .is_some()
                {
                    continue;
                }
                let temp = self.generate_block_temp(source_file, &claimed);
                claimed.insert(temp.clone());
                self.computed_property_temps
                    .insert(property.name, temp.clone());
                field_temps.push(temp);
            }
            if *is_expression
                && !self.class_expression_is_in_es5_captured_for_scope(*class_id)
                && self
                    .arena
                    .get(*class_id)
                    .and_then(|node| match &node.data {
                        NodeData::ClassExpression(class) => {
                            Some(self.class_expression_requires_post_class_lowering(
                                &Self::class_expression_as_declaration(class),
                            ))
                        }
                        _ => None,
                    })
                    .unwrap_or(false)
            {
                let temp = self.generate_block_temp(source_file, &claimed);
                claimed.insert(temp.clone());
                self.class_expression_temps.insert(*class_id, temp.clone());
                field_temps.push(temp);
            }
        }
        self.prepare_downlevel_nullish_temps(source_file, &mut claimed, &mut field_temps);
        if !field_temps.is_empty() {
            self.writer.write("var ");
            self.writer.write(&field_temps.join(", "));
            self.writer.write(";");
            self.writer.newline();
        }

        let mut decorator_temps = Vec::new();
        for (_, _, members, is_expression) in classes {
            for member in members {
                if !class_member_has_legacy_decorators(self.arena, member) {
                    continue;
                }
                let Some(name) = type_member_name(self.arena, member) else {
                    continue;
                };
                let Some(NodeData::ComputedPropertyName(computed)) =
                    self.arena.get(name).map(|node| &node.data)
                else {
                    continue;
                };
                if self.constant_property_name(computed.expression).is_some()
                    || self.computed_property_temps.contains_key(&name)
                {
                    continue;
                }
                let temp = self.generate_block_temp(source_file, &claimed);
                claimed.insert(temp.clone());
                self.computed_property_temps.insert(name, temp.clone());
                if is_expression
                    && matches!(
                        self.arena.get(member).map(|node| &node.data),
                        Some(NodeData::PropertyDeclaration(_))
                    )
                {
                    self.class_expression_computed_properties.insert(name);
                }
                decorator_temps.push(temp);
            }
        }
        if !decorator_temps.is_empty() {
            self.writer.write("var ");
            self.writer.write(&decorator_temps.join(", "));
            self.writer.write(";");
            self.writer.newline();
        }
    }

    fn prepare_class_expression_computed_property_temps(
        &mut self,
        members: &[NodeId],
        scope: NodeId,
        claimed: &mut HashSet<String>,
        temps: &mut Vec<String>,
    ) {
        for member in members {
            let Some(NodeData::PropertyDeclaration(property)) =
                self.arena.get(*member).map(|node| &node.data)
            else {
                continue;
            };
            let Some(NodeData::ComputedPropertyName(computed)) =
                self.arena.get(property.name).map(|node| &node.data)
            else {
                continue;
            };
            if self.computed_property_requires_runtime_evaluation(*member, property) {
                self.class_expression_computed_properties
                    .insert(property.name);
            }
            let needs_temp = (class_member_has_legacy_decorators(self.arena, *member)
                && self.constant_property_name(computed.expression).is_none())
                || (self.class_field_emits_runtime_value(property)
                    && self
                        .constant_computed_property_name(computed.expression)
                        .is_none());
            if !needs_temp || self.computed_property_temps.contains_key(&property.name) {
                continue;
            }
            let name = property.name;
            let temp = self.generate_block_temp(scope, claimed);
            claimed.insert(temp.clone());
            self.computed_property_temps.insert(name, temp.clone());
            temps.push(temp);
        }
        for member in members {
            if !class_member_has_legacy_decorators(self.arena, *member) {
                continue;
            }
            let Some(name) = type_member_name(self.arena, *member) else {
                continue;
            };
            let Some(NodeData::ComputedPropertyName(computed)) =
                self.arena.get(name).map(|node| &node.data)
            else {
                continue;
            };
            if self.constant_property_name(computed.expression).is_some()
                || self.computed_property_temps.contains_key(&name)
            {
                continue;
            }
            let temp = self.generate_block_temp(scope, claimed);
            claimed.insert(temp.clone());
            self.computed_property_temps.insert(name, temp.clone());
            temps.push(temp);
        }
    }

    fn prepare_source_computed_object_literal_temps(
        &mut self,
        source_file: NodeId,
        claimed: &mut HashSet<String>,
        temps: &mut Vec<String>,
    ) {
        let mut objects = self
            .arena
            .iter()
            .filter_map(|(id, node)| {
                let NodeData::ObjectLiteralExpression(object) = &node.data else {
                    return None;
                };
                if !self.class_expression_belongs_to_source_scope(id, source_file)
                    || self.node_has_class_ancestor(id, source_file)
                {
                    return None;
                }
                object
                    .properties
                    .nodes
                    .iter()
                    .any(|property| {
                        let Some(property) = self.arena.get(*property) else {
                            return false;
                        };
                        let name = match &property.data {
                            NodeData::PropertyAssignment(property) => property.name,
                            NodeData::MethodDeclaration(method) => method.name,
                            NodeData::GetAccessorDeclaration(accessor) => accessor.name,
                            NodeData::SetAccessorDeclaration(accessor) => accessor.name,
                            _ => return false,
                        };
                        matches!(
                            self.arena.get(name).map(|name| &name.data),
                            Some(NodeData::ComputedPropertyName(_))
                        )
                    })
                    .then_some((node.range.start, id))
            })
            .collect::<Vec<_>>();
        objects.sort_by_key(|(start, _)| *start);
        for (_, object) in objects {
            let temp = self.generate_block_temp(source_file, claimed);
            claimed.insert(temp.clone());
            self.computed_property_temps.insert(object, temp.clone());
            temps.push(temp);
        }
    }

    fn node_has_class_ancestor(&self, node: NodeId, boundary: NodeId) -> bool {
        let mut current = node;
        while let Some(parent) = self.arena.get(current).and_then(|node| node.parent) {
            if parent == boundary {
                return false;
            }
            if matches!(
                self.arena.get(parent).map(|node| &node.data),
                Some(NodeData::ClassDeclaration(_) | NodeData::ClassExpression(_))
            ) {
                return true;
            }
            current = parent;
        }
        false
    }

    fn class_expression_belongs_to_source_scope(
        &self,
        class_expression: NodeId,
        source_file: NodeId,
    ) -> bool {
        let mut current = class_expression;
        while let Some(parent) = self.arena.get(current).and_then(|node| node.parent) {
            if parent == source_file {
                return true;
            }
            if matches!(
                self.arena.get(parent).map(|node| &node.data),
                Some(
                    NodeData::FunctionDeclaration(_)
                        | NodeData::FunctionExpression(_)
                        | NodeData::ArrowFunction(_)
                        | NodeData::MethodDeclaration(_)
                        | NodeData::ConstructorDeclaration(_)
                        | NodeData::GetAccessorDeclaration(_)
                        | NodeData::SetAccessorDeclaration(_)
                )
            ) {
                return false;
            }
            current = parent;
        }
        false
    }

    fn class_expression_is_in_es5_captured_for_scope(&self, class_expression: NodeId) -> bool {
        if self.settings.target >= ScriptTarget::Es2015 {
            return false;
        }
        let mut current = class_expression;
        while let Some(parent) = self.arena.get(current).and_then(|node| node.parent) {
            match self.arena.get(parent).map(|node| &node.data) {
                Some(NodeData::ForStatement(for_statement))
                    if self.node_is_within(class_expression, for_statement.statement)
                        && !self
                            .es5_captured_for_initializer_names(for_statement)
                            .is_empty() =>
                {
                    return true;
                }
                Some(
                    NodeData::FunctionDeclaration(_)
                    | NodeData::FunctionExpression(_)
                    | NodeData::ArrowFunction(_)
                    | NodeData::MethodDeclaration(_)
                    | NodeData::ConstructorDeclaration(_)
                    | NodeData::GetAccessorDeclaration(_)
                    | NodeData::SetAccessorDeclaration(_),
                ) => return false,
                _ => {}
            }
            current = parent;
        }
        false
    }

    fn node_is_within(&self, node: NodeId, ancestor: NodeId) -> bool {
        let mut current = Some(node);
        while let Some(id) = current {
            if id == ancestor {
                return true;
            }
            current = self.arena.get(id).and_then(|node| node.parent);
        }
        false
    }

    fn prepare_parameter_class_expression_temps(
        &mut self,
        parameters: &NodeList,
        body: NodeId,
    ) -> Vec<String> {
        if self.settings.target >= ScriptTarget::Es2022 {
            return Vec::new();
        }
        let mut classes = Vec::new();
        for parameter in &parameters.nodes {
            let Some(NodeData::ParameterDeclaration(parameter)) =
                self.arena.get(*parameter).map(|node| &node.data)
            else {
                continue;
            };
            let Some(initializer) = parameter.initializer else {
                continue;
            };
            let Some(range) = self.arena.get(initializer).map(|node| node.range) else {
                continue;
            };
            for (id, node) in self.arena.iter() {
                let NodeData::ClassExpression(class) = &node.data else {
                    continue;
                };
                if range.start <= node.range.start && node.range.end <= range.end {
                    let declaration = Self::class_expression_as_declaration(class);
                    if self.class_expression_requires_post_class_lowering(&declaration) {
                        classes.push((node.range.start, id));
                    }
                }
            }
        }
        classes.sort_by_key(|(start, _)| *start);
        classes.dedup_by_key(|(_, id)| *id);
        let mut claimed = HashSet::new();
        let mut temps = Vec::new();
        for (_, class_id) in classes {
            let Some(NodeData::ClassExpression(class)) =
                self.arena.get(class_id).map(|node| &node.data)
            else {
                continue;
            };
            let members = class.members.nodes.clone();
            self.prepare_class_expression_computed_property_temps(
                &members,
                body,
                &mut claimed,
                &mut temps,
            );
            let temp = self.generate_block_temp(body, &claimed);
            claimed.insert(temp.clone());
            self.class_expression_temps.insert(class_id, temp.clone());
            temps.push(temp);
        }
        temps
    }

    fn emit_function_body_with_parameter_defaults(
        &mut self,
        body: NodeId,
        parameters: &NodeList,
        temps: &[String],
    ) -> Result<(), EmitError> {
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        if !temps.is_empty() {
            self.writer.write("var ");
            self.writer.write(&temps.join(", "));
            self.writer.write(";");
            self.writer.newline();
        }
        self.emit_parameter_default_prologues(parameters)?;
        self.emit_block_statements(body)?;
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn downlevel_binding_parameters(
        &self,
        parameters: &NodeList,
        function: NodeId,
    ) -> Vec<(NodeId, NodeId, String)> {
        let mut claimed = HashSet::new();
        let mut result = Vec::new();
        for parameter_id in &parameters.nodes {
            let Some(NodeData::ParameterDeclaration(parameter)) =
                self.arena.get(*parameter_id).map(|node| &node.data)
            else {
                continue;
            };
            if !matches!(
                self.arena.get(parameter.name).map(|node| &node.data),
                Some(NodeData::BindingPattern(_))
            ) {
                continue;
            }
            if self.settings.target >= ScriptTarget::Es2015
                && !(self
                    .arena
                    .get(parameter.name)
                    .is_some_and(|node| node.kind == SyntaxKind::ObjectBindingPattern)
                    && self.object_binding_pattern_has_rest(parameter.name))
            {
                continue;
            }
            let temp = self.generate_block_temp(function, &claimed);
            claimed.insert(temp.clone());
            result.push((*parameter_id, parameter.name, temp));
        }
        result
    }

    fn emit_function_body_with_binding_parameters(
        &mut self,
        body: NodeId,
        parameters: &NodeList,
        class_temps: &[String],
        downlevel_parameter_defaults: bool,
        binding_parameters: &[(NodeId, NodeId, String)],
    ) -> Result<(), EmitError> {
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        if !class_temps.is_empty() {
            self.writer.write("var ");
            self.writer.write(&class_temps.join(", "));
            self.writer.write(";");
            self.writer.newline();
        }
        if downlevel_parameter_defaults {
            self.emit_parameter_default_prologues_with_overrides(parameters, binding_parameters)?;
        }
        for (_, pattern, temp) in binding_parameters {
            if self.node(*pattern)?.kind == SyntaxKind::ObjectBindingPattern
                && self.object_binding_pattern_has_rest(*pattern)
            {
                self.emit_object_rest_parameter_prologue(*pattern, temp)?;
            } else {
                self.writer.write("var ");
                let mut emitted = false;
                self.emit_downlevel_binding_declarators(
                    *pattern,
                    DownlevelBindingValue::Name(temp.clone()),
                    None,
                    &mut emitted,
                    true,
                )?;
                self.writer.write(";");
                self.writer.newline();
            }
        }
        if self.parameters_have_rest_parameter(parameters) {
            self.emit_downlevel_rest_parameter_prologue(parameters)?;
        }
        self.emit_block_statements(body)?;
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn emit_parameter_default_prologues(
        &mut self,
        parameters: &NodeList,
    ) -> Result<bool, EmitError> {
        self.emit_parameter_default_prologues_with_overrides(parameters, &[])
    }

    fn emit_parameter_default_prologues_with_overrides(
        &mut self,
        parameters: &NodeList,
        overrides: &[(NodeId, NodeId, String)],
    ) -> Result<bool, EmitError> {
        let mut emitted = false;
        for parameter_id in &parameters.nodes {
            let node = self.node(*parameter_id)?.clone();
            let NodeData::ParameterDeclaration(parameter) = &node.data else {
                return Err(Self::unsupported(*parameter_id, node.kind));
            };
            let Some(initializer) = parameter.initializer else {
                continue;
            };
            self.writer.write("if (");
            if let Some((_, _, temp)) = overrides
                .iter()
                .find(|(candidate, _, _)| candidate == parameter_id)
            {
                self.writer.write(temp);
            } else {
                self.emit_expression(parameter.name, 0)?;
            }
            self.writer.write(" === void 0) { ");
            if let Some((_, _, temp)) = overrides
                .iter()
                .find(|(candidate, _, _)| candidate == parameter_id)
            {
                self.writer.write(temp);
            } else {
                self.emit_expression(parameter.name, 0)?;
            }
            self.writer.write(" = ");
            self.emit_expression(initializer, 1)?;
            self.writer.write("; }");
            self.writer.newline();
            emitted = true;
        }
        Ok(emitted)
    }

    fn generate_block_temp(&self, block: NodeId, claimed: &HashSet<String>) -> String {
        let mut count = 0_u32;
        loop {
            if let Some(candidate) = generated_temp_name(count) {
                let block_range = self.arena.get(block).map(|block| block.range);
                let used_in_block = self.arena.iter().any(|(_, node)| {
                    matches!(&node.data, NodeData::Identifier(identifier) if identifier.text == candidate)
                        && block_range.is_some_and(|range| {
                            range.start <= node.range.start && node.range.end <= range.end
                        })
                });
                if !used_in_block && !claimed.contains(&candidate) {
                    return candidate;
                }
            }
            count += 1;
        }
    }

    fn prepare_downlevel_nullish_temps(
        &mut self,
        container: NodeId,
        claimed: &mut HashSet<String>,
        temps: &mut Vec<String>,
    ) {
        if self.settings.target >= ScriptTarget::Es2020 {
            return;
        }
        let mut expressions = self
            .arena
            .iter()
            .filter_map(|(id, node)| {
                let NodeData::BinaryExpression(binary) = &node.data else {
                    return None;
                };
                if self
                    .arena
                    .get(binary.operator_token)
                    .is_none_or(|operator| operator.kind != SyntaxKind::QuestionQuestionToken)
                    || !self.downlevel_nullish_left_needs_temp(binary.left)
                    || !self.node_belongs_to_temp_scope(id, container)
                {
                    return None;
                }
                Some((node.range.start.get(), id))
            })
            .collect::<Vec<_>>();
        expressions.sort_by_key(|(start, _)| *start);
        for (_, expression) in expressions {
            if self.downlevel_nullish_temps.contains_key(&expression) {
                continue;
            }
            let temp = self.generate_block_temp(container, claimed);
            claimed.insert(temp.clone());
            self.downlevel_nullish_temps
                .insert(expression, temp.clone());
            temps.push(temp);
        }
    }

    fn node_belongs_to_temp_scope(&self, node: NodeId, container: NodeId) -> bool {
        let mut current = node;
        while let Some(parent) = self.arena.get(current).and_then(|node| node.parent) {
            if parent == container {
                return true;
            }
            if matches!(
                self.arena.get(parent).map(|node| &node.data),
                Some(
                    NodeData::FunctionDeclaration(_)
                        | NodeData::FunctionExpression(_)
                        | NodeData::ArrowFunction(_)
                        | NodeData::MethodDeclaration(_)
                        | NodeData::ConstructorDeclaration(_)
                        | NodeData::GetAccessorDeclaration(_)
                        | NodeData::SetAccessorDeclaration(_)
                )
            ) {
                return false;
            }
            current = parent;
        }
        false
    }

    fn downlevel_nullish_left_needs_temp(&self, expression: NodeId) -> bool {
        match self.arena.get(expression).map(|node| &node.data) {
            Some(
                NodeData::Identifier(_)
                | NodeData::NumericLiteral(_)
                | NodeData::BigIntLiteral(_)
                | NodeData::StringLiteral(_),
            )
            | None => false,
            Some(NodeData::ParenthesizedExpression(expression)) => {
                self.downlevel_nullish_left_needs_temp(expression.expression)
            }
            Some(NodeData::AsExpression(expression)) => {
                self.downlevel_nullish_left_needs_temp(expression.expression)
            }
            Some(NodeData::SatisfiesExpression(expression)) => {
                self.downlevel_nullish_left_needs_temp(expression.expression)
            }
            Some(NodeData::TypeAssertion(expression)) => {
                self.downlevel_nullish_left_needs_temp(expression.expression)
            }
            Some(NodeData::NonNullExpression(expression)) => {
                self.downlevel_nullish_left_needs_temp(expression.expression)
            }
            Some(_) => self.arena.get(expression).is_none_or(|node| {
                !matches!(
                    node.kind,
                    SyntaxKind::ThisKeyword
                        | SyntaxKind::SuperKeyword
                        | SyntaxKind::NullKeyword
                        | SyntaxKind::TrueKeyword
                        | SyntaxKind::FalseKeyword
                )
            }),
        }
    }

    fn body_opening_line_comment_is_unowned(&self, block: NodeId) -> bool {
        let Some(function) = self.arena.get(block).and_then(|block| block.parent) else {
            return false;
        };
        matches!(
            self.arena.get(function).map(|node| &node.data),
            Some(
                NodeData::FunctionDeclaration(_)
                    | NodeData::FunctionExpression(_)
                    | NodeData::ArrowFunction(_)
                    | NodeData::MethodDeclaration(_)
                    | NodeData::ConstructorDeclaration(_)
                    | NodeData::GetAccessorDeclaration(_)
                    | NodeData::SetAccessorDeclaration(_)
            )
        )
    }

    fn position_after_immediate_line_comment(&self, start: u32, end: u32) -> u32 {
        let start_index = usize::try_from(start).unwrap_or(usize::MAX);
        let end_index = usize::try_from(end).unwrap_or(usize::MAX);
        let Some(trivia) = self.source_text.get(start_index..end_index) else {
            return start;
        };
        let comment = trivia.trim_start_matches([' ', '\t']);
        if !comment.starts_with("//") {
            return start;
        }
        let leading = trivia.len() - comment.len();
        let comment_end = comment.find(['\n', '\r']).map_or(comment.len(), |end| end);
        u32::try_from(start_index + leading + comment_end).unwrap_or(end)
    }

    fn emit_function_body(&mut self, body: NodeId) -> Result<(), EmitError> {
        if let Some(statement) = self.single_line_body_statement(body)? {
            let body_node = self.node(body)?.clone();
            let statement_node = self.node(statement)?.clone();
            self.writer.write("{ ");
            self.emit_statement(statement)?;
            self.emit_source_comments_between_with_trailing(
                statement_node.range.end.get(),
                body_node.range.end.get().saturating_sub(1),
                statement_emits_javascript(self.arena, &statement_node),
            );
            self.writer.remove_trailing_newline();
            self.writer.write(" }");
            Ok(())
        } else if let Some(statements) = self.compact_function_body_statements(body)? {
            self.writer.write("{ ");
            for (index, statement) in statements.iter().enumerate() {
                self.emit_statement(*statement)?;
                self.writer.remove_trailing_newline();
                if index + 1 != statements.len() {
                    self.writer.write(" ");
                }
            }
            self.writer.write(" }");
            Ok(())
        } else {
            self.emit_block(body)
        }
    }

    fn compact_function_body_statements(
        &self,
        body: NodeId,
    ) -> Result<Option<Vec<NodeId>>, EmitError> {
        if self.source_text.is_empty() || self.node_source_is_multiline(body) {
            return Ok(None);
        }
        let node = self.node(body)?;
        let NodeData::Block(block) = &node.data else {
            return Err(Self::unsupported(body, node.kind));
        };
        if block.statements.nodes.len() < 2
            || self.source_range_contains_comment(
                node.range.start.get().saturating_add(1),
                node.range.end.get().saturating_sub(1),
            )
        {
            return Ok(None);
        }
        for statement in &block.statements.nodes {
            if !matches!(
                self.node(*statement)?.data,
                NodeData::ExpressionStatement(_)
                    | NodeData::DebuggerStatement(_)
                    | NodeData::ReturnStatement(_)
                    | NodeData::ThrowStatement(_)
                    | NodeData::EmptyStatement(_)
            ) || self.statement_contains_class_expression(*statement)?
            {
                return Ok(None);
            }
        }
        Ok(Some(block.statements.nodes.clone()))
    }

    fn body_has_downlevel_async_arrow(&self, body: NodeId) -> bool {
        self.arena.iter().any(|(id, node)| {
            let NodeData::ArrowFunction(arrow) = &node.data else {
                return false;
            };
            if !declaration_has_modifier_in_list(
                self.arena,
                arrow.modifiers.as_ref(),
                SyntaxKind::AsyncKeyword,
            ) {
                return false;
            }
            let mut current = id;
            while let Some(parent) = self.arena.get(current).and_then(|node| node.parent) {
                if parent == body {
                    return true;
                }
                if matches!(
                    self.arena.get(parent).map(|node| &node.data),
                    Some(
                        NodeData::FunctionDeclaration(_)
                            | NodeData::FunctionExpression(_)
                            | NodeData::MethodDeclaration(_)
                            | NodeData::GetAccessorDeclaration(_)
                            | NodeData::SetAccessorDeclaration(_)
                    )
                ) {
                    return false;
                }
                current = parent;
            }
            false
        })
    }

    fn emit_function_body_with_this_capture(&mut self, body: NodeId) -> Result<(), EmitError> {
        let alias = self.generate_this_capture_name(body);
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("var ");
        self.writer.write(&alias);
        self.writer.write(" = this;");
        self.writer.newline();
        let previous = self.capture_arrow_this.clone();
        self.capture_arrow_this = Some(alias);
        let result = self.emit_block_statements(body);
        self.capture_arrow_this = previous;
        result?;
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn generate_this_capture_name(&self, body: NodeId) -> String {
        let mut suffix = 0_u32;
        loop {
            let candidate = if suffix == 0 {
                "_this".to_owned()
            } else {
                format!("_this_{suffix}")
            };
            let used = self.arena.iter().any(|(id, node)| {
                self.node_is_within(id, body)
                    && matches!(
                        &node.data,
                        NodeData::Identifier(identifier) if identifier.text == candidate
                    )
            });
            if !used {
                return candidate;
            }
            suffix += 1;
        }
    }

    fn emit_downlevel_async_function_body(
        &mut self,
        body: NodeId,
        this_argument: &str,
    ) -> Result<(), EmitError> {
        if self.settings.target < ScriptTarget::Es2015 {
            return self.emit_es5_async_function_body(
                body,
                None,
                this_argument,
                "this",
                "_a",
                None,
                false,
            );
        }
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("return ");
        self.emit_awaiter_call(body, None, this_argument)?;
        self.writer.write(";");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn es5_generator_for_of(&self, body: NodeId) -> Result<Option<Es5GeneratorForOf>, EmitError> {
        let body_node = self.node(body)?;
        let NodeData::Block(block) = &body_node.data else {
            return Ok(None);
        };
        let [loop_id] = block.statements.nodes.as_slice() else {
            return Ok(None);
        };
        let loop_node = self.node(*loop_id)?;
        let NodeData::ForInOrOfStatement(for_of) = &loop_node.data else {
            return Ok(None);
        };
        if loop_node.kind != SyntaxKind::ForOfStatement || for_of.await_modifier.is_some() {
            return Ok(None);
        }
        let initializer = self.node(for_of.initializer)?;
        let NodeData::VariableDeclarationList(declarations) = &initializer.data else {
            return Ok(None);
        };
        let [declaration_id] = declarations.declarations.nodes.as_slice() else {
            return Ok(None);
        };
        let declaration = self.node(*declaration_id)?;
        let NodeData::VariableDeclaration(declaration) = &declaration.data else {
            return Ok(None);
        };
        let Ok(loop_variable) = self.identifier_text(declaration.name) else {
            return Ok(None);
        };
        let loop_variable = loop_variable.to_owned();
        let loop_body = self.node(for_of.statement)?;
        let NodeData::Block(loop_body) = &loop_body.data else {
            return Ok(None);
        };
        let Some((last, before_yield)) = loop_body.statements.nodes.split_last() else {
            return Ok(None);
        };
        let last = self.node(*last)?;
        let NodeData::ExpressionStatement(last) = &last.data else {
            return Ok(None);
        };
        let yielded = self.node(last.expression)?;
        let NodeData::YieldExpression(yielded) = &yielded.data else {
            return Ok(None);
        };
        let Some(yielded) = yielded.expression else {
            return Ok(None);
        };
        Ok(Some(Es5GeneratorForOf {
            loop_variable,
            iterable: for_of.expression,
            before_yield: before_yield.to_vec(),
            yielded,
        }))
    }

    fn es5_generator_object_literal(&self, body: NodeId) -> Option<Es5GeneratorObjectLiteral> {
        let NodeData::Block(block) = &self.arena.get(body)?.data else {
            return None;
        };
        let [statement] = block.statements.nodes.as_slice() else {
            return None;
        };
        let NodeData::VariableStatement(statement) = &self.arena.get(*statement)?.data else {
            return None;
        };
        let NodeData::VariableDeclarationList(list) =
            &self.arena.get(statement.declaration_list)?.data
        else {
            return None;
        };
        let [declaration] = list.declarations.nodes.as_slice() else {
            return None;
        };
        let NodeData::VariableDeclaration(declaration) = &self.arena.get(*declaration)?.data else {
            return None;
        };
        if !matches!(
            self.arena.get(declaration.name).map(|node| &node.data),
            Some(NodeData::Identifier(_))
        ) {
            return None;
        }
        let initializer = declaration.initializer?;
        let NodeData::ObjectLiteralExpression(object) = &self.arena.get(initializer)?.data else {
            return None;
        };

        let mut suspended = Vec::new();
        let mut direct_yields = HashSet::new();
        for (index, property) in object.properties.nodes.iter().enumerate() {
            let NodeData::PropertyAssignment(property) = &self.arena.get(*property)?.data else {
                return None;
            };
            let key_yield = match &self.arena.get(property.name)?.data {
                NodeData::ComputedPropertyName(computed)
                    if matches!(
                        self.arena.get(computed.expression).map(|node| &node.data),
                        Some(NodeData::YieldExpression(_))
                    ) => Some(computed.expression),
                _ => None,
            };
            let value_yield = matches!(
                self.arena.get(property.initializer).map(|node| &node.data),
                Some(NodeData::YieldExpression(_))
            )
            .then_some(property.initializer);
            if let Some(yield_) = key_yield {
                direct_yields.insert(yield_);
            }
            if let Some(yield_) = value_yield {
                direct_yields.insert(yield_);
            }
            if key_yield.is_some() || value_yield.is_some() {
                suspended.push((index, key_yield, value_yield));
            }
        }
        let [(suspended_property, key_yield, value_yield)] = suspended.as_slice() else {
            return None;
        };
        if self.arena.iter().any(|(id, node)| {
            matches!(node.data, NodeData::YieldExpression(_))
                && self.node_is_within(id, initializer)
                && !direct_yields.contains(&id)
        }) {
            return None;
        }
        Some(Es5GeneratorObjectLiteral {
            target: declaration.name,
            properties: object.properties.nodes.clone(),
            suspended_property: *suspended_property,
            key_yield: *key_yield,
            value_yield: *value_yield,
        })
    }

    fn emit_es5_generator_body(&mut self, body: NodeId) -> Result<(), EmitError> {
        if self.es5_generator_for_of(body)?.is_some() {
            return self.emit_es5_generator_for_of_body(body);
        }
        if let Some(plan) = self.es5_generator_object_literal(body) {
            return self.emit_es5_generator_object_literal_body(body, &plan);
        }
        let node = self.node(body)?.clone();
        let NodeData::Block(block) = &node.data else {
            return Err(Self::unsupported(body, node.kind));
        };
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("return ");
        self.emit_generator_reference();
        self.writer.write("(this, function (_a) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.emit_es5_generator_state_machine(&block.statements.nodes, "_a")?;
        self.writer.indent -= 1;
        self.writer.write("});");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn emit_es5_generator_object_literal_body(
        &mut self,
        body: NodeId,
        plan: &Es5GeneratorObjectLiteral,
    ) -> Result<(), EmitError> {
        let first_computed = plan
            .properties
            .iter()
            .position(|property| self.es5_generator_object_property_is_computed(*property));
        let computed_owns_prefix = first_computed
            .is_some_and(|index| index <= plan.suspended_property);
        let suspended_computed = self
            .es5_generator_object_property_is_computed(plan.properties[plan.suspended_property]);

        let mut claimed = HashSet::new();
        let mut generator_hoists = Vec::new();
        let generator_accumulator = if computed_owns_prefix {
            None
        } else {
            let temp = self.generate_block_temp(body, &claimed);
            claimed.insert(temp.clone());
            generator_hoists.push(temp.clone());
            Some(temp)
        };
        let key_temp = if suspended_computed && plan.value_yield.is_some() {
            let temp = self.generate_block_temp(body, &claimed);
            claimed.insert(temp.clone());
            generator_hoists.push(temp.clone());
            Some(temp)
        } else {
            None
        };
        let computed_accumulator = first_computed.map(|_| {
            let temp = self.generate_block_temp(body, &claimed);
            claimed.insert(temp.clone());
            temp
        });
        let accumulator = if computed_owns_prefix {
            computed_accumulator
                .clone()
                .expect("computed prefix requires an accumulator")
        } else {
            generator_accumulator
                .clone()
                .expect("suspended object requires an accumulator")
        };
        let state = self.generate_block_temp(body, &claimed);

        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("var ");
        self.emit_expression(plan.target, 0)?;
        for temp in &generator_hoists {
            self.writer.write(", ");
            self.writer.write(temp);
        }
        self.writer.write(";");
        self.writer.newline();
        if let Some(computed) = &computed_accumulator {
            self.writer.write("var ");
            self.writer.write(computed);
            self.writer.write(";");
            self.writer.newline();
        }
        self.writer.write("return ");
        self.emit_generator_reference();
        self.writer.write("(this, function (");
        self.writer.write(&state);
        self.writer.write(") {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("switch (");
        self.writer.write(&state);
        self.writer.write(".label) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("case 0:");
        self.writer.newline();
        self.writer.indent += 1;

        self.emit_es5_generator_object_prefix(
            plan,
            &accumulator,
            computed_owns_prefix,
        )?;

        let mut case = 0_usize;
        if let Some(key_yield) = plan.key_yield {
            let NodeData::YieldExpression(yielded) = self.node(key_yield)?.data.clone() else {
                unreachable!("planned key yield must remain a yield expression");
            };
            self.emit_es5_generator_yield_opcode(&yielded)?;
            self.emit_es5_generator_next_case(&mut case);
            if let Some(value_yield) = plan.value_yield {
                self.writer
                    .write(key_temp.as_deref().expect("yielded key crossing yield needs temp"));
                self.writer.write(" = ");
                self.writer.write(&state);
                self.writer.write(".sent();");
                self.writer.newline();
                let NodeData::YieldExpression(yielded) = self.node(value_yield)?.data.clone() else {
                    unreachable!("planned value yield must remain a yield expression");
                };
                self.emit_es5_generator_yield_opcode(&yielded)?;
                self.emit_es5_generator_next_case(&mut case);
            }
        } else if let Some(value_yield) = plan.value_yield {
            if let Some(key_temp) = &key_temp {
                let property = self.node(plan.properties[plan.suspended_property])?.clone();
                let NodeData::PropertyAssignment(property) = &property.data else {
                    unreachable!("planned object member must remain a property assignment");
                };
                let NodeData::ComputedPropertyName(computed) = self.node(property.name)?.data.clone()
                else {
                    unreachable!("planned computed key must remain computed");
                };
                self.writer.write(key_temp);
                self.writer.write(" = ");
                self.emit_expression(computed.expression, 1)?;
                self.writer.write(";");
                self.writer.newline();
            }
            let NodeData::YieldExpression(yielded) = self.node(value_yield)?.data.clone() else {
                unreachable!("planned value yield must remain a yield expression");
            };
            self.emit_es5_generator_yield_opcode(&yielded)?;
            self.emit_es5_generator_next_case(&mut case);
        }

        self.emit_es5_generator_object_finish(
            plan,
            &accumulator,
            computed_accumulator.as_deref(),
            key_temp.as_deref(),
            &state,
        )?;
        self.writer.write("return [2 /*return*/];");
        self.writer.newline();
        self.writer.indent -= 2;
        self.writer.write("}");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("});");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn es5_generator_object_property_is_computed(&self, property: NodeId) -> bool {
        let Some(NodeData::PropertyAssignment(property)) =
            self.arena.get(property).map(|node| &node.data)
        else {
            return false;
        };
        matches!(
            self.arena.get(property.name).map(|node| &node.data),
            Some(NodeData::ComputedPropertyName(_))
        )
    }

    fn emit_es5_generator_object_prefix(
        &mut self,
        plan: &Es5GeneratorObjectLiteral,
        accumulator: &str,
        computed_style: bool,
    ) -> Result<(), EmitError> {
        let prefix = &plan.properties[..plan.suspended_property];
        let literal_end = prefix
            .iter()
            .position(|property| self.es5_generator_object_property_is_computed(*property))
            .unwrap_or(prefix.len());

        self.writer.write(accumulator);
        self.writer.write(" = ");
        if computed_style {
            self.writer.indent += 1;
        }
        if literal_end == 0 {
            self.writer.write("{}");
        } else {
            self.writer.write("{");
            self.writer.indent += 1;
            self.writer.newline();
            for (index, property) in prefix[..literal_end].iter().enumerate() {
                if index != 0 {
                    self.writer.write(",");
                    self.writer.newline();
                }
                let property = self.node(*property)?.clone();
                let NodeData::PropertyAssignment(property) = &property.data else {
                    unreachable!("planned object member must remain a property assignment");
                };
                self.emit_object_literal_property_name(property.name)?;
                self.writer.write(": ");
                self.emit_expression(property.initializer, 1)?;
            }
            self.writer.indent -= 1;
            self.writer.newline();
            self.writer.write("}");
        }
        for property in &prefix[literal_end..] {
            self.writer.write(",");
            self.writer.newline();
            self.emit_es5_generator_object_property_assignment(
                accumulator,
                *property,
                None,
                false,
                None,
            )?;
        }
        self.writer.write(";");
        if computed_style {
            self.writer.indent -= 1;
        }
        self.writer.newline();
        Ok(())
    }

    fn emit_es5_generator_next_case(&mut self, case: &mut usize) {
        self.writer.newline();
        self.writer.indent -= 1;
        *case += 1;
        self.writer.write("case ");
        self.writer.write(&case.to_string());
        self.writer.write(":");
        self.writer.newline();
        self.writer.indent += 1;
    }

    fn emit_es5_generator_object_finish(
        &mut self,
        plan: &Es5GeneratorObjectLiteral,
        accumulator: &str,
        computed_accumulator: Option<&str>,
        key_temp: Option<&str>,
        state: &str,
    ) -> Result<(), EmitError> {
        let suffix = &plan.properties[plan.suspended_property + 1..];
        let rebase_at = computed_accumulator
            .filter(|computed| *computed != accumulator)
            .and_then(|_| {
                suffix
                    .iter()
                    .position(|property| self.es5_generator_object_property_is_computed(*property))
            });
        let final_accumulator = if rebase_at.is_some() {
            computed_accumulator.expect("rebase requires computed accumulator")
        } else {
            accumulator
        };

        self.emit_expression(plan.target, 1)?;
        self.writer.write(" = (");
        self.writer.indent += 1;
        if let Some(rebase_at) = rebase_at {
            let computed = computed_accumulator.expect("rebase requires computed accumulator");
            self.writer.write(computed);
            self.writer.write(" = (");
            self.emit_es5_generator_suspended_property_assignment(
                plan,
                accumulator,
                key_temp,
                state,
            )?;
            for property in &suffix[..rebase_at] {
                self.writer.write(",");
                self.writer.newline();
                self.emit_es5_generator_object_property_assignment(
                    accumulator,
                    *property,
                    None,
                    false,
                    None,
                )?;
            }
            self.writer.write(",");
            self.writer.newline();
            self.writer.write(accumulator);
            self.writer.write(")");
            for property in &suffix[rebase_at..] {
                self.writer.write(",");
                self.writer.newline();
                self.emit_es5_generator_object_property_assignment(
                    computed,
                    *property,
                    None,
                    false,
                    None,
                )?;
            }
        } else {
            self.emit_es5_generator_suspended_property_assignment(
                plan,
                accumulator,
                key_temp,
                state,
            )?;
            for property in suffix {
                self.writer.write(",");
                self.writer.newline();
                self.emit_es5_generator_object_property_assignment(
                    accumulator,
                    *property,
                    None,
                    false,
                    None,
                )?;
            }
        }
        self.writer.write(",");
        self.writer.newline();
        self.writer.write(final_accumulator);
        self.writer.indent -= 1;
        self.writer.write(");");
        self.writer.newline();
        Ok(())
    }

    fn emit_es5_generator_suspended_property_assignment(
        &mut self,
        plan: &Es5GeneratorObjectLiteral,
        accumulator: &str,
        key_temp: Option<&str>,
        state: &str,
    ) -> Result<(), EmitError> {
        let property = plan.properties[plan.suspended_property];
        let key = if let Some(key_temp) = key_temp {
            Some(key_temp)
        } else if plan.key_yield.is_some() {
            Some(state)
        } else {
            None
        };
        self.emit_es5_generator_object_property_assignment(
            accumulator,
            property,
            key,
            plan.key_yield.is_some() && key_temp.is_none(),
            plan.value_yield.map(|_| state),
        )
    }

    fn emit_es5_generator_object_property_assignment(
        &mut self,
        accumulator: &str,
        property: NodeId,
        key_override: Option<&str>,
        key_is_sent: bool,
        value_state: Option<&str>,
    ) -> Result<(), EmitError> {
        let property = self.node(property)?.clone();
        let NodeData::PropertyAssignment(property) = &property.data else {
            unreachable!("planned object member must remain a property assignment");
        };
        self.writer.write(accumulator);
        if let Some(key) = key_override {
            self.writer.write("[");
            self.writer.write(key);
            if key_is_sent {
                self.writer.write(".sent()");
            }
            self.writer.write("]");
        } else {
            self.emit_downlevel_member_access(property.name)?;
        }
        self.writer.write(" = ");
        if let Some(state) = value_state {
            self.writer.write(state);
            self.writer.write(".sent()");
        } else {
            self.emit_expression(property.initializer, 1)?;
        }
        Ok(())
    }

    fn emit_es5_generator_state_machine(
        &mut self,
        statements: &[NodeId],
        state: &str,
    ) -> Result<(), EmitError> {
        let yields = statements
            .iter()
            .filter(|statement| self.direct_yield_expression(**statement).is_some())
            .count();
        if yields == 0 {
            for statement in statements {
                if let Some(NodeData::ReturnStatement(return_statement)) =
                    self.arena.get(*statement).map(|node| &node.data)
                {
                    self.emit_es5_generator_return(return_statement.expression)?;
                } else {
                    self.emit_statement(*statement)?;
                }
            }
            if !statements.last().is_some_and(|statement| {
                matches!(
                    self.arena.get(*statement).map(|node| &node.data),
                    Some(NodeData::ReturnStatement(_))
                )
            }) {
                self.writer.write("return [2 /*return*/];");
                self.writer.newline();
            }
            return Ok(());
        }

        self.writer.write("switch (");
        self.writer.write(state);
        self.writer.write(".label) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("case 0:");
        self.writer.newline();
        self.writer.indent += 1;
        let mut case = 0;
        for statement in statements {
            if let Some(yielded) = self.direct_yield_expression(*statement).cloned() {
                self.emit_es5_generator_yield_opcode(&yielded)?;
                self.writer.newline();
                self.writer.indent -= 1;
                case += 1;
                self.writer.write("case ");
                self.writer.write(&case.to_string());
                self.writer.write(":");
                self.writer.newline();
                self.writer.indent += 1;
                self.writer.write(state);
                self.writer.write(".sent();");
                self.writer.newline();
            } else if let Some(NodeData::ReturnStatement(return_statement)) =
                self.arena.get(*statement).map(|node| &node.data)
            {
                self.emit_es5_generator_return(return_statement.expression)?;
            } else {
                self.emit_statement(*statement)?;
            }
        }
        if !statements.last().is_some_and(|statement| {
            matches!(
                self.arena.get(*statement).map(|node| &node.data),
                Some(NodeData::ReturnStatement(_))
            )
        }) {
            self.writer.write("return [2 /*return*/];");
            self.writer.newline();
        }
        self.writer.indent -= 2;
        self.writer.write("}");
        self.writer.newline();
        Ok(())
    }

    fn emit_es5_generator_yield_opcode(
        &mut self,
        yielded: &ts_ast::YieldExpressionData,
    ) -> Result<(), EmitError> {
        if yielded.asterisk_token.is_some() {
            self.writer.write("return [5 /*yield**/, __values(");
            if let Some(expression) = yielded.expression {
                self.emit_expression(expression, 0)?;
            } else {
                self.writer.write("void 0");
            }
            self.writer.write(")];");
        } else {
            self.writer.write("return [4 /*yield*/");
            if let Some(expression) = yielded.expression {
                self.writer.write(", ");
                self.emit_expression(expression, 0)?;
            }
            self.writer.write("];");
        }
        Ok(())
    }

    fn direct_yield_expression(&self, statement: NodeId) -> Option<&ts_ast::YieldExpressionData> {
        let NodeData::ExpressionStatement(expression) = &self.arena.get(statement)?.data else {
            return None;
        };
        let NodeData::YieldExpression(yielded) = &self.arena.get(expression.expression)?.data
        else {
            return None;
        };
        Some(yielded)
    }

    fn emit_es5_generator_return(&mut self, expression: Option<NodeId>) -> Result<(), EmitError> {
        self.writer.write("return [2 /*return*/");
        if let Some(expression) = expression {
            self.writer.write(", ");
            self.emit_expression(expression, 0)?;
        }
        self.writer.write("];");
        self.writer.newline();
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn emit_es5_generator_for_of_body(&mut self, body: NodeId) -> Result<(), EmitError> {
        let info = self
            .es5_generator_for_of(body)?
            .expect("downlevel generator shape checked");
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("var _loop_1, _a, _b, ");
        self.writer.write(&info.loop_variable);
        self.writer.write(", e_1_1;");
        self.writer.newline();
        self.writer.write("var e_1, _c;");
        self.writer.newline();
        self.writer.write("return ");
        self.emit_generator_reference();
        self.writer.write("(this, function (_d) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("switch (_d.label) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("case 0:");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("_loop_1 = function (");
        self.writer.write(&info.loop_variable);
        self.writer.write(") {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("return ");
        self.emit_generator_reference();
        self.writer.write("(this, function (_e) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("switch (_e.label) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("case 0:");
        self.writer.newline();
        self.writer.indent += 1;
        for statement in &info.before_yield {
            self.emit_statement(*statement)?;
        }
        self.writer.write("return [4 /*yield*/, ");
        self.emit_expression(info.yielded, 0)?;
        self.writer.write("];");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("case 1:");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("_e.sent();");
        self.writer.newline();
        self.writer.write("return [2 /*return*/];");
        self.writer.newline();
        self.writer.indent -= 2;
        self.writer.write("}");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("});");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("};");
        self.writer.newline();
        self.writer.write("_d.label = 1;");
        self.writer.newline();
        self.writer.indent -= 1;
        for line in ["case 1:", "    _d.trys.push([1, 6, 7, 8]);"] {
            self.writer.write(line);
            self.writer.newline();
        }
        self.writer.indent += 1;
        self.writer.write("_a = __values(");
        self.emit_expression(info.iterable, 0)?;
        self.writer.write("), _b = _a.next();");
        self.writer.newline();
        self.writer.write("_d.label = 2;");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("case 2:");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("if (!!_b.done) return [3 /*break*/, 5];");
        self.writer.newline();
        self.writer.write(&info.loop_variable);
        self.writer.write(" = _b.value;");
        self.writer.newline();
        self.writer.write("return [5 /*yield**/, _loop_1(");
        self.writer.write(&info.loop_variable);
        self.writer.write(")];");
        self.writer.newline();
        self.writer.indent -= 1;
        for line in [
            "case 3:",
            "    _d.sent();",
            "    _d.label = 4;",
            "case 4:",
            "    _b = _a.next();",
            "    return [3 /*break*/, 2];",
            "case 5: return [3 /*break*/, 8];",
            "case 6:",
            "    e_1_1 = _d.sent();",
            "    e_1 = { error: e_1_1 };",
            "    return [3 /*break*/, 8];",
            "case 7:",
            "    try {",
            "        if (_b && !_b.done && (_c = _a.return)) _c.call(_a);",
            "    }",
            "    finally { if (e_1) throw e_1.error; }",
            "    return [7 /*endfinally*/];",
            "case 8: return [2 /*return*/];",
        ] {
            self.writer.write(line);
            self.writer.newline();
        }
        self.writer.indent -= 1;
        self.writer.write("}");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("});");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn emit_downlevel_async_generator_body(
        &mut self,
        body: NodeId,
        inner_name: &str,
    ) -> Result<(), EmitError> {
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer
            .write("return __asyncGenerator(this, arguments, function* ");
        self.writer.write(inner_name);
        self.writer.write("() {");
        self.writer.newline();
        self.writer.indent += 1;
        let previous = self.async_expression_transform;
        self.async_expression_transform = AsyncExpressionTransform::AsyncGenerator;
        let result = self.emit_block_statements(body);
        self.async_expression_transform = previous;
        result?;
        self.writer.indent -= 1;
        self.writer.write("});");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn emit_es5_downlevel_async_generator_body(
        &mut self,
        body: NodeId,
        inner_name: &str,
    ) -> Result<(), EmitError> {
        let node = self.node(body)?.clone();
        let NodeData::Block(block) = &node.data else {
            return Err(Self::unsupported(body, node.kind));
        };
        self.writer.write("{");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer
            .write("return __asyncGenerator(this, arguments, function ");
        self.writer.write(inner_name);
        self.writer.write("() {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("return ");
        self.emit_generator_reference();
        self.writer.write("(this, function (_a) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.emit_es5_async_generator_state_machine(&block.statements.nodes, "_a")?;
        self.writer.indent -= 1;
        self.writer.write("});");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("});");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write("}");
        Ok(())
    }

    fn emit_es5_async_generator_state_machine(
        &mut self,
        statements: &[NodeId],
        state: &str,
    ) -> Result<(), EmitError> {
        let has_suspension = statements.iter().any(|statement| {
            self.direct_yield_expression(*statement).is_some()
                || self.direct_await_expression(*statement).is_some()
        });
        if !has_suspension {
            for statement in statements {
                if let Some(NodeData::ReturnStatement(return_statement)) =
                    self.arena.get(*statement).map(|node| &node.data)
                {
                    self.emit_es5_generator_return(return_statement.expression)?;
                } else {
                    self.emit_statement(*statement)?;
                }
            }
            if !self.statements_end_in_return(statements) {
                self.writer.write("return [2 /*return*/];");
                self.writer.newline();
            }
            return Ok(());
        }

        self.writer.write("switch (");
        self.writer.write(state);
        self.writer.write(".label) {");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write("case 0:");
        self.writer.newline();
        self.writer.indent += 1;
        let mut case = 0;
        for statement in statements {
            if let Some(yielded) = self.direct_yield_expression(*statement).cloned() {
                self.writer.write("return [4 /*yield*/, __await(");
                if let Some(expression) = yielded.expression {
                    self.emit_expression(expression, 0)?;
                } else {
                    self.writer.write("void 0");
                }
                self.writer.write(")];");
                self.writer.newline();
                self.writer.indent -= 1;
                case += 1;
                self.writer.write("case ");
                self.writer.write(&case.to_string());
                self.writer.write(": return [4 /*yield*/, ");
                self.writer.write(state);
                self.writer.write(".sent()];");
                self.writer.newline();
                self.writer.indent += 1;
                self.emit_es5_state_case(&mut case);
                self.writer.write(state);
                self.writer.write(".sent();");
                self.writer.newline();
            } else if let Some(awaited) = self.direct_await_expression(*statement) {
                self.writer.write("return [4 /*yield*/, __await(");
                self.emit_expression(awaited, 0)?;
                self.writer.write(")];");
                self.writer.newline();
                self.emit_es5_state_case(&mut case);
                self.writer.write(state);
                self.writer.write(".sent();");
                self.writer.newline();
            } else if let Some(NodeData::ReturnStatement(return_statement)) =
                self.arena.get(*statement).map(|node| &node.data)
            {
                self.emit_es5_generator_return(return_statement.expression)?;
            } else {
                self.emit_statement(*statement)?;
            }
        }
        if !self.statements_end_in_return(statements) {
            self.writer.write("return [2 /*return*/];");
            self.writer.newline();
        }
        self.writer.indent -= 2;
        self.writer.write("}");
        self.writer.newline();
        Ok(())
    }

    fn emit_es5_state_case(&mut self, case: &mut usize) {
        self.writer.indent -= 1;
        *case += 1;
        self.writer.write("case ");
        self.writer.write(&case.to_string());
        self.writer.write(":");
        self.writer.newline();
        self.writer.indent += 1;
    }

    fn direct_await_expression(&self, statement: NodeId) -> Option<NodeId> {
        let NodeData::ExpressionStatement(expression) = &self.arena.get(statement)?.data else {
            return None;
        };
        let NodeData::AwaitExpression(awaited) = &self.arena.get(expression.expression)?.data
        else {
            return None;
        };
        Some(awaited.expression)
    }

    fn statements_end_in_return(&self, statements: &[NodeId]) -> bool {
        statements.last().is_some_and(|statement| {
            matches!(
                self.arena.get(*statement).map(|node| &node.data),
                Some(NodeData::ReturnStatement(_))
            )
        })
    }

    #[allow(clippy::too_many_arguments, clippy::too_many_lines)]
    fn emit_es5_async_for_in_statement(
        &mut self,
        statement_id: NodeId,
        statement: &ts_ast::ForInOrOfStatementData,
        label: Option<NodeId>,
        plan: &Es5AsyncForInPlan,
        state: &str,
        case: &mut usize,
        is_last: bool,
    ) -> Result<(), EmitError> {
        let start_case = *case;
        let expression_await = self.es5_async_simple_await_in_expression(statement.expression);
        let initializer_await = self.es5_async_simple_await_in_expression(statement.initializer);
        let head_case = start_case + usize::from(expression_await.is_some()) + 1;
        let increment_case = head_case
            + usize::from(initializer_await.is_some())
            + self.es5_async_case_advance(statement.statement)
            + 1;
        let exit_case = increment_case + 1;

        if let Some(await_id) = expression_await {
            let NodeData::AwaitExpression(awaited) = &self.node(await_id)?.data else {
                unreachable!("await expression identified above")
            };
            let awaited_expression = awaited.expression;
            self.emit_es5_async_yield(awaited_expression, case, false)?;
            let previous = self
                .es5_async_expression_rewrites
                .insert(await_id, format!("{state}.sent()"));
            self.writer.write(&plan.object);
            self.writer.write(" = ");
            self.emit_expression(statement.expression, 1)?;
            self.writer.write(";");
            self.writer.newline();
            self.restore_es5_async_expression_rewrite(await_id, previous);
        } else {
            if !self.writer.line_start {
                self.writer.newline();
            }
            self.writer.write(&plan.object);
            self.writer.write(" = ");
            self.emit_expression(statement.expression, 1)?;
            self.writer.write(";");
            self.writer.newline();
        }
        self.writer.write(&plan.keys);
        self.writer.write(" = [];");
        self.writer.newline();
        self.writer.write("for (");
        self.writer.write(&plan.key);
        self.writer.write(" in ");
        self.writer.write(&plan.object);
        self.writer.write(")");
        self.writer.newline();
        self.writer.indent += 1;
        self.writer.write(&plan.keys);
        self.writer.write(".push(");
        self.writer.write(&plan.key);
        self.writer.write(");");
        self.writer.newline();
        self.writer.indent -= 1;
        self.writer.write(&plan.index);
        self.writer.write(" = 0;");
        self.writer.newline();
        self.writer.write(state);
        self.writer.write(".label = ");
        self.writer.write(&head_case.to_string());
        self.writer.write(";");
        self.writer.newline();

        self.emit_es5_async_case_label(head_case, false);
        *case = head_case;
        self.writer.write("if (!(");
        self.writer.write(&plan.index);
        self.writer.write(" < ");
        self.writer.write(&plan.keys);
        self.writer.write(".length)) return [3 /*break*/, ");
        self.writer.write(&exit_case.to_string());
        self.writer.write("];");
        self.writer.newline();
        self.writer.write(&plan.key);
        self.writer.write(" = ");
        self.writer.write(&plan.keys);
        self.writer.write("[");
        self.writer.write(&plan.index);
        self.writer.write("];");
        self.writer.newline();
        self.writer.write("if (!(");
        self.writer.write(&plan.key);
        self.writer.write(" in ");
        self.writer.write(&plan.object);
        self.writer.write(")) return [3 /*break*/, ");
        self.writer.write(&increment_case.to_string());
        self.writer.write("];");
        self.writer.newline();

        if let Some(await_id) = initializer_await {
            let NodeData::AwaitExpression(awaited) = &self.node(await_id)?.data else {
                unreachable!("await expression identified above")
            };
            let awaited_expression = awaited.expression;
            self.emit_es5_async_yield(awaited_expression, case, false)?;
            let previous = self
                .es5_async_expression_rewrites
                .insert(await_id, format!("{state}.sent()"));
            self.emit_es5_async_for_in_binding(statement.initializer, &plan.key)?;
            self.restore_es5_async_expression_rewrite(await_id, previous);
        } else {
            self.emit_es5_async_for_in_binding(statement.initializer, &plan.key)?;
        }

        let mut nodes = vec![statement_id];
        nodes.extend(label);
        self.es5_async_control_targets.push(Es5AsyncControlTarget {
            nodes,
            break_case: exit_case,
            continue_case: increment_case,
        });
        let body_result = self.emit_es5_async_branch(statement.statement, state, case);
        self.es5_async_control_targets.pop();
        body_result?;
        if self.es5_async_statement_may_complete_normally(statement.statement) {
            self.writer.write(state);
            self.writer.write(".label = ");
            self.writer.write(&increment_case.to_string());
            self.writer.write(";");
            self.writer.newline();
        }

        self.emit_es5_async_case_label(increment_case, false);
        *case = increment_case;
        self.writer.write(&plan.index);
        self.writer.write("++;");
        self.writer.newline();
        self.writer.write("return [3 /*break*/, ");
        self.writer.write(&head_case.to_string());
        self.writer.write("];");
        self.writer.newline();
        self.emit_es5_async_case_label(exit_case, is_last);
        if is_last {
            self.writer.write(" ");
        }
        *case = exit_case;
        Ok(())
    }

    fn emit_es5_async_for_in_binding(
        &mut self,
        initializer: NodeId,
        key: &str,
    ) -> Result<(), EmitError> {
        let initializer_node = self.node(initializer)?.clone();
        let target = if let NodeData::VariableDeclarationList(list) = &initializer_node.data {
            let Some(declaration) = list.declarations.nodes.first() else {
                return Ok(());
            };
            let declaration_node = self.node(*declaration)?.clone();
            let NodeData::VariableDeclaration(declaration) = &declaration_node.data else {
                return Err(Self::unsupported(*declaration, declaration_node.kind));
            };
            declaration.name
        } else {
            initializer
        };
        self.emit_expression(target, 1)?;
        self.writer.write(" = ");
        self.writer.write(key);
        self.writer.write(";");
        self.writer.newline();
        Ok(())
    }

    #[allow(clippy::too_many_arguments, clippy::too_many_lines)]
    fn emit_es5_async_for_of_statement(
        &mut self,
        statement_id: NodeId,
        statement: &ts_ast::ForInOrOfStatementData,
        label: Option<NodeId>,
        plan: &Es5AsyncForOfPlan,
        state: &str,
        case: &mut usize,
        is_last: bool,
    ) -> Result<(), EmitError> {
        let binding = self.es5_async_for_of_binding(statement.initializer)?;
        let expression_await = self.es5_async_simple_await_in_expression(statement.expression);
        let initializer_await = self.es5_async_simple_await_in_expression(statement.initializer);
        let binding_advance = self.es5_async_for_of_binding_case_advance(statement.initializer);
        let start_case = *case;
        let head_case = start_case + usize::from(expression_await.is_some()) + 1;
        let increment_case =
            head_case + binding_advance + self.es5_async_case_advance(statement.statement) + 1;
        let exit_case = increment_case + 1;

        if !self.writer.line_start {
            self.writer.newline();
        }
        self.writer.write(&plan.counter);
        self.writer.write(" = 0");
        if let Some(await_id) = expression_await {
            self.writer.write(";");
            self.writer.newline();
            let NodeData::AwaitExpression(awaited) = &self.node(await_id)?.data else {
                unreachable!("await expression identified above")
            };
            let awaited_expression = awaited.expression;
            self.emit_es5_async_yield(awaited_expression, case, false)?;
            let previous = self
                .es5_async_expression_rewrites
                .insert(await_id, format!("{state}.sent()"));
            self.writer.write(&plan.rhs);
            self.writer.write(" = ");
            self.emit_expression(statement.expression, 1)?;
            self.writer.write(";");
            self.writer.newline();
            self.restore_es5_async_expression_rewrite(await_id, previous);
        } else {
            self.writer.write(", ");
            self.writer.write(&plan.rhs);
            self.writer.write(" = ");
            self.emit_expression(statement.expression, 1)?;
            self.writer.write(";");
            self.writer.newline();
        }
        self.writer.write(state);
        self.writer.write(".label = ");
        self.writer.write(&head_case.to_string());
        self.writer.write(";");
        self.writer.newline();

        self.emit_es5_async_case_label(head_case, false);
        *case = head_case;
        self.writer.write("if (!(");
        self.writer.write(&plan.counter);
        self.writer.write(" < ");
        self.writer.write(&plan.rhs);
        self.writer.write(".length)) return [3 /*break*/, ");
        self.writer.write(&exit_case.to_string());
        self.writer.write("];");
        self.writer.newline();

        if let Some(default) = self.es5_async_for_of_binding_default(statement.initializer)
            && let Some(await_id) = self.es5_async_simple_await_in_expression(default)
        {
            let pattern_temp = plan
                .pattern_temp
                .as_deref()
                .expect("awaited default pattern temp");
            let value_temp = plan
                .value_temp
                .as_deref()
                .expect("awaited default value temp");
            let non_default_case = head_case + 2;
            let join_case = head_case + 3;
            self.writer.write(pattern_temp);
            self.writer.write(" = ");
            self.emit_es5_async_for_of_value(plan, &binding)?;
            self.writer.write(";");
            self.writer.newline();
            self.writer.write("if (!(");
            self.writer.write(pattern_temp);
            self.writer.write(" === void 0)) return [3 /*break*/, ");
            self.writer.write(&non_default_case.to_string());
            self.writer.write("];");
            self.writer.newline();
            let NodeData::AwaitExpression(awaited) = &self.node(await_id)?.data else {
                unreachable!("await expression identified above")
            };
            let awaited_expression = awaited.expression;
            self.emit_es5_async_yield(awaited_expression, case, false)?;
            let previous = self
                .es5_async_expression_rewrites
                .insert(await_id, format!("{state}.sent()"));
            self.writer.write(value_temp);
            self.writer.write(" = ");
            self.emit_expression(default, 1)?;
            self.writer.write(";");
            self.writer.newline();
            self.restore_es5_async_expression_rewrite(await_id, previous);
            self.writer.write("return [3 /*break*/, ");
            self.writer.write(&join_case.to_string());
            self.writer.write("];");
            self.writer.newline();
            self.emit_es5_async_case_label(non_default_case, false);
            *case = non_default_case;
            self.writer.write(value_temp);
            self.writer.write(" = ");
            self.writer.write(pattern_temp);
            self.writer.write(";");
            self.writer.newline();
            self.writer.write(state);
            self.writer.write(".label = ");
            self.writer.write(&join_case.to_string());
            self.writer.write(";");
            self.writer.newline();
            self.emit_es5_async_case_label(join_case, false);
            *case = join_case;
            self.emit_expression(Self::es5_async_for_of_binding_target(&binding), 1)?;
            self.writer.write(" = ");
            self.writer.write(value_temp);
            self.writer.write(";");
            self.writer.newline();
        } else if let Some(await_id) = initializer_await {
            let NodeData::AwaitExpression(awaited) = &self.node(await_id)?.data else {
                unreachable!("await expression identified above")
            };
            let awaited_expression = awaited.expression;
            self.emit_es5_async_yield(awaited_expression, case, false)?;
            let previous = self
                .es5_async_expression_rewrites
                .insert(await_id, format!("{state}.sent()"));
            self.emit_es5_async_for_of_binding_assignment(plan, &binding)?;
            self.restore_es5_async_expression_rewrite(await_id, previous);
        } else {
            self.emit_es5_async_for_of_binding_assignment(plan, &binding)?;
        }

        let mut nodes = vec![statement_id];
        nodes.extend(label);
        self.es5_async_control_targets.push(Es5AsyncControlTarget {
            nodes,
            break_case: exit_case,
            continue_case: increment_case,
        });
        let body_result = self.emit_es5_async_branch(statement.statement, state, case);
        self.es5_async_control_targets.pop();
        body_result?;
        if self.es5_async_statement_may_complete_normally(statement.statement) {
            self.writer.write(state);
            self.writer.write(".label = ");
            self.writer.write(&increment_case.to_string());
            self.writer.write(";");
            self.writer.newline();
        }

        self.emit_es5_async_case_label(increment_case, false);
        *case = increment_case;
        self.writer.write(&plan.counter);
        self.writer.write("++;");
        self.writer.newline();
        self.writer.write("return [3 /*break*/, ");
        self.writer.write(&head_case.to_string());
        self.writer.write("];");
        self.writer.newline();
        self.emit_es5_async_case_label(exit_case, is_last);
        if is_last {
            self.writer.write(" ");
        }
        *case = exit_case;
        Ok(())
    }

    fn es5_async_for_of_binding(
        &self,
        initializer: NodeId,
    ) -> Result<Es5AsyncForOfBinding, EmitError> {
        let node = self.node(initializer)?;
        match &node.data {
            NodeData::VariableDeclarationList(list) => {
                let Some(declaration) = list.declarations.nodes.first() else {
                    return Ok(Es5AsyncForOfBinding::Direct(initializer));
                };
                let declaration_node = self.node(*declaration)?;
                let NodeData::VariableDeclaration(declaration) = &declaration_node.data else {
                    return Err(Self::unsupported(*declaration, declaration_node.kind));
                };
                Ok(Es5AsyncForOfBinding::Direct(declaration.name))
            }
            NodeData::ArrayLiteralExpression(array) => {
                let Some(element) = array.elements.nodes.first().copied() else {
                    return Ok(Es5AsyncForOfBinding::Direct(initializer));
                };
                if let NodeData::BinaryExpression(binary) = &self.node(element)?.data
                    && self
                        .arena
                        .get(binary.operator_token)
                        .is_some_and(|node| node.kind == SyntaxKind::EqualsToken)
                {
                    Ok(Es5AsyncForOfBinding::Array {
                        target: binary.left,
                        default: Some(binary.right),
                    })
                } else {
                    Ok(Es5AsyncForOfBinding::Array {
                        target: element,
                        default: None,
                    })
                }
            }
            NodeData::ObjectLiteralExpression(object) => {
                let Some(property) = object.properties.nodes.first().copied() else {
                    return Ok(Es5AsyncForOfBinding::Direct(initializer));
                };
                let property_node = self.node(property)?;
                let NodeData::ShorthandPropertyAssignment(property) = &property_node.data else {
                    return Ok(Es5AsyncForOfBinding::Direct(initializer));
                };
                Ok(Es5AsyncForOfBinding::Object {
                    target: property.name,
                    default: property.object_assignment_initializer,
                })
            }
            _ => Ok(Es5AsyncForOfBinding::Direct(initializer)),
        }
    }

    const fn es5_async_for_of_binding_target(binding: &Es5AsyncForOfBinding) -> NodeId {
        match binding {
            Es5AsyncForOfBinding::Direct(target)
            | Es5AsyncForOfBinding::Array { target, .. }
            | Es5AsyncForOfBinding::Object { target, .. } => *target,
        }
    }

    fn emit_es5_async_for_of_value(
        &mut self,
        plan: &Es5AsyncForOfPlan,
        binding: &Es5AsyncForOfBinding,
    ) -> Result<(), EmitError> {
        self.writer.write(&plan.rhs);
        self.writer.write("[");
        self.writer.write(&plan.counter);
        self.writer.write("]");
        match binding {
            Es5AsyncForOfBinding::Array { .. } => self.writer.write("[0]"),
            Es5AsyncForOfBinding::Object { .. } => {
                self.writer.write(".");
                self.emit_expression(Self::es5_async_for_of_binding_target(binding), 0)?;
            }
            Es5AsyncForOfBinding::Direct(_) => {}
        }
        Ok(())
    }

    fn emit_es5_async_for_of_binding_assignment(
        &mut self,
        plan: &Es5AsyncForOfPlan,
        binding: &Es5AsyncForOfBinding,
    ) -> Result<(), EmitError> {
        let target = Self::es5_async_for_of_binding_target(binding);
        let default = match binding {
            Es5AsyncForOfBinding::Array { default, .. }
            | Es5AsyncForOfBinding::Object { default, .. } => *default,
            Es5AsyncForOfBinding::Direct(_) => None,
        };
        if let Some(default) = default {
            let temp = plan.pattern_temp.as_deref().expect("default pattern temp");
            self.writer.write(temp);
            self.writer.write(" = ");
            self.emit_es5_async_for_of_value(plan, binding)?;
            self.writer.write(", ");
            self.emit_expression(target, 1)?;
            self.writer.write(" = ");
            self.writer.write(temp);
            self.writer.write(" === void 0 ? ");
            self.emit_expression(default, 2)?;
            self.writer.write(" : ");
            self.writer.write(temp);
        } else {
            self.emit_expression(target, 1)?;
            self.writer.write(" = ");
            self.emit_es5_async_for_of_value(plan, binding)?;
        }
        self.writer.write(";");
        self.writer.newline();
        Ok(())
    }

    #[allow(clippy::too_many_arguments, clippy::too_many_lines)]
    fn emit_es5_async_function_body(
        &mut self,
        body: NodeId,
        expression_body: Option<NodeId>,
        this_argument: &str,
        generator_this: &str,
        requested_state_parameter: &str,
        object_rest: Option<(NodeId, &str, Option<&str>)>,
        compact_outer: bool,
    ) -> Result<(), EmitError> {
        let previous_await_captures = std::mem::take(&mut self.es5_async_await_captures);
        let previous_conditional_temps = std::mem::take(&mut self.es5_async_conditional_temps);
        let previous_array_temps = std::mem::take(&mut self.es5_async_array_temps);
        let previous_call_temps = std::mem::take(&mut self.es5_async_call_temps);
        let previous_new_temps = std::mem::take(&mut self.es5_async_new_temps);
        let previous_binary_temps = std::mem::take(&mut self.es5_async_binary_temps);
        let previous_object_plans = std::mem::take(&mut self.es5_async_object_plans);
        let previous_switch_temps = std::mem::take(&mut self.es5_async_switch_temps);
        let previous_try_catch_temps = std::mem::take(&mut self.es5_async_try_catch_temps);
        let previous_with_temps = std::mem::take(&mut self.es5_async_with_temps);
        let previous_with_environments = std::mem::take(&mut self.es5_async_with_environments);
        let previous_open_with_depth = std::mem::take(&mut self.es5_async_open_with_depth);
        let previous_inline_with_environment =
            std::mem::take(&mut self.es5_async_inline_with_environment);
        let previous_hoisted_variable_lists =
            std::mem::take(&mut self.es5_async_hoisted_variable_lists);
        let previous_hoisted_function_declarations =
            std::mem::take(&mut self.es5_async_hoisted_function_declarations);
        let previous_for_of_names = std::mem::take(&mut self.es5_async_for_of_names);
        let previous_for_in_plans = std::mem::take(&mut self.es5_async_for_in_plans);
        let mut hoisted_names = Vec::new();
        let mut hoisted_functions = Vec::new();
        let mut for_of_pattern_hoists = Vec::new();
        if expression_body.is_none() {
            self.es5_async_for_of_names = self.prepare_es5_async_for_of_names(body);
            let mut for_of_nodes = Vec::new();
            self.collect_es5_async_for_of_nodes(body, &mut for_of_nodes);
            for statement in for_of_nodes {
                if let Some(temp) = self
                    .es5_async_for_of_names
                    .get(&statement)
                    .and_then(|plan| plan.pattern_temp.clone())
                {
                    for_of_pattern_hoists.push(temp);
                }
            }
            let mut hoisted_lists = HashSet::new();
            self.collect_es5_async_variable_hoists(body, &mut hoisted_lists, &mut hoisted_names);
            self.collect_es5_async_for_hoists(body, &mut hoisted_lists, &mut hoisted_names);
            self.collect_es5_async_function_hoists(body, &mut hoisted_functions);
            self.es5_async_hoisted_function_declarations =
                hoisted_functions.iter().copied().collect();
            self.es5_async_hoisted_variable_lists = hoisted_lists;
        }
        let capture_plan = if expression_body.is_none() {
            self.es5_async_capture_plan(body)
        } else {
            Es5AsyncCapturePlan {
                temps: Vec::new(),
                captures: HashMap::new(),
                conditional_temps: HashMap::new(),
                array_temps: HashMap::new(),
                call_temps: HashMap::new(),
                new_temps: HashMap::new(),
                binary_temps: HashMap::new(),
                object_plans: HashMap::new(),
                object_key_hoists: Vec::new(),
                switch_temps: HashMap::new(),
                try_catch_temps: HashMap::new(),
                try_catch_hoists: Vec::new(),
                with_temps: HashMap::new(),
                for_in_plans: HashMap::new(),
                state_parameter: None,
            }
        };
        let Es5AsyncCapturePlan {
            temps: planned_temps,
            captures: await_captures,
            conditional_temps,
            array_temps,
            call_temps,
            new_temps,
            binary_temps,
            object_plans,
            object_key_hoists,
            switch_temps,
            try_catch_temps,
            try_catch_hoists,
            with_temps,
            for_in_plans,
            state_parameter: planned_state_parameter,
        } = capture_plan;
        self.es5_async_await_captures = await_captures;
        self.es5_async_conditional_temps = conditional_temps;
        self.es5_async_array_temps = array_temps;
        self.es5_async_call_temps = call_temps;
        self.es5_async_new_temps = new_temps;
        self.es5_async_binary_temps = binary_temps;
        self.es5_async_object_plans = object_plans;
        self.es5_async_switch_temps = switch_temps;
        self.es5_async_try_catch_temps = try_catch_temps;
        self.es5_async_with_temps = with_temps;
        self.es5_async_for_in_plans = for_in_plans;
        let state_parameter = planned_state_parameter
            .as_deref()
            .unwrap_or(requested_state_parameter);
        self.writer.write("{");
        if compact_outer {
            self.writer.write(" return ");
        } else {
            self.writer.newline();
        }
        if !compact_outer {
            self.writer.indent += 1;
        }
        if !compact_outer {
            self.writer.write("return ");
        }
        self.emit_awaiter_reference();
        self.writer.write("(");
        self.writer.write(this_argument);
        self.writer.write(", void 0, void 0, function () {");
        let callback_is_indented = !compact_outer
            || object_rest.is_some()
            || (expression_body.is_none() && self.this_alias.as_deref() != Some("_a"));
        if callback_is_indented {
            self.writer.newline();
        } else {
            self.writer.write(" ");
        }
        if callback_is_indented {
            self.writer.indent += 1;
        }

        if let Some((pattern, parameter, expression_temp)) = object_rest {
            if let Some(temp) = expression_temp {
                self.writer.write("var ");
                self.writer.write(temp);
                self.writer.write(";");
                self.writer.newline();
            }
            self.emit_object_rest_parameter_prologue(pattern, parameter)?;
        } else if expression_body.is_none()
            && let Some(loop_info) = self.es5_async_captured_for_loop(body)?
        {
            self.emit_es5_async_captured_loop_hoists(&loop_info)?;
        }
        for function in &hoisted_functions {
            self.es5_async_hoisted_function_declarations
                .remove(function);
            let result = self.emit_statement(*function);
            self.es5_async_hoisted_function_declarations
                .insert(*function);
            result?;
        }
        for temp in object_key_hoists {
            self.writer.write("var ");
            self.writer.write(&temp);
            self.writer.write(";");
            self.writer.newline();
        }
        if !planned_temps.is_empty()
            || (expression_body.is_none()
                && (!hoisted_names.is_empty() || !try_catch_hoists.is_empty()))
        {
            self.writer.write("var ");
            let mut index = 0;
            for name in &planned_temps {
                if index != 0 {
                    self.writer.write(", ");
                }
                self.writer.write(name);
                index += 1;
            }
            for name in &hoisted_names {
                if index != 0 {
                    self.writer.write(", ");
                }
                self.writer.write(name);
                index += 1;
            }
            for name in &try_catch_hoists {
                if index != 0 {
                    self.writer.write(", ");
                }
                self.writer.write(name);
                index += 1;
            }
            self.writer.write(";");
            self.writer.newline();
        }
        for temp in &for_of_pattern_hoists {
            self.writer.write("var ");
            self.writer.write(temp);
            self.writer.write(";");
            self.writer.newline();
        }

        self.writer.write("return ");
        self.emit_generator_reference();
        self.writer.write("(");
        self.writer.write(generator_this);
        self.writer.write(", function (");
        self.writer.write(state_parameter);
        self.writer.write(") {");
        self.writer.newline();
        self.writer.indent += 1;

        if let Some(expression) = expression_body {
            self.emit_es5_async_expression_state_machine(
                expression,
                state_parameter,
                object_rest.and_then(|(_, _, temp)| temp),
            )?;
        } else if let Some(loop_info) = self.es5_async_captured_for_loop(body)? {
            self.emit_es5_async_captured_loop_state_machine(&loop_info, state_parameter)?;
        } else {
            self.emit_es5_async_block_state_machine(body, state_parameter)?;
        }

        self.writer.indent -= 1;
        self.writer.write("});");
        if compact_outer && !callback_is_indented {
            self.writer.write(" });");
        } else {
            self.writer.newline();
        }
        if callback_is_indented {
            self.writer.indent -= 1;
        }
        if !compact_outer {
            self.writer.write("});");
            self.writer.newline();
            self.writer.indent -= 1;
            self.writer.write("}");
        } else if callback_is_indented {
            self.writer.write("}); }");
        } else {
            self.writer.write(" }");
        }
        self.es5_async_await_captures = previous_await_captures;
        self.es5_async_conditional_temps = previous_conditional_temps;
        self.es5_async_array_temps = previous_array_temps;
        self.es5_async_call_temps = previous_call_temps;
        self.es5_async_new_temps = previous_new_temps;
        self.es5_async_binary_temps = previous_binary_temps;
        self.es5_async_object_plans = previous_object_plans;
        self.es5_async_switch_temps = previous_switch_temps;
        self.es5_async_try_catch_temps = previous_try_catch_temps;
        self.es5_async_with_temps = previous_with_temps;
        self.es5_async_with_environments = previous_with_environments;
        self.es5_async_open_with_depth = previous_open_with_depth;
        self.es5_async_inline_with_environment = previous_inline_with_environment;
        self.es5_async_hoisted_variable_lists = previous_hoisted_variable_lists;
        self.es5_async_hoisted_function_declarations = previous_hoisted_function_declarations;
        self.es5_async_for_of_names = previous_for_of_names;
        self.es5_async_for_in_plans = previous_for_in_plans;
        Ok(())
    }

    fn emit_es5_async_expression_state_machine(
        &mut self,
        expression: NodeId,
        state: &str,
        call_temp: Option<&str>,
    ) -> Result<(), EmitError> {
        let node = self.node(expression)?.clone();
        if let NodeData::CallExpression(call) = &node.data
            && call.arguments.nodes.len() == 1
            && let Some(NodeData::AwaitExpression(awaited)) = self
                .arena
                .get(call.arguments.nodes[0])
                .map(|node| &node.data)
            && let Some(temp) = call_temp
        {
            self.writer.write("switch (");
            self.writer.write(state);
            self.writer.write(".label) {");
            self.writer.newline();
            self.writer.indent += 1;
            self.writer.write("case 0:");
            self.writer.newline();
            self.writer.indent += 1;
            self.writer.write(temp);
            self.writer.write(" = ");
            self.emit_expression(call.expression, 0)?;
            self.writer.write(";");
            self.writer.newline();
            self.writer.write("return [4 /*yield*/, ");
            self.emit_expression(awaited.expression, 0)?;
            self.writer.write("];");
            self.writer.newline();
            self.writer.indent -= 1;
            self.writer.write("case 1: return [2 /*return*/, ");
            self.writer.write(temp);
            self.writer.write(".apply(void 0, [");
            self.writer.write(state);
            self.writer.write(".sent()])];");
            self.writer.newline();
            self.writer.indent -= 1;
            self.writer.write("}");
            self.writer.newline();
            return Ok(());
        }
        self.writer.write("return [2 /*return*/, ");
        self.emit_expression(expression, 0)?;
        self.writer.write("];");
        self.writer.newline();
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn es5_async_capture_plan(&mut self, body: NodeId) -> Es5AsyncCapturePlan {
        let mut await_captures = Vec::new();
        let mut conditional_nodes = Vec::new();
        let mut array_nodes = Vec::new();
        let mut call_nodes = Vec::new();
        let mut new_nodes = Vec::new();
        let mut binary_nodes = Vec::new();
        let mut object_nodes = Vec::new();
        let mut switch_nodes = Vec::new();
        let mut try_nodes = Vec::new();
        let mut with_nodes = Vec::new();
        let mut for_in_nodes = Vec::new();
        if let Some(NodeData::Block(block)) = self.arena.get(body).map(|node| &node.data) {
            for statement in &block.statements.nodes {
                self.collect_es5_async_await_captures(*statement, &mut await_captures);
                self.collect_es5_async_conditional_temps(*statement, &mut conditional_nodes);
                self.collect_es5_async_array_temps(*statement, &mut array_nodes);
                self.collect_es5_async_call_temps(*statement, &mut call_nodes);
                self.collect_es5_async_new_temps(*statement, &mut new_nodes);
                self.collect_es5_async_binary_temps(*statement, &mut binary_nodes);
                self.collect_es5_async_object_plans(*statement, &mut object_nodes);
                self.collect_es5_async_switch_plans(*statement, &mut switch_nodes);
                self.collect_es5_async_try_plans(*statement, &mut try_nodes);
                self.collect_es5_async_with_plans(*statement, &mut with_nodes);
                self.collect_es5_async_for_in_plans(*statement, &mut for_in_nodes);
            }
        }
        let mut claimed = HashSet::new();
        let mut for_of_nodes = Vec::new();
        self.collect_es5_async_for_of_nodes(body, &mut for_of_nodes);
        let mut has_suspending_for_of = false;
        for statement in for_of_nodes {
            if let Some(plan) = self.es5_async_for_of_names.get(&statement) {
                claimed.insert(plan.counter.clone());
                claimed.insert(plan.rhs.clone());
                if let Some(temp) = &plan.value_temp {
                    claimed.insert(temp.clone());
                }
                if let Some(temp) = &plan.pattern_temp {
                    claimed.insert(temp.clone());
                }
            }
            if let Some(NodeData::ForInOrOfStatement(statement)) =
                self.arena.get(statement).map(|node| &node.data)
            {
                has_suspending_for_of |= self.es5_async_for_of_suspension_count(statement) != 0;
            }
        }
        let mut temps = Vec::new();
        let mut captures = HashMap::new();
        for (await_id, capture_nodes) in await_captures {
            let entries = captures.entry(await_id).or_insert_with(Vec::new);
            for capture in capture_nodes {
                let temp = self.generate_block_temp(body, &claimed);
                claimed.insert(temp.clone());
                temps.push(temp.clone());
                entries.push((capture, temp));
            }
        }
        let mut conditional_temps = HashMap::new();
        for conditional in conditional_nodes {
            let temp = self.generate_block_temp(body, &claimed);
            claimed.insert(temp.clone());
            temps.push(temp.clone());
            conditional_temps.insert(conditional, temp);
        }
        let mut array_temps = HashMap::new();
        for array in array_nodes {
            let temp = if self.es5_async_array_needs_temp(array) {
                let temp = self.generate_block_temp(body, &claimed);
                claimed.insert(temp.clone());
                temps.push(temp.clone());
                Some(temp)
            } else {
                None
            };
            array_temps.insert(array, temp);
        }
        let mut call_temps = HashMap::new();
        for call in call_nodes {
            let mut planned = Vec::new();
            for _ in 0..self.es5_async_call_temp_count(call) {
                let temp = self.generate_block_temp(body, &claimed);
                claimed.insert(temp.clone());
                temps.push(temp.clone());
                planned.push(temp);
            }
            call_temps.insert(call, planned);
        }
        let mut new_temps = HashMap::new();
        for expression in new_nodes {
            let mut planned = Vec::new();
            for _ in 0..self.es5_async_new_temp_count(expression) {
                let temp = self.generate_block_temp(body, &claimed);
                claimed.insert(temp.clone());
                temps.push(temp.clone());
                planned.push(temp);
            }
            new_temps.insert(expression, planned);
        }
        let mut binary_temps = HashMap::new();
        for expression in binary_nodes {
            let mut planned = Vec::new();
            for _ in 0..self.es5_async_binary_temp_count(expression) {
                let temp = self.generate_block_temp(body, &claimed);
                claimed.insert(temp.clone());
                temps.push(temp.clone());
                planned.push(temp);
            }
            binary_temps.insert(expression, planned);
        }
        let mut object_plans = HashMap::new();
        let mut object_key_hoists = Vec::new();
        for object in object_nodes {
            let mut key_temps = HashMap::new();
            for key in self.es5_async_object_keys_needing_temp(object) {
                let temp = self.generate_block_temp(body, &claimed);
                claimed.insert(temp.clone());
                object_key_hoists.push(temp.clone());
                key_temps.insert(key, temp);
            }
            let temp = self.generate_block_temp(body, &claimed);
            claimed.insert(temp.clone());
            temps.push(temp.clone());
            object_plans.insert(object, Es5AsyncObjectPlan { temp, key_temps });
        }
        let mut switch_temps = HashMap::new();
        for statement in switch_nodes {
            let temp = if self.es5_async_switch_needs_cfg(statement) {
                let temp = self.generate_block_temp(body, &claimed);
                claimed.insert(temp.clone());
                temps.push(temp.clone());
                Some(temp)
            } else {
                None
            };
            switch_temps.insert(statement, temp);
        }
        let mut try_catch_temps = HashMap::new();
        let mut try_catch_hoists = Vec::new();
        for statement in try_nodes {
            let Some(NodeData::TryStatement(statement)) =
                self.arena.get(statement).map(|node| &node.data)
            else {
                continue;
            };
            let Some(catch_clause) = statement.catch_clause else {
                continue;
            };
            let Some(NodeData::CatchClause(catch)) =
                self.arena.get(catch_clause).map(|node| &node.data)
            else {
                continue;
            };
            let Some(variable) = catch.variable_declaration else {
                continue;
            };
            let Some(NodeData::VariableDeclaration(variable)) =
                self.arena.get(variable).map(|node| &node.data)
            else {
                continue;
            };
            let Some(name) = declaration_name_text(self.arena, variable.name) else {
                continue;
            };
            let temp = self.generated_names.generate(name);
            try_catch_hoists.push(temp.clone());
            try_catch_temps.insert(catch_clause, temp);
        }
        let mut with_temps = HashMap::new();
        for statement in with_nodes {
            let temp = self.generate_block_temp(body, &claimed);
            claimed.insert(temp.clone());
            temps.push(temp.clone());
            with_temps.insert(statement, temp);
        }
        let mut for_in_plans = HashMap::new();
        for statement in for_in_nodes {
            let object = self.generate_block_temp(body, &claimed);
            claimed.insert(object.clone());
            temps.push(object.clone());
            let keys = self.generate_block_temp(body, &claimed);
            claimed.insert(keys.clone());
            temps.push(keys.clone());
            let key = self.generate_block_temp(body, &claimed);
            claimed.insert(key.clone());
            temps.push(key.clone());
            let index = if !claimed.contains("_i") && !self.es5_async_block_uses_name(body, "_i") {
                "_i".to_owned()
            } else {
                self.generate_block_temp(body, &claimed)
            };
            claimed.insert(index.clone());
            temps.push(index.clone());
            for_in_plans.insert(
                statement,
                Es5AsyncForInPlan {
                    object,
                    keys,
                    key,
                    index,
                },
            );
        }
        let state_parameter = (!temps.is_empty() || has_suspending_for_of)
            .then(|| self.generate_block_temp(body, &claimed));
        Es5AsyncCapturePlan {
            temps,
            captures,
            conditional_temps,
            array_temps,
            call_temps,
            new_temps,
            binary_temps,
            object_plans,
            object_key_hoists,
            switch_temps,
            try_catch_temps,
            try_catch_hoists,
            with_temps,
            for_in_plans,
            state_parameter,
        }
    }

    fn es5_async_block_uses_name(&self, block: NodeId, name: &str) -> bool {
        let range = self.arena.get(block).map(|node| node.range);
        self.arena.iter().any(|(_, node)| {
            matches!(&node.data, NodeData::Identifier(identifier) if identifier.text == name)
                && range.is_some_and(|range| {
                    range.start <= node.range.start && node.range.end <= range.end
                })
        })
    }

    fn collect_es5_async_for_in_plans(&self, statement: NodeId, loops: &mut Vec<NodeId>) {
        let Some(node) = self.arena.get(statement) else {
            return;
        };
        match &node.data {
            NodeData::Block(block) => {
                for statement in &block.statements.nodes {
                    self.collect_es5_async_for_in_plans(*statement, loops);
                }
            }
            NodeData::ForInOrOfStatement(for_statement) => {
                if node.kind == SyntaxKind::ForInStatement
                    && self.es5_async_for_in_suspension_count(for_statement) != 0
                {
                    loops.push(statement);
                }
                self.collect_es5_async_for_in_plans(for_statement.statement, loops);
            }
            NodeData::IfStatement(statement) => {
                self.collect_es5_async_for_in_plans(statement.then_statement, loops);
                if let Some(statement) = statement.else_statement {
                    self.collect_es5_async_for_in_plans(statement, loops);
                }
            }
            NodeData::WhileStatement(statement) => {
                self.collect_es5_async_for_in_plans(statement.statement, loops);
            }
            NodeData::DoStatement(statement) => {
                self.collect_es5_async_for_in_plans(statement.statement, loops);
            }
            NodeData::ForStatement(statement) => {
                self.collect_es5_async_for_in_plans(statement.statement, loops);
            }
            NodeData::LabeledStatement(statement) => {
                self.collect_es5_async_for_in_plans(statement.statement, loops);
            }
            NodeData::WithStatement(statement) => {
                self.collect_es5_async_for_in_plans(statement.statement, loops);
            }
            NodeData::SwitchStatement(statement) => self.collect_es5_async_switch_regions(
                statement,
                loops,
                Self::collect_es5_async_for_in_plans,
            ),
            NodeData::TryStatement(statement) => self.collect_es5_async_try_regions(
                statement,
                loops,
                Self::collect_es5_async_for_in_plans,
            ),
            _ => {}
        }
    }

    fn collect_es5_async_with_plans(&self, statement: NodeId, withs: &mut Vec<NodeId>) {
        match self.arena.get(statement).map(|node| &node.data) {
            Some(NodeData::Block(block)) => {
                for statement in &block.statements.nodes {
                    self.collect_es5_async_with_plans(*statement, withs);
                }
            }
            Some(NodeData::WithStatement(with_statement)) => {
                if self.es5_async_with_suspension_count(with_statement) != 0 {
                    withs.push(statement);
                }
                self.collect_es5_async_with_plans(with_statement.statement, withs);
            }
            Some(NodeData::IfStatement(statement)) => {
                self.collect_es5_async_with_plans(statement.then_statement, withs);
                if let Some(statement) = statement.else_statement {
                    self.collect_es5_async_with_plans(statement, withs);
                }
            }
            Some(NodeData::WhileStatement(statement)) => {
                self.collect_es5_async_with_plans(statement.statement, withs);
            }
            Some(NodeData::DoStatement(statement)) => {
                self.collect_es5_async_with_plans(statement.statement, withs);
            }
            Some(NodeData::ForStatement(statement)) => {
                self.collect_es5_async_with_plans(statement.statement, withs);
            }
            Some(NodeData::ForInOrOfStatement(statement)) => {
                self.collect_es5_async_with_plans(statement.statement, withs);
            }
            Some(NodeData::LabeledStatement(statement)) => {
                self.collect_es5_async_with_plans(statement.statement, withs);
            }
            Some(NodeData::SwitchStatement(statement)) => self.collect_es5_async_switch_regions(
                statement,
                withs,
                Self::collect_es5_async_with_plans,
            ),
            Some(NodeData::TryStatement(statement)) => self.collect_es5_async_try_regions(
                statement,
                withs,
                Self::collect_es5_async_with_plans,
            ),
            _ => {}
        }
    }

    fn collect_es5_async_try_plans(&self, statement: NodeId, tries: &mut Vec<NodeId>) {
        match self.arena.get(statement).map(|node| &node.data) {
            Some(NodeData::Block(block)) => {
                for statement in &block.statements.nodes {
                    self.collect_es5_async_try_plans(*statement, tries);
                }
            }
            Some(NodeData::TryStatement(try_statement)) => {
                self.collect_es5_async_try_plans(try_statement.try_block, tries);
                if self.es5_async_try_suspension_count(try_statement) != 0 {
                    tries.push(statement);
                }
                if let Some(catch_clause) = try_statement.catch_clause
                    && let Some(NodeData::CatchClause(catch)) =
                        self.arena.get(catch_clause).map(|node| &node.data)
                {
                    self.collect_es5_async_try_plans(catch.block, tries);
                }
                if let Some(finally_block) = try_statement.finally_block {
                    self.collect_es5_async_try_plans(finally_block, tries);
                }
            }
            Some(NodeData::IfStatement(statement)) => {
                self.collect_es5_async_try_plans(statement.then_statement, tries);
                if let Some(statement) = statement.else_statement {
                    self.collect_es5_async_try_plans(statement, tries);
                }
            }
            Some(NodeData::WhileStatement(statement)) => {
                self.collect_es5_async_try_plans(statement.statement, tries);
            }
            Some(NodeData::DoStatement(statement)) => {
                self.collect_es5_async_try_plans(statement.statement, tries);
            }
            Some(NodeData::ForStatement(statement)) => {
                self.collect_es5_async_try_plans(statement.statement, tries);
            }
            Some(NodeData::LabeledStatement(statement)) => {
                self.collect_es5_async_try_plans(statement.statement, tries);
            }
            Some(NodeData::WithStatement(statement)) => {
                self.collect_es5_async_try_plans(statement.statement, tries);
            }
            Some(NodeData::SwitchStatement(statement)) => {
                if let Some(NodeData::CaseBlock(block)) =
                    self.arena.get(statement.case_block).map(|node| &node.data)
                {
                    for clause in &block.clauses.nodes {
                        if let Some(NodeData::CaseOrDefaultClause(clause)) =
                            self.arena.get(*clause).map(|node| &node.data)
                        {
                            for statement in &clause.statements.nodes {
                                self.collect_es5_async_try_plans(*statement, tries);
                            }
                        }
                    }
                }
            }
            _ => {}
        }
    }

    fn collect_es5_async_try_regions<T>(
        &self,
        statement: &ts_ast::TryStatementData,
        values: &mut T,
        collect: fn(&Self, NodeId, &mut T),
    ) {
        collect(self, statement.try_block, values);
        if let Some(catch_clause) = statement.catch_clause
            && let Some(block) = self.es5_async_catch_block(catch_clause)
        {
            collect(self, block, values);
        }
        if let Some(finally_block) = statement.finally_block {
            collect(self, finally_block, values);
        }
    }

    fn collect_es5_async_switch_regions<T>(
        &self,
        statement: &ts_ast::SwitchStatementData,
        values: &mut T,
        collect: fn(&Self, NodeId, &mut T),
    ) {
        let Some(NodeData::CaseBlock(block)) =
            self.arena.get(statement.case_block).map(|node| &node.data)
        else {
            return;
        };
        for clause in &block.clauses.nodes {
            let Some(NodeData::CaseOrDefaultClause(clause)) =
                self.arena.get(*clause).map(|node| &node.data)
            else {
                continue;
            };
            for statement in &clause.statements.nodes {
                collect(self, *statement, values);
            }
        }
    }

    fn collect_es5_async_switch_plans(&self, statement: NodeId, switches: &mut Vec<NodeId>) {
        match self.arena.get(statement).map(|node| &node.data) {
            Some(NodeData::Block(block)) => {
                for statement in &block.statements.nodes {
                    self.collect_es5_async_switch_plans(*statement, switches);
                }
            }
            Some(NodeData::IfStatement(statement)) => {
                self.collect_es5_async_switch_plans(statement.then_statement, switches);
                if let Some(statement) = statement.else_statement {
                    self.collect_es5_async_switch_plans(statement, switches);
                }
            }
            Some(NodeData::WhileStatement(statement)) => {
                self.collect_es5_async_switch_plans(statement.statement, switches);
            }
            Some(NodeData::DoStatement(statement)) => {
                self.collect_es5_async_switch_plans(statement.statement, switches);
            }
            Some(NodeData::ForStatement(statement)) => {
                self.collect_es5_async_switch_plans(statement.statement, switches);
            }
            Some(NodeData::LabeledStatement(statement)) => {
                self.collect_es5_async_switch_plans(statement.statement, switches);
            }
            Some(NodeData::WithStatement(statement)) => {
                self.collect_es5_async_switch_plans(statement.statement, switches);
            }
            Some(NodeData::TryStatement(statement)) => self.collect_es5_async_try_regions(
                statement,
                switches,
                Self::collect_es5_async_switch_plans,
            ),
            Some(NodeData::SwitchStatement(switch)) => {
                if self.es5_async_switch_suspension_count(statement) != 0 {
                    switches.push(statement);
                }
                self.collect_es5_async_switch_regions(
                    switch,
                    switches,
                    Self::collect_es5_async_switch_plans,
                );
            }
            _ => {}
        }
    }

    fn collect_es5_async_object_plans(&self, statement: NodeId, objects: &mut Vec<NodeId>) {
        match self.arena.get(statement).map(|node| &node.data) {
            Some(NodeData::Block(block)) => {
                for statement in &block.statements.nodes {
                    self.collect_es5_async_object_plans(*statement, objects);
                }
            }
            Some(NodeData::IfStatement(statement)) => {
                self.collect_es5_async_object_plans(statement.then_statement, objects);
                if let Some(statement) = statement.else_statement {
                    self.collect_es5_async_object_plans(statement, objects);
                }
            }
            Some(NodeData::WhileStatement(statement)) => {
                self.collect_es5_async_object_plans(statement.statement, objects);
            }
            Some(NodeData::DoStatement(statement)) => {
                self.collect_es5_async_object_plans(statement.statement, objects);
            }
            Some(NodeData::ForStatement(statement)) => {
                self.collect_es5_async_object_plans(statement.statement, objects);
            }
            Some(NodeData::LabeledStatement(statement)) => {
                self.collect_es5_async_object_plans(statement.statement, objects);
            }
            Some(NodeData::WithStatement(statement)) => {
                self.collect_es5_async_object_plans(statement.statement, objects);
            }
            Some(NodeData::TryStatement(statement)) => self.collect_es5_async_try_regions(
                statement,
                objects,
                Self::collect_es5_async_object_plans,
            ),
            Some(NodeData::SwitchStatement(statement)) => self.collect_es5_async_switch_regions(
                statement,
                objects,
                Self::collect_es5_async_object_plans,
            ),
            Some(NodeData::ExpressionStatement(statement)) => {
                if let Some(NodeData::BinaryExpression(binary)) =
                    self.arena.get(statement.expression).map(|node| &node.data)
                    && self
                        .arena
                        .get(binary.operator_token)
                        .is_some_and(|operator| operator.kind == SyntaxKind::EqualsToken)
                    && matches!(
                        self.arena.get(binary.right).map(|node| &node.data),
                        Some(NodeData::ObjectLiteralExpression(_))
                    )
                    && self.es5_async_object_await_count(binary.right) != 0
                {
                    objects.push(binary.right);
                }
            }
            Some(NodeData::ReturnStatement(statement)) => {
                if let Some(expression) = statement.expression
                    && matches!(
                        self.arena.get(expression).map(|node| &node.data),
                        Some(NodeData::ObjectLiteralExpression(_))
                    )
                    && self.es5_async_object_await_count(expression) != 0
                {
                    objects.push(expression);
                }
            }
            _ => {}
        }
    }

