    fn emit_amd(source: &str) -> super::EmitResult {
        emit_amd_like(source, ModuleKind::Amd)
    }

    fn emit_umd(source: &str) -> super::EmitResult {
        emit_amd_like(source, ModuleKind::Umd)
    }

    fn emit_amd_like(source: &str, module: ModuleKind) -> super::EmitResult {
        let parsed = parse_source_file(source);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let dependencies = parsed
            .amd_dependencies
            .iter()
            .map(|dependency| AmdDependency {
                path: &dependency.path,
                name: dependency.name.as_deref(),
                comment_start: dependency.range.start.get(),
                comment_end: dependency.range.end.get(),
            })
            .collect::<Vec<_>>();
        let enum_values = BTreeMap::new();
        let import_meanings = BTreeMap::new();
        emit_source_file_with_context(
            &parsed.arena,
            parsed.source_file,
            "input.ts",
            source,
            PrinterSettings {
                always_strict: false,
                target: ScriptTarget::Es2015,
                module,
                jsx: JsxEmit::Preserve,
                emit_javascript: true,
                emit_declarations: false,
                source_map: true,
                inline_source_map: false,
                import_helpers: false,
                no_emit_helpers: false,
                experimental_decorators: false,
                remove_comments: false,
                use_define_for_class_fields: None,
            },
            &EmitContext {
                bindings: &bindings,
                amd_module_name: parsed.amd_module_name.as_deref(),
                amd_bundle: false,
                preemitted_source_prologues: false,
                preemitted_shebang: false,
                suppress_extends_helper: false,
                preemitted_comment_end: None,
                preserve_top_of_file_reference_directive: false,
                amd_dependencies: &dependencies,
                amd_module_specifier_rewrites: &BTreeMap::new(),
                amd_generated_name_offsets: &BTreeMap::new(),
                enum_member_values: &enum_values,
                enum_access_values: &enum_values,
                import_runtime_meanings: &import_meanings,
                preserve_const_enums: true,
                inline_const_enums: false,
                emit_decorator_metadata: false,
                preserve_dynamic_import: false,
                isolated_modules: false,
                strict_null_checks: false,
                force_use_strict: false,
                jsx_factory: None,
                downlevel_iteration: false,
                module_detection: ModuleDetectionKind::Auto,
            },
        )
        .unwrap()
    }

    fn emit_jsx(source: &str, jsx: JsxEmit) -> String {
        let parsed = parse_jsx_source_file(source);
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        emit_source_file_with_settings(
            &parsed.arena,
            parsed.source_file,
            "input.tsx",
            source,
            PrinterSettings {
                always_strict: false,
                target: ScriptTarget::EsNext,
                module: ModuleKind::EsNext,
                jsx,
                emit_javascript: true,
                emit_declarations: false,
                source_map: false,
                inline_source_map: false,
                import_helpers: false,
                no_emit_helpers: false,
                experimental_decorators: false,
                remove_comments: false,
                use_define_for_class_fields: None,
            },
        )
        .unwrap()
        .code
    }

    #[test]
