    #[test]
    fn downlevels_async_functions_to_awaiter_for_es2015() {
        let output = emit_with(
            "async function run() { await task(); } const next = async value => await value;",
            ScriptTarget::Es2015,
            ModuleKind::None,
        )
        .code;
        assert!(output.starts_with("var __awaiter = "), "{output}");
        assert!(
            output.contains(
                "return __awaiter(this, void 0, void 0, function* () { yield task(); });"
            ),
            "{output}"
        );
        assert!(
            output.contains(
                "const next = (value) => __awaiter(void 0, void 0, void 0, function* () { return yield value; });"
            ),
            "{output}"
        );
    }

    #[test]
    fn imports_commonjs_async_helpers_from_tslib() {
        let source = "export async function foo() { await 0; }";
        let parsed = parse_source_file(source);
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let output = emit_source_file_with_settings(
            &parsed.arena,
            parsed.source_file,
            "notmodule.cts",
            source,
            PrinterSettings {
                always_strict: false,
                target: ScriptTarget::Es2015,
                module: ModuleKind::CommonJs,
                jsx: JsxEmit::Preserve,
                emit_javascript: true,
                emit_declarations: false,
                source_map: false,
                inline_source_map: false,
                import_helpers: true,
                no_emit_helpers: false,
                experimental_decorators: false,
                remove_comments: false,
                use_define_for_class_fields: None,
            },
        )
        .unwrap()
        .code;
        let marker = output.find("Object.defineProperty(exports").unwrap();
        let export = output.find("exports.foo = foo;").unwrap();
        let helper = output.find("const tslib_1 = require(\"tslib\");").unwrap();
        let function = output.find("function foo()").unwrap();
        assert!(output.starts_with("\"use strict\";\n"), "{output}");
        assert!(
            marker < export && export < helper && helper < function,
            "{output}"
        );
        assert!(output.contains("return tslib_1.__awaiter("), "{output}");
        assert!(!output.contains("var __awaiter ="), "{output}");
    }

    #[test]
    fn downlevels_instance_and_static_async_class_methods_for_es2015() {
        let output = emit_with(
            concat!(
                "class C {\n",
                "    async instance(value: Promise<number>) {\n",
                "        return await value;\n",
                "    }\n",
                "    static async load() {\n",
                "        await task();\n",
                "    }\n",
                "}",
            ),
            ScriptTarget::Es2015,
            ModuleKind::None,
        )
        .code;
        assert!(output.starts_with("var __awaiter = "), "{output}");
        assert!(
            output.contains(
                "instance(value) {\n        return __awaiter(this, void 0, void 0, function* () {\n            return yield value;\n        });\n    }"
            ),
            "{output}"
        );
        assert!(
            output.contains(
                "static load() {\n        return __awaiter(this, void 0, void 0, function* () {\n            yield task();\n        });\n    }"
            ),
            "{output}"
        );
        assert!(!output.contains("async instance"), "{output}");
        assert!(!output.contains("static async load"), "{output}");
    }

    #[test]
    fn lowers_es2015_async_object_rest_parameters_and_static_fields() {
        let object_rest = emit_with(
            "async ({ foo, bar, ...rest }) => bar(await foo);",
            ScriptTarget::Es2015,
            ModuleKind::None,
        )
        .code;
        assert!(object_rest.contains("var __rest = "), "{object_rest}");
        assert!(
            object_rest.contains("(_a) => __awaiter(void 0, void 0, void 0, function* () {\n    var { foo, bar } = _a, rest = __rest(_a, [\"foo\", \"bar\"]);\n    return bar(yield foo);\n})"),
            "{object_rest}"
        );

        let static_field = emit_with(
            "class Test { static member = async (x: string) => {}; }",
            ScriptTarget::Es2015,
            ModuleKind::None,
        )
        .code;
        assert!(
            static_field.contains("var _a;\nclass Test"),
            "{static_field}"
        );
        assert!(
            static_field.contains("}\n_a = Test;\nTest.member = (x) => __awaiter("),
            "{static_field}"
        );
    }

