    #[test]
    fn inlines_negative_const_enum_values_with_expression_precedence() {
        let source = concat!(
            "const enum E { A = -1 }\n",
            "const product = E.A * 2;\n",
            "const text = E.A.toString();\n",
        );
        let parsed = parse_source_file(source);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let accesses = parsed
            .arena
            .iter()
            .filter_map(|(id, node)| {
                let NodeData::PropertyAccessExpression(access) = &node.data else {
                    return None;
                };
                (super::declaration_name_text(&parsed.arena, access.name) == Some("A"))
                    .then_some((id, EmitConstantValue::Number(-1.0)))
            })
            .collect::<BTreeMap<_, _>>();
        let member_values = BTreeMap::new();
        let import_meanings = BTreeMap::new();
        let emitted = emit_source_file_with_context(
            &parsed.arena,
            parsed.source_file,
            "input.ts",
            source,
            PrinterSettings {
                always_strict: false,
                target: ScriptTarget::Es2015,
                module: ModuleKind::EsNext,
                jsx: JsxEmit::Preserve,
                emit_javascript: true,
                emit_declarations: false,
                source_map: false,
                inline_source_map: false,
                import_helpers: false,
                no_emit_helpers: false,
                experimental_decorators: false,
                remove_comments: false,
                use_define_for_class_fields: None,
            },
            &EmitContext {
                bindings: &bindings,
                amd_module_name: None,
                amd_bundle: false,
                preemitted_source_prologues: false,
                preemitted_shebang: false,
                suppress_extends_helper: false,
                preemitted_comment_end: None,
                preserve_top_of_file_reference_directive: false,
                amd_dependencies: &[],
                amd_module_specifier_rewrites: &BTreeMap::new(),
                amd_generated_name_offsets: &BTreeMap::new(),
                enum_member_values: &member_values,
                enum_access_values: &accesses,
                import_runtime_meanings: &import_meanings,
                preserve_const_enums: false,
                inline_const_enums: true,
                emit_decorator_metadata: false,
                preserve_dynamic_import: false,
                isolated_modules: false,
                strict_null_checks: false,
                force_use_strict: false,
                jsx_factory: None,
                downlevel_iteration: false,
                module_detection: ModuleDetectionKind::Auto,
            },
        )
        .unwrap();
        assert_eq!(
            emitted.code,
            concat!(
                "const product = -1 /* E.A */ * 2;\n",
                "const text = (-1 /* E.A */).toString();\n",
            )
        );
    }

