    #[test]
    fn lowers_named_default_classes_for_commonjs_and_preserved_es5_modules() {
        let source = "export default class Operation { run() { return 1; } }";
        let commonjs = emit_with(source, ScriptTarget::Es5, ModuleKind::CommonJs).code;
        assert!(commonjs.starts_with("\"use strict\";\n"), "{commonjs}");
        assert!(!commonjs.contains("exports.default = void 0"), "{commonjs}");
        assert!(
            commonjs.contains("var Operation = /** @class */"),
            "{commonjs}"
        );
        assert!(
            commonjs.ends_with("exports.default = Operation;\n"),
            "{commonjs}"
        );
        assert!(!commonjs.contains("export default var"), "{commonjs}");

        let preserved = emit_with(source, ScriptTarget::Es5, ModuleKind::EsNext).code;
        assert!(
            preserved.starts_with("var Operation = /** @class */"),
            "{preserved}"
        );
        assert!(
            preserved.ends_with("export default Operation;\n"),
            "{preserved}"
        );
        assert!(!preserved.contains("export default var"), "{preserved}");
    }

    #[test]
    fn avoids_user_super_names_in_es5_class_captures() {
        let output = emit_with(
            "class Base {} class Derived extends Base { constructor(_super: number) { super(); } get value() { var _super = 1; return _super; } }",
            ScriptTarget::Es5,
            ModuleKind::None,
        )
        .code;
        assert!(
            output.contains("var Derived = /** @class */ (function (_super_1) {")
                && output.contains("__extends(Derived, _super_1);")
                && output.contains("return _super_1.call(this) || this;"),
            "{output}"
        );
    }

    #[test]
    fn emits_source_prologues_before_extends_and_returns_a_final_super_call() {
        let output = emit_with(
            concat!(
                "// header\n",
                "\"use strict\";\n",
                "class Base {}\n",
                "class Derived extends Base { constructor() { ",
                "\"ngInject\"; before(); super(); } }",
            ),
            ScriptTarget::Es5,
            ModuleKind::None,
        )
        .code;
        let header = output.find("// header").unwrap();
        let prologue = output.find("\"use strict\";").unwrap();
        let helper = output.find("var __extends").unwrap();
        assert!(header < prologue && prologue < helper, "{output}");
        assert!(
            output.contains(concat!(
                "function Derived() {\n",
                "        \"ngInject\";\n",
                "        before();\n",
                "        return _super.call(this) || this;\n",
            )),
            "{output}"
        );
        assert!(
            !output.contains("var _this = _super.call(this)"),
            "{output}"
        );
    }

    #[test]
    fn captures_super_when_derived_constructor_has_post_super_work() {
        let output = emit_with(
            "class Base {} class Derived extends Base { constructor() { before(); super(); after(this); } }",
            ScriptTarget::Es5,
            ModuleKind::None,
        )
        .code;
        assert!(
            output.contains("var _this = _super.call(this) || this;"),
            "{output}"
        );
        assert!(output.contains("after(_this);"), "{output}");
        assert!(output.contains("return _this;"), "{output}");
    }

    #[test]
    fn captures_lexical_this_across_nested_es5_arrows() {
        let output = emit_with(
            "class C { method(_super: number) { // erased header\n var f = () => { // erased arrow\n return x => this; // retained statement\n }; } }",
            ScriptTarget::Es5,
            ModuleKind::None,
        )
        .code;
        assert!(output.contains("var _this = this;"), "{output}");
        assert!(
            output.contains("return function (x) { return _this; }; // retained statement"),
            "{output}"
        );
        assert!(!output.contains("erased header"), "{output}");
        assert!(!output.contains("erased arrow"), "{output}");
    }

